INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1,1,'Cowboy Bebop','Cowboy Bebop',replace('Enter a world in the distant future, where Bounty Hunters roam the solar system. Spike and Jet, bounty hunting partners, set out on journeys in an ever struggling effort to win bounty rewards to survive.\n\n\nWhile traveling, they meet up with other very interesting people. Could Faye, the beautiful and ridiculously poor gambler, Edward, the computer genius, and Ein, the engineered dog be a good addition to the group?','\n',char(10)),8.6,'TV',2,0,'24 min','Sunrise','SPRING 1998','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1-GCsPm7waJ4kS.png','["Action","Adventure","Drama","Sci-Fi"]',476640,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(6,6,'TRIGUN','Trigun',replace('Vash the Stampede is a wanted man with a habit of turning entire towns into rubble. The price on his head is a fortune, and his path of destruction reaches across the arid wastelands of a desert planet. Unfortunately, most encounters with the spiky-haired gunslinger don''t end well for the bounty hunters who catch up with him; someone almost always gets hurt - and it''s never Vash.\n\n\n\nOddly enough, for such an infamous fugitive, there''s no proof that he''s ever taken a life. In fact, he''s a pacifist with a doughnut obsession who''s more doofus than desperado. There''s a whole lot more to him than his reputation lets on - Vash the Stampede definitely ain''t your typical outlaw.\n\n\n\n(Source: Funimation)','\n',char(10)),8,'TV',2,0,'24 min','MADHOUSE','SPRING 1998','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx6-wd4saT1JzStH.jpg','["Action","Adventure","Comedy","Drama","Sci-Fi"]',173646,1794735120,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(19,19,'MONSTER','Monster',replace('Dr. Kenzo Tenma is a renowned Japanese brain surgeon working at a leading hospital in Germany. One night, Dr. Tenma risks his reputation and career to save the life of a critically wounded young boy over that of the town mayor who had been planning to support the hospital financially. A string of mysterious murders begin to occur soon after the operation, and Dr. Tenma emerges as the primary suspect despite no incriminating evidence. \n\n\n\nA doctor is taught to believe that all life is equal; however, when another series of murders occur in the surgeon''s vicinity, Dr. Tenma''s beliefs are shaken as his actions that night are shown to have much broader consequences than he could have imagined. Leaving behind his life as a surgeon he embarks on a journey across the country to unravel the mystery of the boy he saved.','\n',char(10)),8.8,'TV',2,0,'24 min','MADHOUSE','SPRING 2004','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx19-gtMC64182sm4.jpg','["Drama","Horror","Mystery","Psychological","Thriller"]',351856,1794735119,74,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20,20,'NARUTO','Naruto',replace('Naruto Uzumaki, a hyperactive and knuckle-headed ninja, lives in Konohagakure, the Hidden Leaf village. Moments prior to his birth, a huge demon known as the Kyuubi, the Nine-tailed Fox, attacked Konohagakure and wreaked havoc. In order to put an end to the Kyuubi''s rampage, the leader of the village, the 4th Hokage, sacrificed his life and sealed the monstrous beast inside the newborn Naruto. \n\n\nShunned because of the presence of the Kyuubi inside him, Naruto struggles to find his place in the village. He strives to become the Hokage of Konohagakure, and he meets many friends and foes along the way. \n\n\n(Source: MAL Rewrite)','\n',char(10)),8,'TV',2,0,'23 min','Studio Pierrot','FALL 2002','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20-dE6UHbFFg1A5.jpg','["Action","Adventure","Comedy","Drama","Fantasy","Supernatural"]',741667,1794735119,220,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21,21,'ONE PIECE','ONE PIECE',replace('Gold Roger was known as the Pirate King, the strongest and most infamous being to have sailed the Grand Line. The capture and death of Roger by the World Government brought a change throughout the world. His last words before his death revealed the location of the greatest treasure in the world, One Piece. It was this revelation that brought about the Grand Age of Pirates, men who dreamed of finding One Piece (which promises an unlimited amount of riches and fame), and quite possibly the most coveted of titles for the person who found it, the title of the Pirate King.\n\n\nEnter Monkey D. Luffy, a 17-year-old boy that defies your standard definition of a pirate. Rather than the popular persona of a wicked, hardened, toothless pirate who ransacks villages for fun, Luffy’s reason for being a pirate is one of pure wonder; the thought of an exciting adventure and meeting new and intriguing people, along with finding One Piece, are his reasons of becoming a pirate. Following in the footsteps of his childhood hero, Luffy and his crew travel across the Grand Line, experiencing crazy adventures, unveiling dark mysteries and battling strong enemies, all in order to reach One Piece.\n\n\n*This includes the following special episodes:\n\n- Chopperman to the Rescue! Protect the TV Station by the Shore! (Episode 336)\n\n- The Strongest Tag-Team! Luffy and Toriko''s Hard Struggle! (Episode 492)\n\n- Team Formation! Save Chopper (Episode 542)\n\n- History''s Strongest Collaboration vs. Glutton of the Sea (Episode 590)\n\n- 20th Anniversary! Special Romance Dawn (Episode 907)','\n',char(10)),8.7,'TV',1,7,'24 min','Toei Animation','FALL 1999','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21-ELSYx3yMPcKM.jpg','["Action","Adventure","Comedy","Drama","Fantasy"]',770120,1794782800,0,1798985760,1181);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(30,30,'Shin Seiki Evangelion','Neon Genesis Evangelion',replace('In the year 2015, the Angels, huge, tremendously powerful, alien war machines, appear in Tokyo for the second time. The only hope for Mankind''s survival lies in the Evangelion, a humanoid fighting machine developed by NERV, a special United Nations agency. Capable of withstanding anything the Angels can dish out, the Evangelion''s one drawback lies in the limited number of people able to pilot them. Only a handful of teenagers, all born fourteen years ago, nine months after the Angels first appeared, are able to interface with the Evangelion. One such teenager is Shinji Ikari, whose father heads the NERV team that developed and maintains the Evangelion. Thrust into a maelstrom of battle and events that he does not understand, Shinji is forced to plumb the depths of his own inner resources for the courage and strength to not only fight, but to survive, or risk losing everything. \n\n\n(Source: AniDB)\n\n\n\n Note: Later releases include edited versions of Episodes 21-24 called the "Director''s Cut" with some visual editing and adding extra scenes that previously appeared in the theatrical recap ''Death''.','\n',char(10)),8.3,'TV',2,0,'24 min','GAINAX','FALL 1995','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx30-AI1zr74Dh4ye.jpg','["Action","Drama","Mecha","Mystery","Psychological","Sci-Fi"]',506166,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(32,32,'Shin Seiki Evangelion Movie: Air / Magokoro wo, Kimi ni','Neon Genesis Evangelion: The End of Evangelion',replace('NERV faces a brutal attack from SEELE, but with Asuka in a coma, and Shinji in a nervous breakdown, things soon turn into the surreal. This movie provides a concurrent ending to the final two episodes of the show Neon Genesis Evangelion.\n\n\n\n(Source: IMDb)','\n',char(10)),8.6,'MOVIE',2,0,'87 min','GAINAX','SUMMER 1997','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx32-5JYsv0wc122I.jpg','["Action","Drama","Mecha","Psychological","Sci-Fi"]',258897,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(33,33,'Kenpuu Denki Berserk','Berserk',replace('Set during a time that very much resembles Europe during the Middle Ages, Berserk is a story of revenge set in the castle town of Midland. Recently, the town has seen the rise of a wicked king, who uses demonic minions to control and victimise his subjects.\n\n\n\nHowever, when a lone soldier enters the town calling himself the Black Swordsman and armed to the teeth, many sense that the king''s days of unchecked oppression are over. Soon, the Black Swordsman is plying his trade by hunting down the king''s evil servants, giving no quarter, and preparing to exact his vengeance on the king.\n\n\n\n(Source: MVM Entertainment)','\n',char(10)),8.4,'TV',2,0,'25 min','OLM','FALL 1997','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx33-PSwfE5B0gejI.jpg','["Action","Adventure","Drama","Fantasy","Horror","Supernatural"]',190437,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(43,43,'GHOST IN THE SHELL: Koukaku Kidoutai','Ghost in the Shell',replace('2029: A female cybernetic government agent, Major Motoko Kusanagi, and the Internal Bureau of Investigations are hot on the trail of “The Puppet Master,” a mysterious and threatening computer virus capable of infiltrating human hosts. Together with her fellow agents from Section 9, Kusanagi embarks on a high-tech race against time to capture the omnipresent entity.\n\n\n\n(Source: Lionsgate Films)','\n',char(10)),8,'MOVIE',2,0,'83 min','Production I.G','FALL 1995','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx43-Y6EjeEMM14dj.png','["Action","Psychological","Sci-Fi"]',180882,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(47,47,'AKIRA','Akira',replace('It''s the year 2019, thirty-one years have passed since the start of World War III. A top-secret child with amazing powers of the mind breaks free from custody and accidentally gets a motorcycle gang involved in the project. This incident triggers psychic powers within one of the gang members, Tetsuo, and he is taken by the army to be experimented on. His mind has been altered and is now on the path of war, seeking revenge on the society that once called him weak. \n\n\n(Source: FUNimation)','\n',char(10)),7.9,'MOVIE',2,0,'125 min','Tokyo Movie Shinsha','SUMMER 1988','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx47-4CR68arv452h.jpg','["Action","Adventure","Horror","Psychological","Sci-Fi","Supernatural"]',236462,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(121,121,'Hagane no Renkinjutsushi','Fullmetal Alchemist',replace('The rules of alchemy state that to gain something, one must lose something of equal value. Alchemy is the process of taking apart and reconstructing an object into a different entity, with the rules of alchemy to govern this procedure. However, there exists an object that can bring any alchemist above these rules, the object known as the Philosopher''s Stone. The young Edward Elric is a particularly talented alchemist who through an accident years back lost his younger brother Alphonse and one of his legs. Sacrificing one of his arms as well, he used alchemy to bind his brother''s soul to a suit of armor. This lead to the beginning of their journey to restore their bodies, in search for the legendary Philosopher''s Stone.\n\n\n\nNote: Episodes 11, 12 and 37 were adapted from the light novel "Fullmetal Alchemist: The Land of Sand."','\n',char(10)),7.9,'TV',2,0,'25 min','bones','FALL 2003','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx121-zjmixZ428Mwv.png','["Action","Adventure","Drama","Fantasy"]',271301,1794735119,51,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(164,164,'Mononoke-hime','Princess Mononoke',replace('A calm village residing in the mountains comes under attack from a demon-possessed boar one day.\n\n\nAshitaka, a young man and prince of the tribe, engages the creature in an attempt to save his village. During the battle, the boar bites him on the arm, leaving it blackened and cursed. Following his village''s traditions, Ashitaka is exiled and becomes a wanderer, looking for a solution to the curse before it engulfs him.\n\n\nIron Town is a fortress under the leadership of Lady Eboshi. Through the clearing of the surrounding forests, Iron Town produces large amounts of Ironsand, used for gunpowder and other machinery. However, because of the forests destruction, nearby animal clans seek revenge led by a human girl of the Wolf clan called San.\n\n\nWhen Ashitaka comes to Iron Town, he discovers the area consumed in battle. Horrified, he attempts to create peace and befriend the Wolf Clan. However, after the forest''s eradication and the ongoing war between Human and Beast, will the Spirit of the Forest be forgiving and accept Ashitaka''s request to expel his curse?\n\n\n[Written by MAL Rewrite]','\n',char(10)),8.5,'MOVIE',2,0,'134 min','Studio Ghibli','SUMMER 1997','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx164-ySuGzCWVw2cL.jpg','["Action","Adventure","Drama","Fantasy"]',308112,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(199,199,'Sen to Chihiro no Kamikakushi','Spirited Away','On the way to their new home, 10-year-old Chihiro Ogino''s family stumbles upon a deserted theme park. Intrigued, the family investigates the park, though unbeknownst to them, it is secretly inhabited by spirits who sleep by day and appear at night. When Chihiro''s mother and father eat food from a restaurant in the street, angry spirits turn them into pigs. Furthermore, a wide sea has appeared between the spirit world and the human one, trapping Chihiro, the sole human, in a land of spirits. Luckily for her though, a mysterious boy named Haku appears, claiming to know her from the past. Under his instructions, Chihiro secures a job in the bathhouse where Haku works. With only her courage and some new found friends to aid her, Chihiro embarks on a journey to turn her parents back to their original forms and return home.',8.6,'MOVIE',2,0,'125 min','Studio Ghibli','SUMMER 2001','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx199-sWefXJvXkDOb.jpg','["Adventure","Drama","Fantasy","Supernatural"]',489915,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(205,205,'Samurai Champloo','Samurai Champloo',replace('Let''s break it down. Mugen''s a reckless sword-slinger with a style that''s more b-boy than Shaolin. He''s got a nasty streak that makes people want to stick a knife in his throat. Then there''s Jin, a deadbeat ronin who speaks softly but carries a big blade. He runs game old-school style, but he can make your blood spray with the quickness. When these roughnecks bring the ruckus, it ain''t good for anybody, especially them. Enter Fuu, the ditzy waitress who springs her new friends from a deadly jam. All she wants in return is help solving a riddle from her past. She and the boys are tracking the scent, but there''s 99 ways to die between them and the sunflower samurai.\n\n\n\n(Source: Funimation)','\n',char(10)),8.4,'TV',2,0,'24 min','Manglobe','SPRING 2004','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx205-7tHVFu6dPBm9.png','["Action","Adventure","Comedy"]',285809,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(223,223,'Dragon Ball','Dragon Ball',replace('Goku Son is a young boy who lives in the woods all alone—that is until a girl named Bulma runs into him in her search for a set of magical objects called the "Dragon Balls." Since the artifacts are said to grant one wish to whoever collects all seven, Bulma hopes to gather them and wish for a perfect boyfriend. Goku happens to be in possession of a dragon ball, but unfortunately for Bulma, he refuses to part ways with it, so she makes him a deal: he can tag along on her journey if he lets her borrow the dragon ball''s power. With that, the two set off on the journey of a lifetime.\n\n\n\nThey don''t go on the journey alone. On the way, they meet the old Muten-Roshi and wannabe disciple Kuririn, with whom Goku trains to become a stronger martial artist for the upcoming World Martial Arts Tournament. However, it''s not all fun and games; the ability to make any wish come true is a powerful one, and there are others who would do much worse than just wishing for a boyfriend. To stop those who would try to abuse the legendary power, they train to become stronger fighters, using their newfound strength to help the people around them along the way.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'25 min','Toei Animation','WINTER 1986','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx223-scE5uJfXqqj8.png','["Action","Adventure","Comedy","Fantasy","Sci-Fi","Supernatural"]',239843,1794735119,153,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(226,226,'Elfen Lied','Elfen Lied',replace(replace('The Diclonius, a mutated homosapien that is said to be selected by God and will eventually become the destruction of mankind, possess two horns on their heads and have a "sixth sense" which gives them telekinetic abilities. Due to this dangerous power, they have been captured and isolated in laboratories by the government. Lucy, a young and psychotic Diclonius, manages to break free of her confines and brutally murders most of the guards in the laboratory where she is being held, only to be shot in the head as she makes her escape. She survives, falling off a cliff into the ocean and manages to drift along to a beach where two teenagers, Kouta and Yuka, discover her. Having lost her memories, she was named after the only thing that she can now say, "Nyuu," and the two allow her to stay at Kouta''s home. However, it appears that the psychotic side of Lucy is not dead just yet... \n\n\r\n(Source: ANN - Revised)','\r',char(13)),'\n',char(10)),6.8,'TV',2,0,'25 min','ARMS','SUMMER 2004','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx226-MibyRKhIrnTe.png','["Action","Drama","Ecchi","Horror","Psychological","Romance","Supernatural"]',281374,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(227,227,'FLCL','FLCL',replace('Naota is a detached sixth grader afflicted by the pangs of puberty. He''s fooling around with his brother''s ex-girlfriend when a crazed girl on a motor scooter runs him over, brains him with a bass guitar, and moves into his house. This pink-haired girl, Haruko - who claims she''s an alien - hurls Naota into the middle of a mega-corporation''s secret agenda. Oh, and now giant battling robots shoot from his skull. Mix in mind-bending animation and tunes that echo through your cerebellum to top off the trip that will have you falling hard for FLCL.\n\n\n\n(Source: Funimation)','\n',char(10)),7.9,'OVA',2,0,'25 min','GAINAX','SPRING 2000','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx227-qOB9ZhVvNnqO.jpg','["Action","Comedy","Mecha","Sci-Fi"]',210717,1794735120,6,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(235,235,'Meitantei Conan','Detective Conan',replace('Kudo Shinichi is a seventeen year-old high school detective whom people call the "Modern Sherlock Holmes." However, one night after a date with his childhood sweetheart, Ran, Shinichi witnessed an illegal trade and, caught off his guard, was knocked unconscious and fed a drug that was supposed to kill him... but he woke up and found himself shrunken to a seven year-old. In order to track down the men who did this to him, Shinichi hid his identity and lived with Ran, whose father happened to be a hopeless detective, and with that came a series of murders and mysteries that he must solve. \n\n\n(Source: Anime News Network)\n\n\n\nNote:\n\n- Includes Keisatsu Gakkou-hen - Wild Police Story in episodes 1029, 1038, 1042, 1061\n\n- Episodes 11, 52, 76, 118, 162, 184, 208, 342, 356, 449, 452, 487, 488, 489, 490, 515, 516, 521, 522, 651, 734, 804, 805, 927, 928, 1187 aired with a runtime of ~50 minutes as opposed to the standard 25 minute long episode.\n\n- Episodes 96, 129, 174, 219, 263, 304, 383, 479 aired with a runtime of ~90 minutes as opposed to the standard 25 minute long episode.\n\n- Episode 345, 425 aired with a runtime of ~115 minutes as opposed to the standard 25 minute long episode.','\n',char(10)),8.2,'TV',1,6,'25 min','TMS Entertainment','WINTER 1996','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx235-MyYT7K3chBdO.jpg','["Adventure","Comedy","Mystery","Psychological"]',81597,1794782800,0,1795251600,1221);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(245,245,'GTO','GTO: Great Teacher Onizuka',replace('Onizuka is a reformed biker gang leader who has his sights set on an honorable new ambition: to become the world''s greatest teacher... for the purpose of meeting sexy high school girls. Okay, so he''s mostly reformed.\n\n\nHowever, strict administrators and a class of ruthless delinquents stand between Onizuka and his goal and they will use any means, however illegal or low, to drive the new teacher away. Perfect, because Onizuka''s methods won''t be found in any teaching manual; he cares about the difference between legal and illegal activities about as much as he cares for the age difference between himself and a high school girl.\n\n\nSo get ready for math that doesn''t add up, language you''d be slapped for using, and biology that would make a grown man blush... unless of course, you''re the Great Teacher Onizuka.\n\n\n\n Note: Episode 1 has an airtime of 48 minutes.','\n',char(10)),8.4,'TV',2,0,'25 min','Studio Pierrot','SUMMER 1999','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx245-NcQAyTipUMeO.jpg','["Comedy","Drama","Slice of Life"]',179536,1794735120,43,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(249,249,'Inuyasha','InuYasha',replace('Kagome Higurashi, an average ninth grader, gets pulled into an ancient well by a demon, bringing her 500 years in the past to the feudal era. There, she meets Inuyasha, a half-demon who seeks the Shikon Jewel to make himself a full-fledged demon. With Inuyasha and new friends, Kagome''s search for the Jewel of Four Souls begins...\n\n\n\n(Source: VIZ Media)','\n',char(10)),7.7,'TV',2,0,'24 min','Sunrise','FALL 2000','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx249-jVBkyLnBvnRE.png','["Action","Adventure","Comedy","Fantasy","Romance"]',176160,1794735120,167,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(269,269,'BLEACH','Bleach',replace('Ichigo Kurosaki is a rather normal high school student apart from the fact he has the ability to see ghosts. This ability never impacted his life in a major way until the day he encounters the Shinigami Kuchiki Rukia, who saves him and his family''s lives from a Hollow, a corrupt spirit that devours human souls. \n\n\n\nWounded during the fight against the Hollow, Rukia chooses the only option available to defeat the monster and passes her Shinigami powers to Ichigo. Now forced to act as a substitute until Rukia recovers, Ichigo hunts down the Hollows that plague his town.','\n',char(10)),7.9,'TV',2,0,'24 min','Studio Pierrot','FALL 2004','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx269-d2GmRkJbMopq.png','["Action","Adventure","Supernatural"]',537485,1794735119,366,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(339,339,'serial experiments lain','Serial Experiments Lain',replace('We''re all connected... There is the world around us, a world of people, tactile sensation, and culture. There is the wired world, inside the computer, of images, personalities, virtual experiences, and a culture all of its own. The day after a classmate commits suicide, Lain, a 14-year-old girl, discovers how closely the two worlds are linked when she receives an e-mail from the dead girl: I just abandoned my body. I still live here...\n\n\n\nHas the line between the real world and the wired world begun to blur?\n\n\n\n(Source: Geneon Entertainment)','\n',char(10)),8,'TV',2,0,'23 min','Triangle Staff','SUMMER 1998','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx339-xF2wp1NQuQ4r.png','["Drama","Mystery","Psychological","Sci-Fi","Supernatural"]',259498,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(356,356,'Fate/stay night','Fate/stay night',replace('Raised by a mysterious sorcerer after the death of his parents in a catastrophic fire, Shirou Emiya has only just begun to learn small tidbits of magic. When he is caught in a battle between two powerful Magi, however, he ends up performing a spell above his expected ability, accidentally summoning a beautiful woman knight to protect him.\n\n\n\nShirou is thus unwillingly thrust into the competition known as the Holy Grail War where Seven Magi called Masters, together with their spirit partners called Servants, fight to acquire a powerful artifact said to grant every wish.\n\n\n\nNote: Based on the first route from TYPE-MOON''s visual novel of the same name, while incorporating elements of both the second and third routes.','\n',char(10)),6.8,'TV',2,0,'24 min','Studio DEEN','WINTER 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx356-mTpMvtillumS.png','["Action","Fantasy","Romance","Supernatural"]',192311,1794735120,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(431,431,'Howl no Ugoku Shiro','Howl‘s Moving Castle',replace(replace('Sophie, a quiet girl working in a hat shop, finds her life thrown into turmoil when she is literally swept off her feet by a handsome but mysterious wizard named Howl. The vain and vengeful Witch of the Waste, jealous of their friendship, puts a spell on Sophie. In a life-changing adventure, Sophie climbs aboard Howl''s magnificent flying castle and enters a magical world on a quest to break the spell. \n\n\r\n(Source: Disney)','\r',char(13)),'\n',char(10)),8.5,'MOVIE',2,0,'119 min','Studio Ghibli','FALL 2004','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx431-o8Lj3XkjHm2k.jpg','["Adventure","Drama","Fantasy","Romance"]',370736,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(437,437,'PERFECT BLUE','Perfect Blue',replace('Rising pop star Mima has quit singing to pursue a career as an actress and model, but her fans aren’t ready to see her go... Encouraged by her managers, Mima takes on a recurring role on a popular TV show, when suddenly her handlers and collaborators begin turning up murdered. Harboring feelings of guilt and haunted by visions of her former self, Mima’s reality and fantasy meld into a frenzied paranoia. As her stalker closes in, in person and online, the threat he poses is more real than even Mima knows, in this iconic psychological thriller that has frequently been hailed as one of the most important animated films of all time.\n\n\n\n(Source: Shout! Factory)\n\n\n\nNote: The film received an early premiere at the Fantasia Film Festival on August 5, 1997.','\n',char(10)),8.5,'MOVIE',2,0,'82 min','MADHOUSE','WINTER 1998','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx437-69NMlXKFeuse.jpg','["Drama","Horror","Psychological","Thriller"]',250863,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(457,457,'Mushishi','MUSHI-SHI',replace('Neither good nor evil, they are life in its purest form. Vulgar and strange, they have inspired fear in humans since the dawn of time and have, over the ages, come to be known as "mushi." The stories of the Mushi and the people they affect are all linked together by a traveling Mushi-shi, or "Mushi Master," who seeks rare Mushi sightings and uses his shaman-like knowledge of Mushi to help the affected people.\n\n\n\nWhat are the Mushi and what do they want?\n\n\n\n(Source: Funimation)','\n',char(10)),8.5,'TV',2,0,'25 min','Artland','FALL 2005','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx457-l6cTtNgI9Bi6.png','["Adventure","Fantasy","Mystery","Psychological","Slice of Life","Supernatural"]',197845,1794735120,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(512,512,'Majo no Takkyuubin','Kiki''s Delivery Service',replace('Kiki is an enterprising young girl who must follow tradition to become a full-fledged witch. Venturing out with only her chatty black cat, Jiji, Kiki flies off for the adventure of a lifetime. Landing in a far-off city, she sets up a high-flying delivery service and begins a wonderful experience of independence and responsibility as she finds her place in the world.\n\n\n(Source: Disney)','\n',char(10)),8.1,'MOVIE',2,0,'105 min','Studio Ghibli','SUMMER 1989','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx512-UwP8X4BR8YoM.png','["Adventure","Drama","Fantasy","Slice of Life"]',190213,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(523,523,'Tonari no Totoro','My Neighbor Totoro',replace('Follow the adventures of Satsuki and her four-year-old sister Mei when they move into a new home in the countryside. To their delight they discover that their new neighbor is a mysterious forest spirit called Totoro who can be seen only through the eyes of a child. Totoro introduces them to extraordinary characters, including a cat that doubles as a bus, takes them on a journey through the wonders of nature. \n\n\n(Source: Disney)','\n',char(10)),8.1,'MOVIE',2,0,'86 min','Studio Ghibli','SPRING 1988','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx523-fErBvxOHP7IX.jpg','["Adventure","Fantasy","Slice of Life","Supernatural"]',285801,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(578,578,'Hotaru no Haka','Grave of the Fireflies',replace('In the aftermath of a World War II bombing, two orphaned children struggle to survive in the Japanese countryside. To Seita and his four-year-old sister, the helplessness and indifference of their countrymen is even more painful than the enemy raids. Through desperation, hunger and grief, these children''s lives are as heartbreakingly fragile as their spirit and love is inspiring.\n\n\n(Source: Sentai Filmworks)','\n',char(10)),8.3,'MOVIE',2,0,'88 min','Studio Ghibli','SPRING 1988','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx578-vU6XcOlb1XFU.jpg','["Drama"]',207090,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(777,777,'HELLSING OVA','Hellsing Ultimate',replace('Hellsing, a secret organization of the British government, has long been battling supernatural threats to keep the people safe from creatures of the night. The current leader, Integra Wingates Hellsing controls her own personal army to eliminate the undead beings, but even her highly trained soldiers pale in comparison to her most trusted vampire exterminator, a man by the name of Alucard, who is actually a powerful vampire himself. Along with Integra''s mysterious butler and Alucard''s new vampire minion, Seras Victoria, The Hellsing Organization must face not only regular ghouls and vampires, but a rivaling secret organization from the Vatican, and Millennium, an enigmatic group of madmen spawned by a certain war over 50 years ago...\n\nA bloody battle between monsters is about to begin, the dead are dancing, and all hell is singing...','\n',char(10)),8.1,'OVA',2,0,'50 min','MADHOUSE','WINTER 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx777-F6547pSAR2Zd.jpg','["Action","Horror","Supernatural"]',190073,1794735120,10,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(813,813,'Dragon Ball Z','Dragon Ball Z',replace('Goku is back with his new son, Gohan, but just when things are getting settled down, the adventures continue. Whether he is facing enemies such as Freeza, Cell, or Boo, Goku is proven to be an elite of his own and discovers his race, Saiyan. He meets many new people, gaining allies as well as enemies, as he still finds time to raise a family and be the happy-go-lucky Saiyan he is.\n\n\n(Source: Anime News Network)','\n',char(10)),8.1,'TV',2,0,'24 min','Toei Animation','SPRING 1989','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx813-ZhnFNOeCU5dQ.png','["Action","Adventure","Comedy","Fantasy","Supernatural"]',264856,1794735119,291,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(849,849,'Suzumiya Haruhi no Yuuutsu','The Melancholy of Haruhi Suzumiya',replace('Kyon, your typical high school student, has long given up his belief in the supernatural. However, upon meeting Haruhi Suzumiya, he quickly finds out that it is the supernatural that she is interested in; aliens, time travelers and espers among other things. When Haruhi laments about the lack of intriguing clubs around school, Kyon inspires Haruhi to form her own club. As a result, the SOS Brigade is formed, a club which specializes in all that is the supernatural.\n\n\nMuch to his chagrin, Kyon, along with the silent bookworm, Yuki Nagato, the shy and timid Mikuru Asahina, and the perpetually smiling Itsuki Koizumi, are recruited as members. The story follows the crazy adventures that these four endure under their whimsical leader, Haruhi. The story is based on the light novels by Nagaru Tanigawa.\n\n\nNote: This entry is for the original 14-episode 2006 airing. The series was further expanded and reordered into a 28-episode series in 2009.','\n',char(10)),7.6,'TV',2,0,'23 min','Kyoto Animation','SPRING 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx849-wQM3GqLvl62P.png','["Comedy","Mystery","Sci-Fi","Slice of Life","Supernatural"]',204357,1794735120,14,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(853,853,'Ouran Koukou Host Club','Ouran High School Host Club',replace('Fujioka Haruhi wins a scholarship to attend Ouran Academy, a school reserved for only the most rich and prestigious. Despite what other students may think of her, she cares little for physical appearances or the fact that she is a commoner.\n\n\nUnfortunately for Haruhi, her high school days take a sudden turn when she stumbles upon the Host Club, an elite club filled with super rich and beautiful boys who use their specific traits and charms to entertain young ladies. Even worse, Haruhi accidentally breaks an 8-million yen vase in the club. Since she is unable to repay her debt with money, Haruhi finds herself with no choice but to work for the Host Club, becoming a male host herself.','\n',char(10)),8,'TV',2,0,'24 min','bones','SPRING 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx853-fiUtW8yohsSF.jpg','["Comedy","Drama","Romance","Slice of Life"]',263040,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(877,877,'NANA','NANA',replace('Two twenty-somethings seemingly share nothing in common apart from their first name, but a chance meeting on a train bound for Tokyo sets Nana Komatsu and Nana Oosaki on a collision course with destiny. Nana Komatsu, a love-at-first-sight dreamer, aims to find enduring happiness in the big city. Nana Oosaki, neo punk rock vocalist, pursues her burning ambitions of musical stardom and worldwide fame. As their fates increasingly intertwine, they each chase their dreams — until the harsh realities of life in big city Tokyo threaten to tear everything apart.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),8.5,'TV',2,0,'23 min','MADHOUSE','SPRING 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx877-6BUYEWp8By8j.png','["Drama","Music","Romance","Slice of Life"]',212931,1794735120,47,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(889,889,'BLACK LAGOON','Black Lagoon','Okajima Rokuro is a Japanese businessman in a town full of Japanese businessmen. His normal day consists of social drinking with clients and being kicked around by his bosses. He finally gets a break though, as he''s sent by his company to the tropical seas of Eastern China to deliver a disc. But his boat gets hijacked by a band of mercenaries hired to retrieve the disc. Rock (as he is newly dubbed by his captors) catches the interest of the only female merc Revy as she thinks he''s worth a ransom, taking him hostage. However, the disc that was stolen has a terrible secret that''s unknown to Rock, which causes massive confusion and chaos for both him and his kidnappers.',7.8,'TV',2,0,'24 min','MADHOUSE','SPRING 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx889-4S7N2ciq2cwA.png','["Action","Adventure","Drama","Thriller"]',257516,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(918,918,'Gintama','Gintama',replace('Life isn''t easy in feudal Japan... especially since the aliens landed and conquered everything! Oh sure, the new health care is great, but the public ban on the use of swords has left a lot of defeated samurai with a difficult decision to make concerning their future career paths! This is especially true if, as in the case of Gintoki Sakata, they''re not particularly inclined towards holding a day job, which is why Gintoki''s opted for the freelance route, taking any job that''s offered to him as long as the financial remuneration sounds right. Unfortunately, in a brave new world filled with stray bug-eyed monsters, upwardly mobile Yakuza and overly ambitious E.T. entrepreneurs, those jobs usually don''t pay as well as they should for the pain, suffering and indignities endured!\n\n\n(Source: Sentai Filmworks)','\n',char(10)),8.5,'TV',2,0,'25 min','Sunrise','SPRING 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx918-iOaeBVUn4uK7.jpg','["Action","Comedy","Drama","Sci-Fi"]',301822,1794735119,201,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(934,934,'Higurashi no Naku Koro ni','When They Cry','After moving into the quiet town of Hinamizawa, Maebara Keiichi spends his days blissfully in school often playing games with his local friends. However, appearances can be deceiving. One fateful day, Keiichi stumbles upon news of a murder that had occurred in Hinamizawa. From this point on, horrific events unfold in front of Keiichi, as he soon learns his close friends may not be all that they seem. Based on the amateur mystery game by 07th Expansion, the story is told in a series of different scenarios.',7.6,'TV',2,0,'24 min','Studio DEEN','SPRING 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx934-wjMlVEl4CWwg.jpg','["Horror","Mystery","Psychological","Supernatural","Thriller"]',180849,1794735120,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(966,966,'Crayon Shin-chan','Shin Chan',replace('Crayon Shin-chan follows the wacky antics and adventures of five-year-old Shinnosuke "Shin" Nohara and his parents, neighbors, and friends and is set in Kasukabe, Saitama Prefecture, Japan.\n\n\nMany of the jokes in the series stem from Shin-chan''s occasionally weird, unnatural and inappropriate use of language, as well as from his inappropriate behavior. A typical gag involves Shin-chan confounding his parents by using the wrong phrase for the occasion; for example, saying "Welcome back!" instead of "I am back!" when he comes home.\n\n\nDuring the beginning of the series, the TV show was mostly based on the storyline in the original manga. As the show progressed, more and more episodes became anime-original.','\n',char(10)),7.7,'TV',1,6,'21 min','Shin-Ei Animation','SPRING 1992','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b966-QUCdKAk4ls9J.jpg','["Comedy","Ecchi","Slice of Life"]',20427,1794782800,0,1795246200,1362);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1199,1199,'Nintama Rantarou','忍たま乱太郎',replace('Rantarou, Shinbei and Kirimaru are ninja apprentices in the Ninja Gakuen, where first grade ones are called "Nintamas" (contraction of the words ninja+tama (egg). They must learn everything a ninja must know, but as for our heroes, money, food or playing are more interesting. The series show the everyday adventures of our heroes, segmentated in a cartoon fashion, like 2 small episodes in a 30-min show. The cast also includes the teachers (Doi-sensei and crossdressing Yamada-sensei), nintama kunoichis, evil guys (Dokutake ninjas) and even family members of all the cast...\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.5,'TV',1,0,'24 min','-','SPRING 1993','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1199-qguxpAkhdzap.png','["Comedy"]',2260,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1210,1210,'NHK ni Youkoso!','Welcome to the N-H-K',replace('Satou’s life – or what’s left of it – is a paranoid mess of conspiracy theories and social anxieties. He’s terrified of the outside world; his apartment is overflowing with the remnants of cheap take-out food; and his retinas have been permanently scarred by a steady diet of internet porn. But maybe it’s not all his fault. After all, the nefarious N-H-K is out there, and they’re determined to turn society’s fringe-dwellers into a brainwashed lot of jobless, hopeless, futureless recluses.\n\n\n\nEnter Misaki – a mysterious girl-next-door type who is Satou’s last chance to beat down his inner demons and venture out into the light of day. She’s ready to help him overcome his crippling phobias, but Satou would rather cower in his existential foxhole and pretend to work on the demo for his virtual sex game.\n\n\n\nHe’s afraid to face the world. She’s strangely desperate to fix a total stranger. Maybe together they can be normal.\n\n\n\n(Source: Funimation)','\n',char(10)),8.2,'TV',2,0,'24 min','GONZO','SUMMER 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1210-2XotjcgqdcaX.jpg','["Comedy","Drama","Psychological","Romance","Slice of Life"]',208224,1794735120,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1535,1535,'DEATH NOTE','Death Note',replace('Light Yagami is a genius high school student who is about to learn about life through a book of death. When a bored shinigami, a God of Death, named Ryuk drops a black notepad called a Death Note, Light receives power over life and death with the stroke of a pen. Determined to use this dark gift for the best, Light sets out to rid the world of evil… namely, the people he believes to be evil. Should anyone hold such power?\n\n\n\nThe consequences of Light’s actions will set the world ablaze.\n\n\n\n(Source: VIZ Media)','\n',char(10)),8.4,'TV',2,0,'23 min','MADHOUSE','FALL 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1535-kUgkcrfOrkUM.jpg','["Mystery","Psychological","Supernatural","Thriller"]',983233,1794735119,37,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1575,1575,'Code Geass: Hangyaku no Lelouch','Code Geass: Lelouch of the Rebellion',replace('On August 10th of the year 2010 the Holy Empire of Britannia began a campaign of conquest, its sights set on Japan. Operations were completed in one month thanks to Britannia''s deployment of new mobile humanoid armor vehicles dubbed Knightmare Frames. Japan''s rights and identity were stripped away, the once proud nation now referred to as Area 11. Its citizens, Elevens, are forced to scratch out a living while the Britannian aristocracy lives comfortably within their settlements. Pockets of resistance appear throughout Area 11, working towards independence for Japan.\n\n\n Lelouch, an exiled Imperial Prince of Britannia posing as a student, finds himself in the heart of the ongoing conflict for the island nation. Through a chance meeting with a mysterious girl named C.C., Lelouch gains his Geass, the power of the king. Now endowed with absolute dominance over any person, Lelouch may finally realize his goal of bringing down Britannia from within!\n\n\n(Source: Bandai Entertainment)','\n',char(10)),8.5,'TV',2,0,'24 min','Sunrise','FALL 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1575-hsmWM2ydNm1m.jpg','["Action","Drama","Mecha","Sci-Fi","Thriller"]',513751,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1689,1689,'Byousoku 5 Centimeter','5 Centimeters per Second',replace('Tohno Takaki and Shinohara Akari, two very close friends and classmates, are torn apart when Akari''s family is transferred to another region of Japan due to her family''s job. Despite separation, they continue to keep in touch through mail. When Takaki finds out that his family is also moving, he decides to meet with Akari one last time.\n\n\nAs years pass by, they continue down their own paths, their distance slowly growing wider and their contact with one another fades. Yet, they keep remembering one another and the times they have shared together, wondering if they will have the chance to meet once again.','\n',char(10)),7.1,'MOVIE',2,0,'22 min','CoMix Wave','WINTER 2007','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1689-rJKhjLEjQHSy.jpg','["Drama","Romance","Slice of Life"]',254423,1794735119,3,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1735,1735,'NARUTO: Shippuuden','Naruto: Shippuden',replace('Naruto: Shippuuden is the continuation of the original animated TV series Naruto. The story revolves around an older and slightly more matured Uzumaki Naruto and his quest to save his friend Uchiha Sasuke from the grips of the snake-like Shinobi, Orochimaru. After 2 and a half years Naruto finally returns to his village of Konoha, and sets about putting his ambitions to work, though it will not be easy, as he has amassed a few (more dangerous) enemies, in the likes of the shinobi organization; Akatsuki. \n\n\n(Source: Anime News Network)','\n',char(10)),8.2,'TV',2,0,'23 min','Studio Pierrot','WINTER 2007','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1735-kGfVm0YqCPcu.png','["Action","Adventure","Comedy","Drama","Fantasy","Supernatural"]',623555,1794735119,500,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(1960,1960,'Sore Ike! Anpanman','それいけ!アンパンマン',replace('One night, a Star of Life falls down the chimney of a bakery nestled deep in the forest, causing the dough in the oven to come to life. The dough becomes Anpanman, a superhero made of anpan (a sweet roll with bean jam filling). Together with his friends, Anpanman fights his rival Baikinman and helps the malnourished.\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.5,'TV',1,0,'24 min','TMS Entertainment','FALL 1988','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1960-ueSmUxBXWuFK.jpg','["Comedy","Fantasy"]',1446,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2001,2001,'Tengen Toppa Gurren Lagann','Gurren Lagann',replace('In a far away future, mankind lives underground in huge caves, unknowing of a world above with a sky and stars.\n\n\nIn the small village of Jiha, Simon, a shy boy who works as a digger discovers a strange glowing object during excavation. The enterprising Kamina, a young man with a pair of rakish sunglasses and the passion of a firey sun, befriends Simon and forms a small band of brothers, the Gurren Brigade, to escape the village and break through the ceiling of the cave to reach the surface, which few believe exist.\n\n\nThe village elder won''t hear of such foolishness and punishes the Brigade. However, when disaster strikes from the world above and the entire village is in jeopardy, it''s up to Simon, Kamina, a girl with a big gun named Yoko, and the small yet sturdy robot, Lagann, to save the day.\n\n\nThe new friends journey to the world above and find that the surface is a harsh battlefield, and it''s up to them to fight back against the rampaging Beastmen to turn the tide in the humans'' favor! Pierce the heavens, Gurren Lagann!','\n',char(10)),8.5,'TV',2,0,'24 min','GAINAX','SPRING 2007','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2001-XwRnjzGeFWRQ.png','["Action","Comedy","Drama","Mecha","Romance","Sci-Fi"]',389391,1794735119,27,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2025,2025,'DARKER THAN BLACK: Kuro no Keiyakusha','Darker than Black',replace('In Tokyo, an impenetrable field known as "Hell''s Gate" appeared ten years ago. At the same time, psychics who wield paranormal powers at the cost of their conscience also emerged. Hei is one of the most powerful of these psychic agents, and along with his blind associate, Yin, works for one of the many rival agencies vying to unlock the mysteries of Hell''s Gate.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.7,'TV',2,0,'24 min','bones','SPRING 2007','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b2025-ZKVteVzUyFLH.png','["Action","Mystery","Sci-Fi"]',180079,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2167,2167,'CLANNAD','Clannad',replace('Tomoya is a bitter, third year high school student. His mother passed away, causing his father to resort to alcohol and gambling. Tomoya is distant with his father and has become a delinquent in the years since his mother''s death. Walking to school, he meets Nagisa Furukawa who is a year older but is repeating the grade due to illness. She is alone, as most of her friends have moved on. The two begin hanging out, and as time goes by, Tomoya finds his life shifting in a new direction.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.7,'TV',2,0,'24 min','Kyoto Animation','FALL 2007','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2167-pSDBcyc0vjej.jpg','["Comedy","Drama","Romance","Slice of Life","Supernatural"]',306462,1794735119,23,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2236,2236,'Toki wo Kakeru Shoujo','The Girl Who Leapt Through Time',replace('The power to travel through time... It can be used for the good of humanity, or just selfishly abused. While many may fantasize about obtaining such a power, it has become nothing less than reality for otherwise-normal schoolgirl Konno Makoto.\n\n\nAfter a fated event, her life takes a turn for the extraordinary. Though she initially uses her power to literally "leap" into the past and change little things in order to make her life easier, she soon has to face the fact that changing the past can have drastic consequences.','\n',char(10)),7.8,'MOVIE',2,0,'97 min','MADHOUSE','SUMMER 2006','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2236-tH5fWFkHyVGg.png','["Drama","Romance","Sci-Fi"]',177412,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2251,2251,'Baccano!','Baccano!',replace('During the early 1930s in Chicago, the transcontinental train, Flying Pussyfoot, is starting its legendary journey that will leave a trail of blood all over the country. At the same time in New York, the ambitious scientist Szilard and his unwilling aide Ennis, are looking for missing bottles of the immortality elixir. In addition, a war between the mafia groups is getting worse. On board the Advena Avis, in 1711, alchemists are about to learn the price of immortality.\n\n\nBased on the award winning light novels of the same name, this anime adaptation follows several events that initially seem unrelated, both in time and place, but are part of a much bigger story&mdash;one of alchemy, survival and immortality. Merging these events together are the kindhearted would-be thieves, Isaac and Miria, connecting various people, all of them with their own hidden ambitions and agendas, and creating lifelong bonds and consequences for everyone involved.\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.1,'TV',2,0,'25 min','Brain''s Base','SUMMER 2007','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2251-tTQoWxVy4472.jpg','["Action","Mystery","Supernatural"]',192644,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2406,2406,'Sazae-san','サザエさん','The main character is a mother named Sazae-san. She lives in a house with her husband, her kid, her siblings and her parents. The show is the ultimate family program and tends to follow traditional themes. Think of this show as the Japanese equivalent to "The Partridge Family" and you''ll get a good feel for this show''s atmosphere. Don''t expect to see things like violence, swearing, kung-fu action or magical girls. The plots are more like "Today, Sazae-san goes to the new mall and gets lost". Such "boring" plotlines and the simplistic art are often a turn-off to non-Japanese audiences, but most Japanese find the show incredibly good. As a result, it continues to be one of the top ratings grabbers on TV and is one of the few anime that is considered "acceptable" by adults.',5.6,'TV',1,7,'24 min','Eiken','FALL 1969','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2406-nP8NIct9Sci3.jpg','["Comedy","Slice of Life"]',2574,1794782800,0,1795339800,2859);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2890,2890,'Gake no Ue no Ponyo','Ponyo',replace(replace('A young boy named Sosuke rescues a goldfish named Ponyo, and they embark on a fantastic journey of friendship and discovery before Ponyo''s father, a powerful sorcerer, forces her to return to her home in the sea. But Ponyo''s desire to be human upsets the delicate balance of nature and triggers a gigantic storm. Only Ponyo''s mother, a beautiful sea goddess, can restore nature''s balance and make Ponyo''s dreams come true. \n\n\r\n(Source: Disney)','\r',char(13)),'\n',char(10)),8,'MOVIE',2,0,'101 min','Studio Ghibli','SUMMER 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2890-wcNtFr6aUYOR.jpg','["Adventure","Fantasy"]',191848,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2904,2904,'Code Geass: Hangyaku no Lelouch R2','Code Geass: Lelouch of the Rebellion R2','A year has passed since "The Black Rebellion" and the remaining Black Knights have vanished into the shadows, their leader and figurehead, Zero, executed by the Britannian Empire. Area 11 is once more squirming under the Emperor''s oppressive heel as the Britannian armies concentrate their attacks on the European front. But for the Britannians living in Area 11, life is back to normal. On one such normal day, a Britannian student, skipping his classes in the Ashford Academy, sneaks out to gamble on his chess play. But unknown to this young man, several forces are eying him from the shadows, for soon, he will experience a shocking encounter with his own obscured past, and the masked rebel mastermind Zero will return.',8.7,'TV',2,0,'24 min','Sunrise','SPRING 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2904-Fet9Q33suC7G.jpg','["Action","Drama","Mecha","Sci-Fi","Thriller"]',370965,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(2966,2966,'Ookami to Koushinryou','Spice and Wolf','The peddler Kraft Lawrence travels through the world selling all kinds of things. After visiting a village, he discovers a sleeping girl under the pelts in his cart. She has wolf ears and a tail. The wolf girl explains that she has been called a "god", but that her name is Holo and nothing more. Lawrence teases the girl a little, but after hearing more of her story, he is moved and decides to accompany her further north. On their travels the two have many adventures, often getting into trouble, but the bond between them grows stronger.',8,'TV',2,0,'24 min','Imagin','WINTER 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2966-AEULMyYA9WKb.png','["Adventure","Fantasy","Romance","Slice of Life"]',184772,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(3588,3588,'Soul Eater','Soul Eater',replace('Set in the Shinigami technical school for weapon meisters, the series revolves around 3 groups of each a weapon meister and a human weapon. Trying to make the latter a "Death Scythe" which is the highest title for a weapon and thus fit for use by the Shinigami, they must collect the souls of 99 evil humans and 1 witch.\n\n\nMaka &amp; Soul Eater, Black Star &amp; Tsubaki, and Death the Kid with Patty and Liz Thompson are the characters Soul Eater revolves around. Besides taking the time to gather souls, these students of Shibusen defend Death City from some of the most powerful of creatures while still attending school and trying to become stronger.','\n',char(10)),7.7,'TV',2,0,'24 min','bones','SPRING 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx3588-fSMggQoFSbUI.png','["Action","Adventure","Comedy","Fantasy","Supernatural"]',402218,1794735119,51,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(4181,4181,'CLANNAD: After Story','Clannad: After Story',replace('A few months have passed since Tomoya declared his love to Nagisa, and his life keeps moving forward as he continues to meet a variety of new people, expanding his world in the process. While Tomoya''s world continues to expand, his and Nagisa''s relationship is entering a new phase, and neither of them is quite sure where it will take them. Through his relationship with Nagisa, Tomoya begins to understand the meaning and importance of family.\n\n\n\nBut as Tomoya and Nagisa begin a family of their own, they are faced with many hardships along the way in Clannad: After Story\n\n\n\n(Source: Sentai Filmworks, edited)\n\n\n\nNote: Includes 2 un-numbered ''extra'' and ''summary'' episodes that aired at the end of the series.','\n',char(10)),8.8,'TV',2,0,'24 min','Kyoto Animation','FALL 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4181-zUKE7BZC62OF.png','["Drama","Romance","Slice of Life","Supernatural"]',227499,1794735120,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(4224,4224,'Toradora!','Toradora!',replace('Ryuuji Takasu is a gentle high school student with a love for housework; but in contrast to his kind nature, he has an intimidating face that often gets him labeled as a delinquent. On the other hand is Taiga Aisaka, a small, doll-like student, who is anything but a cute and fragile girl. Equipped with a wooden katana and feisty personality, Taiga is known throughout the school as the "Palmtop Tiger."\n\n\n\nOne day, an embarrassing mistake causes the two students to cross paths. Ryuuji discovers that Taiga actually has a sweet side: she has a crush on the popular vice president, Yuusaku Kitamura, who happens to be his best friend. But things only get crazier when Ryuuji reveals that he has a crush on Minori Kushieda—Taiga''s best friend!\n\n\n\nToradora! is a romantic comedy that follows this odd duo as they embark on a quest to help each other with their respective crushes, forming an unlikely alliance in the process.','\n',char(10)),7.7,'TV',2,0,'24 min','J.C.STAFF','FALL 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4224-PXVMBLNwy2aF.jpg','["Comedy","Drama","Romance","Slice of Life"]',552053,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(4459,4459,'Ojarumaru','Prince Mackaroo',replace('In the Heian era, around 1000 years ago, a young boy of noble family named Ojarumaru is bored with his life of privilege. Meanwhile, three demons steal the power-stick of Enma, king of demons, and then lose it. Ojarumaru finds it, and uses it to transport himself to the present time. Here, he is befriended by a young boy named Kazuma, and becomes a member of his family. As time goes on, Ojarumaru makes many new friends, while dodging the comedic efforts of the three demons, Akane, Kisuke, and Aobee, as they try to recover the stick. \n\n\n\n(Source: Anime News Network)','\n',char(10)),5.7,'TV_SHORT',1,0,'10 min','Studio Gallop','FALL 1998','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/4459.jpg','["Adventure","Comedy","Fantasy"]',693,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(4654,4654,'Toaru Majutsu no Index','A Certain Magical Index','Set in a city of scientifically advanced superhuman students, but in a world where magic is also real. Touma Kamijou&rsquo;s right hand, the Imagine Breaker, will negate all magic, psychic, or divine powers, but not his own bad luck. One day he finds a young girl hanging on his balcony railing. She turns out to be a nun from the Church of England, and her mind has been implanted with the Index-Librorum-Prohibitorum - all the magical texts the Church has removed from circulation.',7,'TV',2,0,'23 min','J.C.STAFF','FALL 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4654-ba44icsxDQZd.jpg','["Action","Sci-Fi","Supernatural"]',194457,1794735120,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(4898,4898,'Kuroshitsuji','Black Butler',replace('In Victorian-era Europe, a young boy loses everything he once held near and dear to a vicious plot. In his moment of death, he strikes a deal with a demon: his soul, in exchange for revenge. Ciel Phantomhive is now the head of the Phantomhive corporation, handling all business affairs as well as the underground work for the Queen of England. His new partner is a demon butler, Sebastian Michaelis, whose powers as a butler is only surpassed by his strength as a demon.\n\n\nThe story follows the two along with their other servants, as they work to unravel the plot behind Ciel''s parents'' murder, and the horrendous tragedies that befell Ciel in the month directly after.','\n',char(10)),7.2,'TV',2,0,'24 min','A-1 Pictures','FALL 2008','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx4898-mW4gabZvwmLC.jpg','["Action","Comedy","Fantasy","Mystery","Supernatural"]',265283,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(5081,5081,'Bakemonogatari','Bakemonogatari',replace('First season of the Monogatari Series, part 1/6. Contains the arcs Hitagi Crab, Mayoi Snail, Suruga Monkey, Nadeko Snake, and Tsubasa Cat from the Bakemonogatari light novels.\n\n\nThanks to Meme Oshino, Koyomi Araragi, a high school student, is able to remain a human after coming across a female vampire... However, since the incident, Koyomi seems to meet girls who have an apparition-related issue. Hitagi Senjougahara doesn’t weigh anything, Suruga Kanbaru’s right arm becomes like that of a monkey’s, and a young girl, Mayoi, cannot find her way home no matter how many times she tries. Koyomi, a Mr. Nice Guy, ends up helping each and every girl solve her problem with the help of Meme Oshino.\n\n\n\n(Source: Aniplex)\n\n\nNote: Only the first 12 episodes were broadcast on television; the remaining three episodes were distributed on the anime''s website between November 3, 2009, and June 25, 2010.','\n',char(10)),8.2,'TV',2,0,'24 min','Shaft','SUMMER 2009','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5081-9GocceQ5Z865.jpg','["Comedy","Drama","Mystery","Psychological","Romance","Supernatural"]',348382,1794735119,15,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(5114,5114,'Hagane no Renkinjutsushi: FULLMETAL ALCHEMIST','Fullmetal Alchemist: Brotherhood',replace('"In order for something to be obtained, something of equal value must be lost."\n\n\n\nAlchemy is bound by this Law of Equivalent Exchange—something the young brothers Edward and Alphonse Elric only realize after attempting human transmutation: the one forbidden act of alchemy. They pay a terrible price for their transgression—Edward loses his left leg, Alphonse his physical body. It is only by the desperate sacrifice of Edward''s right arm that he is able to affix Alphonse''s soul to a suit of armor. Devastated and alone, it is the hope that they would both eventually return to their original bodies that gives Edward the inspiration to obtain metal limbs called "automail" and become a state alchemist, the Fullmetal Alchemist.\n\n\n\nThree years of searching later, the brothers seek the Philosopher''s Stone, a mythical relic that allows an alchemist to overcome the Law of Equivalent Exchange. Even with military allies Colonel Roy Mustang, Lieutenant Riza Hawkeye, and Lieutenant Colonel Maes Hughes on their side, the brothers find themselves caught up in a nationwide conspiracy that leads them not only to the true nature of the elusive Philosopher''s Stone, but their country''s murky history as well. In between finding a serial killer and racing against time, Edward and Alphonse must ask themselves if what they are doing will make them human again... or take away their humanity.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),9,'TV',2,0,'25 min','bones','SPRING 2009','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5114-nSWCgQlmOMtj.jpg','["Action","Adventure","Drama","Fantasy"]',744418,1794735119,64,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(5680,5680,'K-ON!','K-ON!',replace('Hirasawa Yui, a young, carefree girl entering high school, has her imagination instantly captured when she sees a poster advertising the ‘Light Music Club’. Being the carefree girl that she is, she quickly signs up. However, Yui has a problem, she is unable to play an instrument.\n\n\nWhen Yui goes to the clubroom to explain, she''s greeted by the other members: Ritsu, Mio and Tsumugi. Although disheartened at Yui’s lack of musical know-how, they still try to convince her to stay to prevent the club’s disbandment. After playing Yui a short piece which re-ignites her imagination, they succeed in keeping their new member and guitarist.\n\n\nAlong with the tasks of school and homework, Yui begins to learn the guitar with the help of the other band members, experiencing many mishaps along the way. However, with the school-festival drawing near and Yui getting stuck with her practice, will the Light Music Club be ready in time for their debut?\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'24 min','Kyoto Animation','SPRING 2009','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5680-r3AI3Cwfv0Aq.png','["Comedy","Music","Slice of Life"]',284969,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(6045,6045,'Kimi ni Todoke','Kimi ni Todoke: From Me to You','Kuronuma Sawako is completely misunderstood by her classmates. Her timid and sweet demeanor is often mistaken for malicious behavior. This is due to her resemblance to the ghost girl from "The Ring", which has led her peers to give her the nickname Sadako. Longing to make friends and live a normal life, she is naturally drawn to Kazehaya Shouta, the most popular guy in class, whose "100% refreshing" personality earns him great admiration from Sawako. So when Kazehaya starts talking to her, maybe there is hope for the friendships Sawako has always longed for. Maybe...there is even a little hope for some romance in her future.',7.9,'TV',2,0,'23 min','Production I.G','FALL 2009','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx6045-JujXjoWtslUM.jpg','["Comedy","Drama","Romance","Slice of Life"]',257023,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(6149,6149,'Chibi Maruko-chan (1995)','Chibi Maruko-chan',replace('Momoko Sakura is an elementary school student who likes popular idol Momoe Yamaguchi and mangas. She is often called "Chibi Maruko-chan" due to her young age and small size. She lives together with her parents, her grandparents and her elder sister in a little town. In school, she has many friends with whom she studies and plays together everyday, including her close pal, Tama-chan; the student committee members, Maruo-kun and Migiwa-san; and the B-class trio: ''little master'' Hanawa-kun, Hamaji-Bu Taro and Sekiguchi-kun. This is a fun-loving and enjoyable anime that portrays the simple things in life.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.1,'TV',1,0,'23 min','-','SUMMER 1995','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b6149-w9IRcMlFkn4i.jpg','["Comedy","Slice of Life"]',1911,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(6547,6547,'Angel Beats!','Angel Beats!',replace('Otonashi wakes up in the afterlife to find out he has no memories of his life before death. Desperate to survive in a war that could yield another unfortunate fate, he joins the SSS in the battle against Angel, whose very mission is to destroy all inhabitants of this afterlife. As Otonashi struggles to recover his memory and learn more about this world, he finds that not all is as it had seemed.\n\n\n(Source: Funimation)','\n',char(10)),7.7,'TV',2,0,'24 min','P.A.WORKS','SPRING 2010','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx6547-SYexAn5aFyss.png','["Action","Comedy","Drama","Supernatural"]',450271,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(6702,6702,'FAIRY TAIL','Fairy Tail',replace('Across the Fiore kingdom, wizards join guilds and make their pay by filling magical needs—but one guild has a reputation as the roughest, rowdiest, most dangerous of all: Fairy Tail!\n\nWhen four young Fairy Tail members unite, their bond is forged by a power found in neither muscle nor magic and grows stronger with every mission. Whatever you do, don''t mess with these friends or you''ll get a taste of Natsu''s flaming fist or Gray''s ice hammer, suffer a painful blow from one of Lucy''s celestial spirits or catch the edge of Erza''s mighty blade! Whether they''re stopping demons from devastating the world or wrestling in the mess hall, this mystical team manages to inflict as much damage to their rivals as they do to the surrounding area!\n\n\n\n(Source: Funimation)','\n',char(10)),7.2,'TV',2,0,'24 min','Satelight','FALL 2009','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b6702-KI4qgSMyI8Pm.png','["Action","Adventure","Comedy","Fantasy"]',387098,1794735119,175,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(6746,6746,'Durarara!!','Durarara!!',replace('In Tokyo''s downtown district of Ikebukuro, amidst many strange rumors and warnings of anonymous gangs and dangerous occupants, one urban legend stands out above the rest—the existence of a headless "Black Rider" who is said to be seen driving a jet-black motorcycle through the city streets.\n\n\nRyuugamine Mikado has always longed for the excitement of the city life, and an invitation from a childhood friend convinces him to move to Tokyo. Witnessing the Black Rider on his first day in the city, his wishes already seem to have been granted. But as supernatural events begin to occur, ordinary citizens like himself, along with Ikebukuro''s most colorful inhabitants, are mixed up in the commotion breaking out in their city.\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'24 min','Brain''s Base','WINTER 2010','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx6746-3LTwM95Uqeoa.png','["Action","Mystery","Supernatural"]',298386,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(6880,6880,'Deadman Wonderland','Deadman Wonderland',replace('Ganta is the only survivor after a mysterious man in red slaughters a classroom full of teenagers. He''s framed for the carnage, sentenced to die, and locked away in the most twisted prison ever built: Deadman Wonderland. And then it gets worse. \n\n\nAt Deadman Wonderland, convicts are forced into brutal deathmatches for the amusement of the masses, the cheers of the crowd drowning out the screams of the dismembered. Even when Ganta befriends Shiro, an unusual female inmate, his dark fate crushes all hope &mdash;until he discovers the strange ability to wield his spilled blood as a weapon. Ganta learns his new skill might be related to the murderous man in red and uncovers disturbing secrets that could expose those who stole his freedom. He''s determined to see justice served &mdash;but first he''ll have to fight for his life in a prison that holds a million ways to die. \n\n\n(Source: FUNimation)','\n',char(10)),6.7,'TV',2,0,'24 min','Manglobe','SPRING 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx6880-qZ1jIqIYpST2.png','["Action","Drama","Sci-Fi","Supernatural"]',253788,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(7054,7054,'Kaichou wa Maid-sama!','Maid-Sama!',replace('Being the first female student council president isn''t easy, especially when your school just transitioned from an all boys high school to a co-ed one. Aptly nicknamed "Demon President" by the boys for her strict disciplinary style, Misaki Ayuzawa is not afraid to use her mastery of Aikido techniques to cast judgment onto the hordes of misbehaving boys and defend the girls at Seika High School.\n\n\n\nYet even the perfect Ayuzawa has an embarrassing secret—she works part-time as a maid at a maid café to help her struggling family pay the bills. She has managed to keep her job hidden from her fellow students and maintained her flawless image as a stellar student until one day, Takumi Usui, the most popular boy in school, walks into the maid café. He could destroy her reputation with her secret... or he could twist the student council president around his little finger and use her secret as an opportunity to get closer to her.\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'24 min','J.C.STAFF','SPRING 2010','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx7054-GW4D7VAZG19W.png','["Comedy","Drama","Romance"]',293350,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(7791,7791,'K-ON!!','K-ON! Season 2',replace('It is the new year, which means that the senior members of the Light Music Club are now third-years, with Azusa Nakano being the only second-year. The seniors soon realize that Azusa will be the only member left once they graduate and decide to recruit new members. Despite trying many methods of attracting underclassmen—handing out fliers, bringing people into the clubroom, and performing at the welcoming ceremony—there are no signs of anyone that plans to join.\n\n\n\nWhile heading to the clubroom, Azusa overhears Yui Hirasawa say that the club is fine with only five people and that they can do many fun things together. Changing her mind, she decides that they do not need to recruit any members for the time being.\n\n\n\nK-On!! revolves around the members of the Light Music Club as they experience their daily high school life. From rehearsing for concerts to just messing around, they are ready to make their last year together an exciting one!\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.2,'TV',2,0,'24 min','Kyoto Animation','SPRING 2010','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx7791-4tnomla2mMDp.png','["Comedy","Music","Slice of Life"]',170091,1794735120,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(8074,8074,'Gakuen Mokushiroku: HIGHSCHOOL OF THE DEAD','High School of the Dead',replace('The lockers are splattered with blood, the student bodies are piling up and that''s not mystery meat they''re eating in the cafeteria… it''s the faculty! And that''s just the start of the worst day of school ever when a nightmarish virus is unleashed, turning humans into flesh eating zombies and converting Fujimi High School into a literal hell on Earth. Now it''s a crash course in survival, and the only test or skill that matters is the ability to keep moving, breathing and fighting. Because if nerds, jocks and the surviving staff can''t find a way to work together to escape this carnal house of education, they''re all going to end up on the menu. And that''s assuming there''s anyplace safe left to escape to.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),6.7,'TV',2,0,'24 min','MADHOUSE','SUMMER 2010','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx8074-YB63Ik96fjPj.png','["Action","Drama","Ecchi","Horror","Romance","Supernatural"]',292041,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(8336,8336,'Hanakappa','はなかっぱ','Story about Kappa with flowers on their heads.',5.2,'TV_SHORT',1,0,'10 min','Xebec','SPRING 2010','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b8336-BJzIHFC49RWb.jpg','["Comedy"]',410,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(8687,8687,'Doraemon (2005)','ドラえもん (2005)','A new Doraemon series produced by the same team as the 1979 series (in association with Studio Pierrot) with new voice actors and staff and updated character designs.',7.7,'TV',1,6,'25 min','Shin-Ei Animation','SPRING 2005','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b8687-bBnJMGnih4PT.jpg','["Adventure","Comedy","Sci-Fi"]',8113,1794782800,0,1795248000,942);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(9253,9253,'Steins;Gate','Steins;Gate',replace('Self-proclaimed mad scientist Okabe Rintarou lives in a small room in Akihabara, where he invents "future gadgets" with fellow lab members Shiina Mayuri, his air-headed childhood friend, and Hashida Itaru, an otaku hacker. The three pass the time by tinkering with their latest creation, a "Phone Microwave" that can be controlled through text messages. \n\n\n\nThe lab members soon face a string of mysterious incidents that lead to a game-changing discovery: the Phone Microwave can send emails to the past and thus alter history. Adapted from the critically acclaimed visual novel by 5pb. and Nitroplus, Steins;Gate takes Okabe to the depths of scientific theory and human despair as he faces the dire consequences of changing the past.','\n',char(10)),8.9,'TV',2,0,'24 min','WHITE FOX','SPRING 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9253-tIUXF2gfU8Sg.jpg','["Drama","Psychological","Sci-Fi","Thriller"]',607242,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(9260,9260,'Kizumonogatari I: Tekketsu-hen','Kizumonogatari Part 1: Tekketsu',replace('First season of the Monogatari Series, part 2/6. Contains the arc Koyomi Vamp from the Kizumonogatari light novel. \n\n\n\nMarch 25th—just another day during spring break. Koyomi Araragi, a second year high school student at Naoetsu High School, befriends Tsubasa Hanekawa, the top honors student at his school. Hanekawa mentions a rumor about a "blonde vampire" that has been sighted around their town recently. Araragi, who is usually anti-social, takes a liking to her down-to-earth personality.\n\n\n\nThat night, Araragi encounters the rumored vampire: she is Kiss-Shot Acerola-Orion Heart-Under-Blade, also known as the "iron-blooded, hot-blooded, cold-blooded King of Apparitions." The stunningly beautiful vampire cries out for Koyomi to save her as she lies in a pool of her own blood, all four of her limbs cut off. Kiss-shot asks Araragi to give her his blood, and when he does, the next moment he awakes, Araragi finds himself reborn as her vampire kin. As Araragi struggles to accept his existence, Kiss-Shot whispers, "Welcome to the world of darkness..."\n\n\n\n(Source: Aniplex)','\n',char(10)),8.3,'MOVIE',2,0,'64 min','Shaft','WINTER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9260-cl7sczYOpTeW.png','["Action","Drama","Ecchi","Mystery","Psychological","Supernatural"]',169522,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(9756,9756,'Mahou Shoujo Madoka☆Magica','Puella Magi Madoka Magica',replace('One night, 14-year-old Madoka Kaname has a terrible nightmare - against the backdrop of a devastated city, she witnesses a girl fight a losing battle against a dreadful being lingering above, while a cat-like magical creature tells Madoka the only way to change such tragic outcome is for her to make a contract with him and become a magical girl. \n\n\nThe next day, the teen''s dream seemingly becomes reality as the girl she saw in her dream - Homura - arrives at Mitakihara Middle School as a transfer student, mysteriously warning Madoka to stay just the way she is; but when later on she and her best friend Sayaka encounter the same cat-like magical creature from her dream - who introduces himself as Kyubey - the pair discovers that magical girls are real, and what''s more, they can choose to become one. All they must do is sign a contract with Kyubey and agree to take on the duty to fight abstract beings called ''witches'' that spread despair to the human world, and in return, each one of them will be granted any single wish they desire. However, as Homura''s omen suggests, there might be far more to becoming a magical girl than Madoka and Sayaka realize... \n\n\n\nNotes:\n\n- Due to the 2011 Tōhoku earthquake and tsunami, the broadcasts of episodes 11 and 12 were delayed and were later aired as a double feature on April 21, 2011.','\n',char(10)),8.3,'TV',2,0,'24 min','Shaft','WINTER 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9756-QnUGwlwwnsuN.jpg','["Action","Drama","Fantasy","Mahou Shoujo","Psychological","Thriller"]',333776,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(9919,9919,'Ao no Exorcist','Blue Exorcist','This world consists of two dimensions joined as one, like a mirror. The first is the world in which the humans live, Assiah. The other is the world of demons, Gehenna. Ordinarily, travel between the two, and indeed any kind of contact between the two, is impossible. However the demons can pass over into this world by possessing anything that exist within it. Satan the god of demons, but there''s one thing that he doesn''t have, and that''s a substance in the human world that is powerful enough to contain him!! For that purpose he created Rin, his son from a human woman, but will his son agree to his plans? Or will he become something else...? An exorcist?',7.2,'TV',2,0,'24 min','A-1 Pictures','SPRING 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9919-nXS7JOZrWHfS.jpg','["Action","Fantasy","Supernatural"]',468103,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(9989,9989,'Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai.','Anohana: The Flower We Saw That Day',replace('Jinta Yadomi and his group of childhood friends have become estranged after a tragic accident split them apart. Now in their high school years, a sudden surprise forces each of them to confront their guilt over what happened that day and come to terms with the ghosts of their past. \n\n\n(Source: NIS America)','\n',char(10)),8,'TV',2,0,'22 min','A-1 Pictures','SPRING 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9989-hImMg6kCMm6I.jpg','["Drama","Romance","Slice of Life","Supernatural"]',399994,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(10087,10087,'Fate/Zero','Fate/Zero',replace('With the promise of granting any wish, the omnipotent Holy Grail triggered three wars in the past, each too cruel and fierce to leave a victor. In spite of that, the wealthy Einzbern family is confident that the Fourth Holy Grail War will be different; namely, with a vessel of the Holy Grail now in their grasp. Solely for this reason, the much hated "Magus Killer" Kiritsugu Emiya is hired by the Einzberns, with marriage to their only daughter Irisviel as binding contract.\n\n\n\nKiritsugu now stands at the center of a cutthroat game of survival, facing off against six other participants, each armed with an ancient familiar, and fueled by unique desires and ideals. Accompanied by his own familiar, Saber, the notorious mercenary soon finds his greatest opponent in Kirei Kotomine, a priest who seeks salvation from the emptiness within himself in pursuit of Kiritsugu.\n\n\n\nBased on the light novel written by Gen Urobuchi, Fate/Zero depicts the events of the Fourth Holy Grail War—10 years prior to Fate/stay night. Witness a battle royale in which no one is guaranteed to survive.\n\n\n\n(Source: MAL Rewrite)\n\n\n\nNote: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),8.1,'TV',2,0,'24 min','ufotable','FALL 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10087-M4Hd9qrHGrXk.png','["Action","Drama","Fantasy","Supernatural"]',353451,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(10165,10165,'Nichijou','Nichijou - My Ordinary Life',replace('Nichijou primarily focuses on the daily antics of a trio of childhood friends—high school girls Mio Naganohara, Yuuko Aioi and Mai Minakami—whose stories soon intertwine with the young genius Hakase Shinonome, her robot caretaker Nano, and their talking cat Sakamoto. With every passing day, the lives of these six, as well as of the many people around them, experience both the calms of normal life and the insanity of the absurd. Walking to school, being bitten by a talking crow, spending time with friends, and watching the principal suplex a deer: they are all in a day''s work in the extraordinary everyday lives of those in Nichijou. \n\n\n(Source: MAL Rewrite)','\n',char(10)),8.3,'TV',2,0,'23 min','Kyoto Animation','SPRING 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10165-tw8Cz7K9tfVJ.png','["Comedy","Slice of Life"]',245089,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(10408,10408,'Hotarubi no Mori e','Into the Forest of Fireflies'' Light','The story of Hotarubi no Mori e centers around Hotaru, a little girl who gets lost in an enchanted forest where apparitions reside. A young boy, Gin, appears before Hotaru, but she cannot touch him for fear of making him disappear.',7.9,'MOVIE',2,0,'45 min','Brain''s Base','SUMMER 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10408-PlKJ6DAyvMk2.png','["Drama","Fantasy","Romance","Supernatural"]',197711,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(10620,10620,'Mirai Nikki','The Future Diary',replace('This psychological thriller, based on the manga written and illustrated by Sakae Esuno, is about Yuki, a loner who''s not very good with people. He prefers to write a diary on his cell phone and talk to his imaginary friend, Deus Ex Machina &ndash; The God of Time and Space. However, Yuki soon learns that Deus is more than a figment of his imagination when he makes Yuki participate in a battle royale with eleven others. The contestants are given special diaries that can predict the future, each diary possessing unique features that give it both advantages and disadvantages. Within the next 90 days, the contestants must try to survive until there is only one left standing. The winner will become the new God of Time and Space.\n\n\n(Source: FUNimation)','\n',char(10)),6.9,'TV',2,0,'23 min','Asread','FALL 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10620-dUZeNej0W4QN.png','["Action","Horror","Mystery","Psychological","Supernatural","Thriller"]',438318,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(10719,10719,'Boku wa Tomodachi ga Sukunai','Haganai',replace('Hasegawa Kodaka has transferred schools, and he''s having a hard time making friends. It doesn''t help that his blond hair tends to make people think he''s a delinquent. One day, he runs into his bad-tempered solitary classmate Yozora while she''s talking animatedly to her imaginary friend Tomo. Realizing that neither of them have any actual friends, they decide that the best way to alter this situation is to form a club and start recruiting. \n\n\nThat is how "Rinjinbu", The Neighbours'' Club, was formed, a club specifically designed for people who don''t have very many friends. As other lonely classmates slowly join their little club, they''ll try to learn how to build friendships through cooking together, playing games, and other group activities. But will this group of relationship-challenged misfits really be able to get along?','\n',char(10)),6.7,'TV',2,0,'24 min','AIC Build','FALL 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10719-aNf9gOOw62Fs.png','["Comedy","Ecchi","Romance","Slice of Life"]',168805,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(10793,10793,'Guilty Crown','Guilty Crown',replace('Shuu''s entire world was shattered after a meteorite crashed into Japan, unleashing the lethal Apocalypse Virus. The chaos and anarchy born of the outbreak cost Shuu his family and reduced him to a timid, fearful shell of the boy he''d once been. His life took another unexpected turn after a chance encounter with the stunning pop star, Inori. This mysterious beauty introduced Shuu to the King''s Right Hand: a genetic mutation that allows him to reach into hearts of mortals and turn them into weapons.\n\n\n\nShuu finds himself caught in the crossfire between those who desperately seek his newfound strength. On one side lurks a clandestine government agency, and on the other, Inori and the spirited band of rebels known as Funeral Parlor. The choice is Shuu''s to make - and the world is his to change.\n\n\n\n(Source: Funimation)','\n',char(10)),6.9,'TV',2,0,'24 min','Production I.G','FALL 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10793-KCysCbrVNqK9.jpg','["Action","Drama","Mecha","Psychological","Romance","Sci-Fi"]',244824,1794735119,22,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11061,11061,'HUNTER×HUNTER (2011)','Hunter x Hunter (2011)',replace('A Hunter is one who travels the world doing all sorts of dangerous tasks. From capturing criminals to searching deep within uncharted lands for any lost treasures. Gon is a young boy whose father disappeared long ago, being a Hunter. He believes if he could also follow his father''s path, he could one day reunite with him.\n\n\nAfter becoming 12, Gon leaves his home and takes on the task of entering the Hunter exam, notorious for its low success rate and high probability of death to become an official Hunter. He befriends the revenge-driven Kurapika, the doctor-to-be Leorio and the rebellious ex-assassin Killua in the exam, with their friendship prevailing throughout the many trials and threats they come upon taking on the dangerous career of a Hunter.','\n',char(10)),8.9,'TV',2,0,'24 min','MADHOUSE','FALL 2011','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11061-y5gsT1hoHuHw.png','["Action","Adventure","Fantasy"]',858036,1794735119,148,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11111,11111,'Another','Another',replace('When Kouichi Sakakibara transfers to a new school, he senses a frightening atmosphere in his new class, a secret none of them will talk about. At the center is the beautiful Mei Misaki. Kouichi is immediately drawn to her mysterious aura, but he begins to realize that no one else in the class is aware of her presence. Soon after his arrival, what is known as the Calamity begins, and it claims the lives of many students.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.1,'TV',2,0,'24 min','P.A.WORKS','WINTER 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11111-gvvE5bBYsyFo.png','["Horror","Mystery","Psychological","Supernatural","Thriller"]',392053,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11597,11597,'Nisemonogatari','Nisemonogatari',replace('First season of the Monogatari Series, part 5/6. Contains the arcs Karen Bee and Tsukihi Phoenix from the Nisemonogatari light novels.\n\n\n\nIn Bakemonogatari, the story centered on Koyomi Araragi, a third year high school student who has recently survived a vampire attack and finds himself mixed up with all kinds of apparitions: gods, ghosts, myths, and spirits. However, in Nisemonogatari, we pick up right where we left off and follow Koyomi as the psychological twists delve deeper and deeper...\n\n\n\n(Source: Aniplex)','\n',char(10)),7.9,'TV',2,0,'24 min','Shaft','WINTER 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11597-dcEqcn2ku4RN.jpg','["Comedy","Drama","Ecchi","Mystery","Psychological","Supernatural"]',188593,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11617,11617,'High School DxD','High School DxD',replace('Issei Hyodo is your average perverted high school student whose one wish in life is to have his own harem, but he''s got to be one of the unluckiest guys around. He goes on his first date with a girl only to get brutally attacked and killed when it turns out the girl is really a vicious fallen angel. To top it all off, he''s later reincarnated as a devil by his gorgeous senpai who tells him that she is also a devil and now his master! One thing''s for sure, his peaceful days are over. In a battle between devils and angels, who will win? \n\n\n(Source: FUNimation)','\n',char(10)),6.9,'TV',2,0,'24 min','TNK','WINTER 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx11617-nmxMU9Zh3H5R.jpg','["Action","Comedy","Ecchi","Fantasy","Romance"]',321219,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11741,11741,'Fate/Zero 2nd Season','Fate/Zero Season 2',replace('As the Fourth Holy Grail War rages on with no clear victor in sight, the remaining Servants and their Masters are called upon by Church supervisor Risei Kotomine, in order to band together and confront an impending threat that could unravel the Grail War and bring about the destruction of Fuyuki City. The uneasy truce soon collapses as Masters demonstrate that they will do anything in their power, no matter how despicable, to win.\n\n\n\nSeeds of doubt are sown between Kiritsugu Emiya and Saber, his Servant, as their conflicting ideologies on heroism and chivalry clash. Meanwhile, an ominous bond forms between Kirei Kotomine, who still seeks to find his purpose in life, and one of the remaining Servants. As the countdown to the end of the war reaches zero, the cost of winning begins to blur the line between victory and defeat.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.4,'TV',2,0,'24 min','ufotable','SPRING 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11741-oEy1fJHYm2zJ.jpg','["Action","Drama","Fantasy","Supernatural"]',245512,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11757,11757,'Sword Art Online','Sword Art Online',replace('In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now...\n\n\n(Source: Crunchyroll)','\n',char(10)),7,'TV',2,0,'23 min','A-1 Pictures','SUMMER 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11757-SxYDUzdr9rh2.jpg','["Action","Adventure","Fantasy","Romance"]',733099,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11771,11771,'Kuroko no Basket','Kuroko''s Basketball',replace('Teikou Junior High School''s basketball team is crowned champion three years in a row thanks to five outstanding players who, with their breathtaking and unique skills, leave opponents in despair and fans in admiration. However, after graduating, these teammates, known as "The Generation of Miracles", go their separate ways and now consider each other as rivals.\n\n\n\nAt Seirin High School, two newly recruited freshmen prove that they are not ordinary basketball players: Taiga Kagami, a promising player returning from the US, and Tetsuya Kuroko, a seemingly ordinary student whose lack of presence allows him to move around unnoticed. Although Kuroko is neither athletic nor able to score any points, he was a member of Teikou''s basketball team, where he played as the "Phantom Sixth Man," who easily passed the ball and assisted his teammates.\n\n\n\nKuroko no Basket follows the journey of Seirin''s players as they attempt to become the best Japanese high school team by winning the Interhigh Championship. To reach their goal, they have to cross pathways with several powerful teams, some of which have one of the five players with godlike abilities, whom Kuroko and Taiga make a pact to defeat.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'24 min','Production I.G','SPRING 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11771-uvr44RAwRxPw.jpg','["Comedy","Sports"]',292213,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11843,11843,'Danshi Koukousei no Nichijou','Daily Lives of High School Boys',replace(replace('Tadakuni, Hidenori, and Yoshitake are students at the all-boys academy, Sanada North High School. This is a tale about just that—their daily lives as students. Winning the basketball tournament? Finding true love? You won''t find any of that here. Whether it''s sparking random arguments while hanging out with friends, meeting that one weird co-worker at a part-time job, or even letting imaginations run wild on a windy afternoon, we''ve all experienced the show''s ordinary but true-to-life themes at one point or another. \n\n\r\n(Source: NIS America)','\r',char(13)),'\n',char(10)),8,'TV',2,0,'24 min','Sunrise','WINTER 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11843-ui2jBcuQUqnl.jpg','["Comedy","Slice of Life"]',196859,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(11887,11887,'Kokoro Connect','Kokoro Connect',replace(replace('The five members of the Cultural Research Club - Taichi Yaegashi, Iori Nagase, Himeko Inaba, Yui Kiriyama, and Yoshifumi Aoki - encounter a bizarre phenomenon one day when Aoki and Yui switch bodies without warning. The same begins to happen to the other club members, throwing their daily lives into disarray.\n\n\r\nAt first the five students find some amusement amidst the confusion, but this unwarranted connection also exposes the painful scars hidden within their hearts. As their calm lives are shattered, the relationships between the five students also begin to change...\n\n\r\n(Source: Crunchyroll, edited)','\r',char(13)),'\n',char(10)),7.5,'TV',2,0,'24 min','SILVER LINK.','SUMMER 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11887-ypZTwcRqopiL.jpg','["Drama","Romance","Slice of Life","Supernatural"]',193825,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(12189,12189,'Hyouka','Hyouka',replace('Energy-conservative high school student Houtarou Oreki ends up with more than he bargained for when he signs up for the Classic Literature Club at his sister''s behest—especially when he realizes how deep-rooted the club''s history really is. Begrudgingly, Oreki is dragged into an investigation concerning the 45-year-old mystery that surrounds the club room.\n\n\n\nAccompanied by his fellow club members, the knowledgeable Satoshi Fukube, the stern but benign Mayaka Ibara, and the ever-curious Eru Chitanda, Oreki must combat deadlines and lack of information with resourcefulness and hidden talent, in order to not only find the truth buried beneath the dust of works created years before them, but of other side cases as well.\n\n\n\nBased on the award-winning Koten-bu light novel series, and directed by Yasuhiro Takemoto of Suzumiya Haruhi no Shoushitsu, Hyouka shows that normal life can be full of small mysteries, be it family history, a student film, or even the withered flowers that make up a ghost story.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'26 min','Kyoto Animation','SPRING 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12189-zj5AWUYO53Fv.jpg','["Mystery","Romance","Slice of Life"]',357998,1794735119,22,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(12355,12355,'Ookami Kodomo no Ame to Yuki','Wolf Children',replace('The theme of the film is the love between parents and children. The story covers 13 years and begins with a 19-year-old college student named Hana who encounters and falls in "fairy tale-like" love with a "wolf man." After marrying the wolf man, Hana gives birth and raises two wolf children&mdash;an older sister named Yuki who was born on a snowy day, and a younger brother named Ame who was born on a rainy day. The four quietly lived in a corner of a city to conceal the existence of the "wolf children," but when the wolf man suddenly dies, Hana decides to move to a rural town far removed from the city.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.3,'MOVIE',2,0,'117 min','MADHOUSE','SPRING 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12355-wNsvhEsXEgrH.png','["Drama","Fantasy","Romance","Slice of Life"]',196802,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(13125,13125,'Shinsekai yori','From the New World',replace('Following a sudden outbreak of psychokinesis in 0.1% of the population, a rapid transformation swept the world. The godlike ability to manipulate matter remotely turned many power wielders to violence, inciting a long period of upheaval. Finally, after a chaotic era shaped by the rise and fall of oppressive regimes, the psychic humans were able to achieve a fragile peace by isolating their society, creating a new world bound by complex rules.\n\n\n\nIn the town of Kamisu 66, 12-year-old Saki Watanabe has just awakened to her powers and is relieved to rejoin her friends—the mischievous Satoru Asahina, the shy Mamoru Itou, the cheerful Maria Akizuki, and Shun Aonuma, a mysterious boy whom Saki admires—at Sage Academy, a special school for psychics. However, unease looms as Saki begins to question the fate of those unable to awaken to their powers, and the children begin to get involved with secretive matters such as the rumored Tainted Cats said to abduct children.\n\n\n\nShinsekai yori tells the unique coming-of-age story of Saki and her friends as they journey to grow into their roles in the supposed utopia. Accepting these roles, however, might not come easy when faced with the dark and shocking truths of society, and the impending havoc born from the new world.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8,'TV',2,0,'23 min','A-1 Pictures','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx13125-2EDZb8ahshQc.png','["Drama","Horror","Mystery","Psychological","Sci-Fi","Supernatural"]',181154,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(13601,13601,'PSYCHO-PASS','PSYCHO-PASS',replace('Justice, and the enforcement of it, has changed. In the 22nd century, Japan enforces the Sibyl System, an objective means of determining the threat level of each citizen by examining their mental state for signs of criminal intent, known as their Psycho-Pass. Inspectors uphold the law by subjugating, often with lethal force, anyone harboring the slightest ill-will; alongside them are Enforcers, jaded Inspectors that have become latent criminals, granted relative freedom in exchange for carrying out the Inspectors'' dirty work.\n\n\n\nInto this world steps Akane Tsunemori, a young woman with an honest desire to uphold justice. However, as she works alongside veteran Enforcer Shinya Kougami, she soon learns that the Sibyl System''s judgments are not as perfect as her fellow Inspectors assume. With everything she has known turned on its head, Akane wrestles with the question of what justice truly is, and whether it can be upheld through the use of a system that may already be corrupt.\n\n\n  \n(Source: MAL Rewrite)\n\n\n\nNote: In the Summer 2014 season, Psycho-Pass was rebroadcast and re-edited to fit into an hour time-slot, ending up in 11 one-hour episodes. This edit included added scenes at the beginning and middle of the episodes, as well as fixing and improving animation.','\n',char(10)),8.1,'TV',2,0,'23 min','Production I.G','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx13601-i42VFuHpqEOJ.jpg','["Action","Psychological","Sci-Fi","Thriller"]',362303,1794735119,22,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(13759,13759,'Sakurasou no Pet na Kanojo','The Pet Girl of Sakurasou',replace('The first time he saw her, it was love at first sight. Unfortunately for Sorata Kanda, "she" was a cat named Hikari and his school''s rules forbid keeping pets in the regular dorms. As a result, Sorata is banished to the infamous Sakura Hall alongside other troublesome and unusual students like Jin, overzealous playboy, Ryuunosuke, the reclusive hermit, and Mashiro, a brilliant artist who''s so unfocused and clueless about the real world that dorm supervisor Ms. Sengoku assigns Sorata the task of taking care of her along with his ever-growing collection of stray cats!\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.8,'TV',2,0,'24 min','J.C.STAFF','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx13759-xNf0gJK4Axt2.jpg','["Comedy","Drama","Romance","Slice of Life"]',281815,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(14227,14227,'Tonari no Kaibutsu-kun','My Little Monster',replace('Standoffish, reclusive Shizuku Mizutani cares far more about earning stellar grades than cultivating friendships. But her opinions on friendship and relationships begin to change when she meets habitual truant Haru Yoshida, who happens to have a rather fearsome reputation. Like Shizuku, Haru’s reputation has made it difficult to make friends. And yet through their budding friendship and stirrings of attraction the unlikely pair learns to understand one another, the world around them, and the tenor of their own emotions.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.2,'TV',2,0,'24 min','Brain''s Base','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14227-VGxPG1xDZG7v.jpg','["Comedy","Romance","Slice of Life"]',266700,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(14467,14467,'K','K',replace('Yashiro Isana has lived a relatively ordinary, simple life. He lives in the technologically advanced Shizume City and attends Ashinaka High School, a notable high school that is located on an island just outside the areas. Yashiro is friendly with everyone. Nothing seems wrong about him, except perhaps his habit of forgetting where his school-issued PDA is.\n\n\n\nHowever, nothing normal has been happening since the recent murder of Tatara Totsuka, prominent member of the infamous HOMRA. No one knows who exactly killed him but the man responsible bears an uncanny, identical appearance to Yashiro. Seeking vengeance, the Red Clansmen of HOMRA set out to get Yashiro and kill him. Everyone suspects that Yashiro is the murderer.\n\n\n\n(Source: Wikipedia)','\n',char(10)),7.1,'TV',2,0,'24 min','GoHands','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14467-TQjwOvq4jkYS.png','["Action","Mystery","Supernatural"]',175868,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(14513,14513,'Magi: The labyrinth of magic','Magi: The Labyrinth of Magic','This story is about the flow of fate and the battle to keep the world on the right path. Aladdin is a boy who has set out to explore the world after being trapped in a room for most of his life. His best friend is a flute with a djinn in it named Ugo. Soon enough, Aladdin discovers he is a Magi, a magician who chooses kings, and he was born to choose kings who will follow the righteous path, battling against those who want to destroy fate. Follow his adventures as he meets others from 1001 Arabian Nights, like Ali Baba and Sinbad, and fights to keep the balance of the world in check!',7.8,'TV',2,0,'24 min','A-1 Pictures','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14513-HuUdrFFYftA7.jpg','["Action","Adventure","Fantasy"]',236189,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(14713,14713,'Kamisama Hajimemashita','Kamisama Kiss',replace('Nanami Momozono is alone and homeless after her dad skips town to evade his gambling debts and the debt collectors kick her out of her apartment. So when a man she''s just saved from a dog offers her his home, she jumps at the opportunity. But it turns out that his place is a shrine, and Nanami has unwittingly taken over his job as a local deity! \n\n\nNanami has all kinda of new responsibilities she doesn''t understand, dangers she''s unaware of, and a cranky ex-familiar who''s... actually pretty hot. What''s a new-fledged godling to do? \n\n\n(Source: VIZ Media)','\n',char(10)),8.1,'TV',2,0,'24 min','TMS Entertainment','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx14713-RyZ7bA7CdvGw.jpg','["Comedy","Fantasy","Romance","Supernatural"]',174347,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(14719,14719,'JoJo no Kimyou na Bouken (TV)','JoJo''s Bizarre Adventure (TV)',replace('Beginning its tale in 19th century England, young aristocrat Jonathan Joestar finds himself locked in bitter rivalry with Dio Brando, a low-born boy who Jonathan''s father took under his wing after the death of Dio''s father. Discontent with his station in life, Dio''s fathomless lust to reign over all eventually leads him to seek the supernatural powers of an ancient Aztec stone mask in the Joestar''s possession—an artifact that will forever change the destiny of Dio and Jonathan for generations to come.\n\n\n\nFifty years later, in 1938 New York City, Jonathan''s grandson Joseph Joestar must take up his grandfather''s mission and master the abilities necessary to destroy the stone mask and its immensely powerful creators who threaten humanity''s very existence, the Pillar Men.\n\n\n(Source: Anime News Network)','\n',char(10)),7.7,'TV',2,0,'24 min','david production','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14719-VT5dRzTBSZ0w.jpg','["Action","Adventure","Supernatural"]',489716,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(14741,14741,'Chuunibyou demo Koi ga Shitai!','Love, Chunibyo & Other Delusions',replace('Everybody has had that stage in their life where they have thought themselves to be special, different from the masses of ordinary humans. They might go as far as seeing themselves capable of wielding mystical powers, or maybe even believe themselves to have descended from a fantasy realm. This "disease" is known as "chuunibyou" and is often the source of some of the most embarrassing moments of a person''s life.\n\n\n\nFor Yuuta Togashi, the scars that his chuunibyou has left behind are still fresh. Having posed as the "Dark Flame Master" during his middle school years, he looks back at those times with extreme embarrassment, so much so that he decides to attend a high school far away where nobody will recognize him. Putting his dark history behind him, he longs to live a normal high school life.\n\n\n\nUnfortunately, he hasn''t escaped his past yet: enter Rikka Takanashi, Yuuta''s new classmate and self-declared vessel of the "Wicked Eye." As this eccentric young girl crashes into Yuuta''s life, his dream of an ordinary, chuunibyou-free life quickly crumbles away. In this hilarious and heartwarming story of a boy who just wants to leave his embarrassing memories behind, the delusions of old are far from a thing of the past.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.5,'TV',2,0,'24 min','Kyoto Animation','FALL 2012','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14741-CGXEIeUe2roA.jpg','["Comedy","Drama","Romance","Slice of Life"]',360484,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(14813,14813,'Yahari Ore no Seishun Love Come wa Machigatteiru.','My Teen Romantic Comedy SNAFU',replace('This romantic comedy revolves around an antisocial high school student named Hikigaya Hachiman with a distorted view on life and no friends or girlfriend. When he sees his classmates talking excitedly about living their adolescent lives, he mutters: "They''re a bunch of liars." When he is asked about his future dreams, he responds: "Not working." A teacher gets Hachiman to join the ''Volunteer Service'' club, which happens to have the school''s prettiest girl: Yukinoshita Yukino.\n\n\n(Source: Anime News Network)','\n',char(10)),7.8,'TV',2,0,'24 min','Brain''s Base','SPRING 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14813-3mNvcKNEQcDs.jpg','["Comedy","Drama","Romance","Slice of Life"]',390410,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(15451,15451,'High School DxD NEW','High School DxD NEW',replace('The devilish haremking Issei Hyoudou is back for more outrageous Oppai Battle Entertainment in the scintillating second season of High School DxD! Fans who like their hardcore action spiked with a double dose of fan service won''t be able to pry their eyes off all the scorching supernatural schoolgirls waiting for them in Season Two. So what are you waiting for? Plant yourself in front of the boob tube and watch a harem of devil hotties show you how much fun it is to be bad!\n\n\n\n(Source: FUNimation)\n\n\n\nEpisode 1 was previewed at a screening in United Cinema Toyosu, Tokyo on June 29, 2013. Regular broadcasting began on July 7, 2013.\n\nThe Blu-ray and DVD Director''s Cut includes an extra 3 minutes per episode.','\n',char(10)),7.1,'TV',2,0,'27 min','TNK','SUMMER 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx15451-A5T54vmxUq9t.jpg','["Action","Comedy","Ecchi","Fantasy","Romance"]',200833,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(15583,15583,'Date A Live','Date A Live',replace('Thirty years before a strange phenomena called a "spacequake" devastated the center of Eurasia, claiming the lives of at least 150 million people. Since then, smaller spacequakes plague the world on an irregular basis. Shidou Itsuka, a seemingly ordinary high schooler comes across a mysterious girl at the ground zero of a spacequake and learns from his sister Kotori she is one of the "Spirits" who are the real cause of the spacequakes that occur when they manifest themselves in the world. He also learns that Kotori is the captain of the airship Ratatoskr and recruits him to make use of his mysterious ability to seal the Spirits'' powers and stop them from being a threat to mankind. However, there is a catch: to seal a Spirit, he must make her fall in love with him.\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.8,'TV',2,0,'23 min','AIC Plus+','SPRING 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx15583-Sxd2J4RJdRhj.jpg','["Action","Comedy","Ecchi","Fantasy","Mecha","Romance","Sci-Fi"]',252128,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(15809,15809,'Hataraku Maou-sama!','The Devil is a Part-Timer!','Devil King Sadao is only one step away from conquering the world when he is beaten by Hero Emilia and forced to drift to the other world: modern-day Tokyo. As "conquering the world" are the only skills the Devil King possesses&mdash;and are obviously unnecessary in his new situation&mdash;he must work as a freeter to pay for his living expenses!',7.5,'TV',2,0,'24 min','WHITE FOX','SPRING 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx15809-ECv3HyOYJKrk.jpg','["Comedy","Fantasy","Romance","Slice of Life"]',402089,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(16498,16498,'Shingeki no Kyojin','Attack on Titan',replace(replace('Several hundred years ago, humans were nearly exterminated by titans. Titans are typically several stories tall, seem to have no intelligence, devour human beings and, worst of all, seem to do it for the pleasure rather than as a food source. A small percentage of humanity survived by walling themselves in a city protected by extremely high walls, even taller than the biggest of titans.\n\n\r\nFlash forward to the present and the city has not seen a titan in over 100 years. Teenage boy Eren and his foster sister Mikasa witness something horrific as the city walls are destroyed by a colossal titan that appears out of thin air. As the smaller titans flood the city, the two kids watch in horror as their mother is eaten alive. Eren vows that he will murder every single titan and take revenge for all of mankind.\n\n\r\n(Source: MangaHelpers)','\r',char(13)),'\n',char(10)),8.5,'TV',2,0,'24 min','WIT STUDIO','SPRING 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx16498-buvcRTBx4NSm.jpg','["Action","Drama","Fantasy","Mystery"]',1078955,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(16592,16592,'Danganronpa: Kibou no Gakuen to Zetsubou no Koukousei - The Animation','Danganronpa: The Animation','A group of 15 elite high school students are gathered at a very special, high class high school. To graduate from this high school essentially means you''ll succeed in life, but graduating is very difficult. The school is presided over by a bear called Monokuma, and he explains to them that their graduation hinges around committing a murder. The only way to graduate is to kill one of your classmates and get away with it. If the other classmates discover the identity of the killer, the killer is the only one executed. However, if they fail to catch the killer, only the killer graduates and the others are annihilated. Which of the 15 will survive the bloodbath to come?',6.9,'TV',2,0,'24 min','Lerche','SUMMER 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx16592-mFn1gfMXlKtw.jpg','["Horror","Mystery","Psychological","Sci-Fi","Thriller"]',236653,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(16782,16782,'Kotonoha no Niwa','The Garden of Words',replace('Some people revel and play in the rain; others dread it and hide at the first drop. For high school student Takao, a summer shower is a source of artistic inspiration… but when he skips school in order to sketch in a rainy garden, Takao finds an even greater muse in Yukino, an older woman who seems adrift in the world. Despite the difference in their ages and lives, they strike up a comfortable relationship that slowly evolves as they randomly meet in the same garden whenever it rains. But with the rainy season coming to a close, Takao wonders if there''s enough time left to put his feelings into actions and words.\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.5,'MOVIE',2,0,'46 min','CoMix Wave','SPRING 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx16782-qpFGk18UqaHn.jpg','["Drama","Psychological","Romance","Slice of Life"]',251628,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(16894,16894,'Kuroko no Basket 2nd SEASON','Kuroko''s Basketball 2',replace('With the Interhigh Championship finally over, Seirin''s basketball team refocuses their efforts, training harder than ever to get the chance to participate in the Winter Cup. Both Kuroko and Kagami see old friends walk back into their lives, providing a challenge both on and off the court. \n \n\n\nAs new skills are developed and new alliances created, enemies from various teams—giants of high school basketball such as Yousen, Shuutoku and Touou—stand in the way of Seirin''s steadfast attempts to get to the top. All of these schools prove to be formidable foes whose abilities progress exponentially, while Kuroko struggles to find a balance between his resolve to play as part of a team and his desire to win. \n \n\n\nWith old wounds reopening, new challenges to face on the court, and a new set of foes—the "Uncrowned Kings"—vowing to defeat the new hopefuls, will Seirin ever be able to achieve their dream of beating the Generation of Miracles? \n \n\n\n(Source: MAL Rewrite)','\n',char(10)),8,'TV',2,0,'24 min','Production I.G','FALL 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx16894-iXt8GDs1L6dr.jpg','["Comedy","Sports"]',186205,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(17074,17074,'Monogatari Series: Second Season','Monogatari Series Second Season',replace('Second season of the Monogatari Series, part 1/2. Contains the arcs Tsubasa Tiger, Mayoi Jiangshi, Nadeko Medusa, Shinobu Time, and Hitagi End, from the Nekomonogatari White, Kabukimonogatari, Otorimonogatari, Onimonogatari and Koimonogatari light novels, respectively.\n\n\n\nThese stories take place after the end of the summer vacation when the apparition of the bee had left and the apparition of the phoenix avoided any consequences… Now that Koyomi Araragi and the girls were entering their new school terms, they were once again about to encounter supernatural beings…but this time, they may not be so easy to deal with.\n\n\n\nTsubasa Hanekawa, Mayoi Hachikuji, Nadeko Sengoku, Shinobu Oshino, and finally Hitagi Senjougahara. The girls’ loneliness, their confessions, and their departures… 5 new “stories” begin now.\n\n\n\n(Source: Aniplex)\n\n\n\nNotes:\n\n\n Includes 3 recap episodes from the TV version (Ep. 6, 11, 16).\n\n\nThe recap episodes were not included in the Blu-Ray version of the anime.','\n',char(10)),8.8,'TV',2,0,'26 min','Shaft','SUMMER 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx17074-xMhVAZsEDH66.png','["Comedy","Drama","Mystery","Psychological","Romance","Supernatural"]',174006,1794735120,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(17265,17265,'Log Horizon','Log Horizon',replace('The online fantasy game Elder Tales is a worldwide phenomenon, immersing millions of players in its intricately conceived virtual world. However, the release of the game''s twelfth expansion pack makes that immersion all too literal, as players from around the world are suddenly pulled into the game''s no-longer-fictional universe! Now, eight-year ET veteran Shiroe, his friend Naotsugu, the beautiful assassin Akatsuki, and 30,000 other players are faced with the daunting task of learning how to deal with an entirely new reality, one where the Non-Player Characters are actually alive, and the tips and tricks learned while playing with a keyboard no longer apply.\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.6,'TV',2,0,'25 min','Satelight','FALL 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx17265-RyErURYesjJt.jpg','["Action","Adventure","Fantasy"]',241821,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(17895,17895,'Golden Time','Golden Time',replace('Due to a tragic accident, Banri Tada is struck with amnesia, dissolving the memories of his hometown and past. However, after befriending Mitsuo Yanagisawa, he decides to move on and begin a new life at law school in Tokyo. But just as he is beginning to adjust to his college life, the beautiful Kouko Kaga dramatically barges into Banri''s life, and their chance meeting marks the beginning of an unforgettable year.\n\n\n\nAfter having a glimpse of college life, Banri learns that he is in a new place and a new world—a place where he can be reborn, to have new friends, fall in love, makes mistakes and grow. And as he begins to discover who he was, the path he has chosen leads him towards a blindingly bright life that he will never want to forget.','\n',char(10)),7.5,'TV',2,0,'24 min','J.C.STAFF','FALL 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx17895-M8yjOyMxHf5X.jpg','["Drama","Romance"]',271520,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(18115,18115,'Magi: The kingdom of magic','Magi: The Kingdom of Magic',replace('After celebrating their victory against Al-Thamen, Aladdin and his friends depart the land of Sindria. With the end of the battle, however, comes the time for each of them to go their separate ways. Hakuryuu and Kougyoku are ordered to go back to their home country, the Kou Empire. Meanwhile Aladdin announces he needs to head for Magnostadt—a mysterious country ruled by magicians—to investigate the mysterious events occurring in this new kingdom and become more proficient in magic. For their part, encouraged by Aladdin''s words, Alibaba and Morgiana also set off in pursuit of their own goals: training and going to her homeland, respectively.\n\n\n\nMagi: The Kingdom of Magic follows these friends as they all go about their separate adventures, each facing their own challenges. However, a new threat begins to rise as a great war looms over the horizon...\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.1,'TV',2,0,'24 min','A-1 Pictures','FALL 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx18115-dilbAD4yGMfc.png','["Action","Adventure","Fantasy"]',171178,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(18153,18153,'Kyoukai no Kanata','Beyond the Boundary',replace('They should never have met. They shouldn''t even exist. But when they come together, the entire world will change. The last surviving member of her clan, Mirai Kuriyama is cursed with the terrifying ability to control and manipulate blood, a power so heretical that she is shunned even by those with the ability to understand her "gift". Akihito Kanbara is only half human, but while the monstrous other half of his lineage seems to have doomed him to a life alone, it has also given him near invulnerability in the form of rapid healing. Alone, their futures seem bleak, but when a chance encounter brings them together, it becomes clear that they share more than just an unexpected bond. Together they share a destiny and a mission that only the two of them together may be strong enough to survive.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.4,'TV',2,0,'24 min','Kyoto Animation','FALL 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx18153-oDqA9zQzQPOq.png','["Action","Drama","Fantasy","Slice of Life","Supernatural"]',283647,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(18507,18507,'Free!','Free! -Iwatobi Swim Club-',replace('The story revolves around Haruka Nanase, a boy who has always loved to be immersed in water, and to swim in it. Before graduating from elementary school, he participated in a swimming tournament along with his fellow swimming club members, Makoto Tachibana, Nagisa Hazuki, and Rin Matsuoka. After achieving victory, each of the boys went their separate ways.\n\n\nTime passed, and in the middle of their uneventful high school lives Rin appears and challenges Haruka to a match, showing Haruka his overwhelming power. Not wanting it to end like this, Haruka, gathers together Makoto and Nagisa once again and brings a new member named Rei Ryugazaki to create the Iwatobi High School Swimming Club in order to defeat Rin.\n\n\n(Source: Anime News Network)','\n',char(10)),7.1,'TV',2,0,'24 min','Kyoto Animation','SUMMER 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx18507-RajfCYPpBfT3.png','["Comedy","Drama","Slice of Life","Sports"]',185318,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(18671,18671,'Chuunibyou demo Koi ga Shitai! Ren','Love, Chunibyo & Other Delusions - Heart Throb -',replace('Due to various events, Yuuta and Rikka are living together. This secret co-habitation is so exciting for the two lovebirds! Or so it should be...\n\n\n\nIs having a chuuni girlfriend too high of a hurdle for Yuuta, who never even went out with a normal girl?! Yuuta worries about how to advance his relationship with Rikka. And then everyone else, Nibutani, Kumin, and Dekomori, have powered up by advancing a grade. Furthermore, the cause of his chuunibyou outburst in middle school, the girl who calls herself Sophia Ring Saturn the 7th, Satone Shichimiya appears...\n\n\n\nThis is the long-awaited second season of the adolescent romantic comedy revolving around chuunibyou that makes you laugh and cry.\n\n\n\n\n(Source: Animax)','\n',char(10)),7.4,'TV',2,0,'24 min','Kyoto Animation','WINTER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx18671-RVIY9TGd737H.jpg','["Comedy","Drama","Romance","Slice of Life"]',186606,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(18679,18679,'Kill la Kill','Kill la Kill','After the murder of her father, Ryuuko Matoi has been wandering the land in search of his killer. Following her only lead—the missing half of his invention, the Scissor Blade—she arrives at the prestigious Honnouji Academy, a high school unlike any other. The academy is ruled by the imposing and cold-hearted student council president Satsuki Kiryuuin alongside her powerful underlings, the Elite Four. In the school''s brutally competitive hierarchy, Satsuki bestows upon those at the top special clothes called "Goku Uniforms," which grant the wearer unique superhuman abilities.',7.9,'TV',2,0,'24 min','TRIGGER','FALL 2013','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b18679-lbkq7iYESoFW.png','["Action","Comedy","Ecchi"]',421557,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(18897,18897,'Nisekoi','Nisekoi',replace('As a child, Raku Ichijo made a secret promise with his childhood sweetheart, keeping a pendant as a memento while his love took the key. He dreams of one day meeting his past love, but years later, reality smashes his hopes when Chitoge Kirisaki accidentally knees him in the face...\n\n\nThough Raku''s a normal high schooler, his family heads the notorious yakuza gang the Shuei-Gumi faction! And he''s dragged into family affairs when he''s forced into a relationship with Chitoge, the daughter of a rival gang''s boss!\n\n\nDespite their constant spats, the two somehow fool everyone with their false relationship. Raku then discovers that Chitoge has a mysterious key from her past, which she can''t remember... Plus, two other girls appear with keys as well—Kosaki Onodera and Marika Tachibana!\n\n\nCaught in the midst of this love maelstrom, even more complications arise for Raku when his class decides on Romeo and Juliet as the class''s play for the school festival. Can the two false lovebirds pull off the impossible and make the play a success?\n\n\n(Source: VIZ Media)','\n',char(10)),7.3,'TV',2,0,'24 min','Shaft','WINTER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx18897-G2Fx2ZACsXBU.jpg','["Comedy","Romance","Slice of Life"]',272796,1794735119,20,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(19603,22297,'Fate/stay night: Unlimited Blade Works','Fate/stay night: Unlimited Blade Works',replace('Fuyuki City - a city surrounded by the sea and mountains becomes the setting for an ancient ritual. Seven masters are given control of heroic spirits in order to realize the mythical Holy Grail, which is said to grant its owner any wish. These heroic spirits or servants represent legendary heroes of various classes: "Saber," "Lancer," "Archer," "Rider," "Caster," "Assassin," and "Berserker." Each master will enter into a contract with their chosen servant and battle the others to the death until only one pair remains... This is the "Holy Grail War."\n\n\n\nThe young and capable mage, Rin Tohsaka, prepares for her long-awaited Fifth Holy Grail War to begin... With her servant Archer, Rin enters the Holy Grail War as the sole heir to the prestigious Tohsaka family after her father''s death. But when Shirou Emiya, a boy from Rin''s school, unwittingly becomes a Master and is fatally wounded in battle, she has no choice but to save him. With Shirou and his servant Saber, Rin sets out to strike down the conspiracies surrounding the Holy Grail War. Will the Holy Grail bless Rin and Shirou''s path toward victory or will they be cursed with defeat?\n\n\n\n(Source: Aniplex of America)\n\n\n\nNotes:\n\n- Includes Prologue.\n\n- The first, second and last episodes aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.\n\n- Based on the second route from TYPE-MOON''s visual novel, Fate/stay night.','\n',char(10)),8,'TV',2,0,'24 min','ufotable','FALL 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx19603-ycT0pyEgDVQu.jpg','["Action","Fantasy","Supernatural"]',269940,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(19815,19815,'No Game No Life','No Game, No Life',replace('Bored with life and considering the real world to be just a “crappy game,” savvy sibling shut-ins Sora and Shiro have withdrawn into their own fantasy world filled with video games. \n\n\n\nHowever, one day they find themselves summoned to another world by a boy who calls himself “God,” their abilities are about to be put to the ultimate test! Now not only their fates — but the fate of all of humanity — will be decided by a series of games that may just be the hardest these super-geniuses have ever faced!\n\n\n\n(Source: Sentai Filmworks, edited)','\n',char(10)),7.7,'TV',2,0,'24 min','MADHOUSE','SPRING 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b19815-sEOQ9yQaPKlk.jpg','["Adventure","Comedy","Ecchi","Fantasy"]',549512,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20447,20507,'Noragami','Noragami',replace('Minor god Yato is down on his luck. Fed up with his slacker lifestyle, his partner abruptly quits. He has no money, no worshippers, and no shrine to call home. But just when things are starting to seem hopeless, a bus accident forces him to cross paths with Hiyori Iki, a sweet and perky high school girl. After the accident, Hiyori''s soul has a bad habit of slipping out of her body, and after enlisting Yato''s help to get her back to normal, she begins to fall into the world of spirits and gods.\n\n\n\nBut Hiyori''s not the only one who''s keeping tabs on Yato. A god from Yato''s past is back, and he''s not interested in a friendly reunion.\n\n\n\n(Source: Funimation)','\n',char(10)),7.8,'TV',2,0,'24 min','bones','WINTER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20447-EoQXeygHaVCK.jpg','["Action","Adventure","Comedy","Supernatural"]',547300,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20457,20787,'Black Bullet','Black Bullet',replace('The Gastrea virus spreads like wildfire, causing each infected host to rapidly mutate, gaining new powers and abilities with every stage of development, even while they continue to attack, kill and infect multiple new hosts. Unable to fight a pandemic enemy that turns defenders into adversaries, the shocked remnants of the human race are forced to retreat into cities surrounded by giant monoliths made of Varanium, one of the few materials that can stop the Gastrea. Now mankind''s last hope lies in the Cursed Children: young girls infected with the virus who have managed to retain a hold on their humanity. Paired with a partner, they alone have the strength to take on a Gastrea in one-on-one combat. But the very thing that gives them power is a ticking time bomb, so even as they protect humanity, they are also feared and shunned. Are they Girls? Monsters? Or Mankind''s Ultimate Salvation?\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),6.7,'TV',2,0,'24 min','Kinema Citrus','SPRING 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20457-ftrNiYhZzgoY.jpg','["Action","Drama","Mystery","Sci-Fi"]',198834,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20458,20785,'Mahouka Koukou no Rettousei','The Irregular at Magic High School',replace('Magic is a product of neither legends nor fairy tales, but instead has become a technology of reality since a time unknown to people. Supernatural power became a technology systematized through magic, while magic became a technical skill. A "Supernatural Power User" became a "Magic Technician." Magic Technicians (in short, Magicians) are nurtured through Magic High Schools and Universities.\n\n\n\nThis is a story about: \n\n\n\nTatsuya, a defective elder brother low achiever.\n\nMiyuki, a perfect, flawless younger sister high achiever.\n\nAfter both siblings entered a Magic High School,\n\nThe stage of daily turbulence was unveiled—.','\n',char(10)),7,'TV',2,0,'23 min','MADHOUSE','SPRING 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20458-tGh343Ew10yU.jpg','["Action","Romance","Sci-Fi","Supernatural"]',264435,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20464,20583,'Haikyuu!!','HAIKYU!!',replace('Inspired after watching a volleyball ace nicknamed "Little Giant" in action, small-statured Shouyou Hinata revives the volleyball club at his middle school. The newly-formed team even makes it to a tournament; however, their first match turns out to be their last when they are brutally squashed by the "King of the Court," Tobio Kageyama. Hinata vows to surpass Kageyama, and so after graduating from middle school, he joins Karasuno High School''s volleyball team—only to find that his sworn rival, Kageyama, is now his teammate.\n\n\n\nThanks to his short height, Hinata struggles to find his role on the team, even with his superior jumping power. Surprisingly, Kageyama has his own problems that only Hinata can help with, and learning to work together appears to be the only way for the team to be successful. Based on Haruichi Furudate''s popular shounen manga of the same name, Haikyuu!! is an exhilarating and emotional sports comedy following two determined athletes as they attempt to patch a heated rivalry in order to make their high school volleyball team the best in Japan.\n\n\n\n[Written by MAL Rewrite]','\n',char(10)),8.3,'TV',2,0,'24 min','Production I.G','SPRING 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20464-ooZUyBe4ptp9.png','["Comedy","Drama","Sports"]',593763,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20474,20899,'JoJo no Kimyou na Bouken: Stardust Crusaders','JoJo''s Bizarre Adventure: Stardust Crusaders',replace('In a Japanese jail sits 17-year-old Jotaro Kujo: punk, fighter, delinquent...and possessed by a force beyond his control! Around the world, evil spirits are awakening: "Stands," monstrous invisible creatures which give their bearers incredible powers. To save his mother''s life, Jotaro must tame his dark forces and travel around the world to Cairo, Egypt, where a hundred-year-old vampire thirsts for the blood of his family. But the road is long, and an army of evil Stand Users waits to kill JoJo and his friends...\n\n\n\n(Source: VIZ Media)','\n',char(10)),7.9,'TV',2,0,'24 min','david production','SPRING 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20474-xuqem5GBlBtb.jpg','["Action","Adventure","Supernatural"]',352482,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20594,21881,'Sword Art Online II','Sword Art Online II',replace(replace('One year after the SAO incident, Kirito is approached by Seijiro Kikuoka from Japan''s Ministry of Internal Affairs and Communications Department "VR Division" with a rather peculiar request.\r\n\r\nThat was an investigation on the "Death Gun" incident that occurred in the gun and steel filled VRMMO called Gun Gale Online (GGO). "Players who are shot by a mysterious avatar with a jet black gun lose their lives even in the real world..." Failing to turn down Kikuoka''s bizarre request, Kirito logs in to GGO even though he is not completely convinced that the virtual world could physically affect the real world.\n\r\n\n\r\nKirito wanders in an unfamiliar world in order to gain any clues about the "Death Gun." Then, a female sniper named Sinon who owns a gigantic "Hecate II" rifle extends Kirito a helping hand. With Sinon''s help, Kirito decides to enter the "Bullet of Bullets," a large tournament to choose the most powerful gunner within the realm of GGO, in hopes to become the target of the "Death Gun" and make direct contact with the mysterious avatar.\n\r\n\n\r\n(Source: Crunchyroll)','\r',char(13)),'\n',char(10)),6.5,'TV',2,0,'24 min','A-1 Pictures','SUMMER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx20594-FhRgZ1H9Istt.jpg','["Action","Adventure","Fantasy","Sci-Fi"]',459332,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20596,21995,'Ao Haru Ride','Blue Spring Ride',replace(replace('Yoshioka Futaba has a few reasons why she wants to "reset" her image & life as a new high school student. Because she''s cute, she was ostracized by her female friends in junior high, and because of a misunderstanding, she couldn''t get her feeling across to the one boy she has ever liked, Tanaka-kun.\r\n\r\nNow in high school, she is determined to be as unladylike as possible so that her friends won''t be jealous of her. While living her life this way contentedly, she meets Tanaka-kun again, but he now goes under the name of Mabuchi Kou. He tells her that he felt the same way as she did when they were younger, but now things can never be the same again. Will Futaba be able to continue her love that never even started from three years ago?','\r',char(13)),'\n',char(10)),7.5,'TV',2,0,'23 min','Production I.G','SUMMER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20596-fJdMHV8xRMgY.png','["Drama","Romance","Slice of Life"]',249018,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20605,22319,'Tokyo Ghoul','Tokyo Ghoul',replace('The suspense horror/dark fantasy story is set in Tokyo, which is haunted by mysterious "ghouls" who are devouring humans. People are gripped by the fear of these ghouls whose identities are masked in mystery. An ordinary college student named Kaneki encounters Rize, a girl who is an avid reader like him, at the café he frequents. Little does he realize that his fate will change overnight.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.6,'TV',2,0,'24 min','Studio Pierrot','SUMMER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b20605-k665mVkSug8D.jpg','["Action","Drama","Horror","Mystery","Psychological","Supernatural"]',754940,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20613,22199,'Akame ga Kill!','Akame ga Kill!',replace('In a land where corruption rules and a ruthless Prime Minister has turned the puppet Emperor''s armies of soldiers, assassins and secret police against the people, only one force dares to stand against them: Night Raid, an elite team of relentless killers, each equipped with an Imperial Arm - legendary weapons with unique and incredible powers created in the distant past.\n\n\n\nRescued from a fate worse than death by Night Raid, young Tatsumi is offered the chance to join their lethal ranks… but it''s a deadly choice, as few can master an Imperial Arm and even fewer survive when two Arms go against each other in combat. The battle is on, and only the strongest will make it out alive.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.3,'TV',2,0,'24 min','WHITE FOX','SUMMER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20613-HXHpec4bemk5.jpg','["Action","Adventure","Drama","Fantasy","Horror","Psychological","Thriller"]',549516,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20623,22535,'Kiseijuu: Sei no Kakuritsu','Parasyte -the maxim-',replace('They arrive in silence and darkness. They descend from the skies. They have a hunger for human flesh. They are everywhere. They are parasites, alien creatures who must invade–and take control of–a human host to survive. And once they have infected their victims, they can assume any deadly form they choose: monsters with giant teeth, winged demons, creatures with blades for hands. But most have chosen to conceal their lethal purpose behind ordinary human faces. So no one knows their secret–except an ordinary high school student. Shin is battling for control of his own body against an alien parasite, but can he find a way to warn humanity of the horrors to come?\n\n\n\n(Source: Del Rey)','\n',char(10)),8.1,'TV',2,0,'24 min','MADHOUSE','FALL 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20623-dUARfggnNDOe.jpg','["Action","Drama","Horror","Psychological","Sci-Fi"]',509590,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20626,22043,'FAIRY TAIL (2014)','Fairy Tail Series 2',replace('The Grand Magic Games reaches its climax following Natsu Dragneel and Gajeel Redfox''s stunning victory over Sting Eucliffe and Rogue Cheney of the Sabertooth guild. This success pushes the Fairy Tail guild closer to being crowned the overall champions, but obtaining victory isn''t the only challenge they face. A mystery still surrounds a hooded stranger and the ominous Eclipse Gate, leaving more questions than answers.\n \nMore crazy adventures are on the horizon for Fairy Tail as their destructive antics and joyful rowdiness continue unabated. Their greatest trial is quickly approaching, but united as a family, the guild will always be ready to face any threat that comes their way.','\n',char(10)),7.4,'TV',2,0,'24 min','A-1 Pictures','SPRING 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20626-9LTreIofBgnu.jpg','["Action","Adventure","Fantasy"]',188657,1794735120,102,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20631,25157,'Trinity Seven','TRINITY SEVEN',replace('Pride, Envy, Wrath, Sloth, Greed, Gluttony, Lust. These are the seven sins laid upon seven girls who rule over Biblia Academy. \n\n\n\nTo retake his world, the boy decides he must control these sins... The boy, Arata Kasuga, has had the world he knows hit by a mysterious phenomenon "Collapse Phenomenon", and his cousin Hijiri disappears into another dimension. To understand the Collapse Phenomenon and win back his cousin, he comes to Biblia Academy. There he finds the seven girls and their sins.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.7,'TV',2,0,'24 min','Seven Arcs Pictures','FALL 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20631-LdCiy3goitcT.png','["Action","Comedy","Ecchi","Fantasy","Romance"]',201469,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20657,23277,'Saenai Heroine no Sodatekata','Saekano: How to Raise a Boring Girlfriend',replace('The life of Tomoyo Aki, a highschool otaku working part time to support his BD hoarding. With remarkable luck, he bumps head-first into Megumi Kato, the most beautiful girl he has ever seen. Naturally, the meeting twists his life into a complicated torrent of relationships. Eriri Spencer Sawamura, his half-foreigner childhood friend who’s always valued her relationship with MC. Kasumigaoka Utaha, a cold, composed renowned literary genius who shoves everyone aside from our protagonist. What is this? An eroge introduction?\n\n\n\nThe tale of a small not quite doujin circle, but not quite indie studio’s journey through the tough territory of comiket and beyond.\n\n\n\nNote: Includes episode 0.','\n',char(10)),7.3,'TV',2,0,'24 min','A-1 Pictures','WINTER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx20657-pMZBj6K6mLhi.jpg','["Comedy","Romance","Slice of Life"]',181557,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20661,23283,'Zankyou no Terror','Terror in Resonance',replace('Painted in red, the word "VON" is all that is left behind after a terrorist attack on a nuclear facility in Japan. The government is shattered by their inability to act, and the police are left frantically searching for ways to crack down the perpetrators. The public are clueless—until, six months later, a strange video makes its way onto the internet. In it, two teenage boys who identify themselves only as "Sphinx" directly challenge the police, threatening to cause destruction and mayhem across Tokyo. Unable to stop the mass panic quickly spreading through the city and desperate for any leads in their investigation, the police struggle to act effectively against these terrorists, with Detective Kenjirou Shibazaki caught in the middle of it all.\n\n\n\nZankyou no Terror tells the story of Nine and Twelve, the two boys behind the masked figures of Sphinx. They should not exist, yet they stand strong in a world of deception and secrets while they make the city fall around them, all in the hopes of burying their own tragic truth.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'23 min','MAPPA','SUMMER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20661-aCR7QgzDfOSI.png','["Drama","Mystery","Psychological","Thriller"]',296866,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20665,23273,'Shigatsu wa Kimi no Uso','Your lie in April','Piano prodigy Arima Kousei dominated the competition and all child musicians knew his name. But after his mother, who was also his instructor, passed away, he had a mental breakdown while performing at a recital. This resulted in him no longer being able to hear the sound of his piano playing. Two years later, Kousei hasn’t touched the piano and views the world without any flair or color. He was content at living out his life with his good friends Tsubaki and Watari until, one day, a girl changed everything. Miyazono Kaori is a pretty, free spirited violinist whose playing style reflects her personality. Kaori helps Kousei return to the music world and show that it should be free and mold breaking unlike the structured and rigid style Kousei was used to.',8.4,'TV',2,0,'23 min','A-1 Pictures','FALL 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20665-TLgkL8T8IRFd.png','["Drama","Music","Romance","Slice of Life"]',625383,1794735119,22,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20668,23289,'Gekkan Shoujo Nozaki-kun','Monthly Girls'' Nozaki-kun',replace('You know how the story goes: girl crushes on guy, girl confesses feelings to guy, guy mistakes confession for a job application. Okay, maybe that''s not how it usually goes, but that''s what happens when Chiyo Sakura finally gets up the nerve to tell her classroom crush Nozaki how she feels. Since she doesn''t know that he''s secretly a manga artist who publishes under a female pen name, and he doesn''t know that she doesn''t know, he misunderstands and offers her a chance to work as his assistant instead of a date! But while it''s not flowers and dancing, it is a chance to get closer to him, so Chiyo gamely accepts. And when Nozaki realizes how useful Chiyo can be in figuring out what girls find romantic, he''ll be spending even more time with her "researching" while remaining completely clueless. Could Chiyo''s romantic frustration possibly get any more drawn out of proportion?\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.6,'TV',2,0,'23 min','Doga Kobo','SUMMER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20668-6UslJY5NDYNh.png','["Comedy","Romance","Slice of Life"]',225633,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20698,23847,'Yahari Ore no Seishun Love Come wa Machigatteiru. Zoku','My Teen Romantic Comedy SNAFU TOO!',replace('Yahari Ore no Seishun Love Comedy wa Machigatteiru. Zoku picks up immediately after the events of the first season, continuing the adventures of the Volunteer Service Club—the dispassionate Hachiman Hikigaya, the cheerful Yui Yuigahama, and the competitive Yukino Yukinoshita—as it dedicates itself to helping any student with issues that they may face.\n\n\n\nWith the rift among his own group widening, Hachiman begins to realize that his knack for quickly getting to the root of other people''s troubles is a double-edged sword: sometimes the best solution is not necessarily the most appropriate one.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.1,'TV',2,0,'24 min','feel.','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20698-YZIYor2zW3Ta.png','["Comedy","Drama","Romance","Slice of Life"]',282225,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20727,24439,'Kekkai Sensen','Blood Blockade Battlefront',replace('A breach between Earth and the netherworlds has opened up over the city of New York, trapping New Yorkers and creatures from other dimensions in an impenetrable bubble. They''ve lived together for years, in a world of crazy crime sci-fi sensibilities. Now someone is threatening to sever the bubble, and a group of stylish superhumans is working to keep it from happening.\n\n\n\n(Source: Anime News Network)\n\n\n\nNote: The last episode aired with a runtime of ~46 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),7.4,'TV',2,0,'25 min','bones','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20727-jgVnxLCHAKqZ.jpg','["Action","Comedy","Supernatural"]',234106,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20745,24703,'High School DxD BorN','High School DxD BorN',replace('The Red Dragon Emperor, Issei Hyoudou, and the Occult Research Club are back in action as summer break comes for the students of Kuoh Academy. After their fight with Issei’s sworn enemy, Vali and the Chaos Brigade, it is clear just how inexperienced Rias Gremory''s team is. As a result, she and Azazel lead the club on an intense training regime in the Underworld to prepare them for the challenges that lie ahead.\n\n\n\nWhile they slowly mature as a team, Issei will once again find himself in intimate situations with the girls of the Occult Research Club. Meanwhile, their adversaries grow stronger and more numerous as they rally their forces. And with the sudden appearance of Loki, the Evil God of Norse Mythology, the stage is set for epic fights and wickedly powerful devils in High School DxD BorN!\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.1,'TV',2,0,'24 min','TNK','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20745-HzWTPFv0P13I.jpg','["Action","Comedy","Ecchi","Fantasy","Romance"]',180653,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20755,24833,'Ansatsu Kyoushitsu','Assassination Classroom','The students of class 3-E have a mission: kill their teacher before graduation. He has already destroyed the moon, and has promised to destroy the Earth if he can not be killed within a year. But how can this class of misfits kill a tentacled monster, capable of reaching Mach 20 speed, who may be the best teacher any of them have ever had?',7.9,'TV',2,0,'23 min','Lerche','WINTER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20755-dWrhs569YGUO.jpg','["Action","Comedy","Drama","Supernatural"]',639612,1794735119,22,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20770,25013,'Akatsuki no Yona','Yona of the Dawn',replace('Since Yona is the only princess of a grand kingdom, she has been raised with great care by her doting father and protected by her childhood friend/guard Hak and others. However, her fate changes on her 16th birthday, when her beloved cousin Soo-won murders her father to claim the throne. She flees the castle to Hak''s hometown and begins her new life.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.9,'TV',2,0,'24 min','Studio Pierrot','FALL 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20770-brCDvhTXlums.png','["Action","Adventure","Comedy","Drama","Fantasy","Romance"]',221593,1794735120,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20789,23755,'Nanatsu no Taizai','The Seven Deadly Sins',replace('When they were accused of trying to overthrow the monarchy, the feared warriors the Seven Deadly Sins were sent into exile. Princess Elizabeth discovers the truth - the Sins were framed by the king''s guard, the Holy Knights - too late to prevent them from assassinating her father and seizing the throne!\n\nNow the princess is on the run, seeking the Sins to help her reclaim the kingdom. But the first Sin she meets, Meliodas, is a little innkeeper with a talking pig. He doesn''t even have a real sword! Have the legends of the Sins'' strength been exaggerated?\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.2,'TV',2,0,'25 min','A-1 Pictures','FALL 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20789-Ma5ouSYPkru9.jpg','["Action","Adventure","Comedy","Ecchi","Fantasy","Supernatural"]',538782,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20792,28701,'Fate/stay night: Unlimited Blade Works 2nd Season','Fate/stay night: Unlimited Blade Works 2nd Season',replace('The Holy Grail War continues, with each Master and Servant duo making their move for the omnipotent wish granter. Caster’s plans have been set in motion, beginning with taking Saber captive while Rin and Archer go their separate ways to continue their fights on their own. Without Saber’s aid, Shirou’s principles are put to the ultimate test. With many battles to come with expected and unexpected enemies, Shirou’s resolve begins to take form. Is his desire to protect people and become a hero, genuine? Or are they simply borrowed feelings? And will it be enough to carry him to the end?\n\n\n\n(Source: Aniplex of America)','\n',char(10)),8.2,'TV',2,0,'24 min','ufotable','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20792-Q53sZsUAh5FF.jpg','["Action","Drama","Fantasy","Supernatural"]',207622,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20799,26055,'JoJo no Kimyou na Bouken: Stardust Crusaders - Egypt-hen','JoJo''s Bizarre Adventure: Stardust Crusaders - Battle in Egypt',replace('After 30 days of travel across the world, plagued with countless battles, Jotaro and his companions have finally arrived in Egypt! Now only the strongest "Stand" users remain to rebuff our heroes'' final march on Cairo: The Nine Egyptian Gods, Dio''s most zealous servants. Will the Joestar line fall to the monstrous vampire, or can Jotaro defeat Dio and save his mother''s life?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.3,'TV',2,0,'24 min','david production','WINTER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20799-S1eyqBDlx51E.jpg','["Action","Adventure","Drama","Supernatural"]',297783,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20807,30240,'Prison School','Prison School',replace('Hachimitsu Private Academy was a revered and elite all-girls'' boarding school on the outskirts of Tokyo...once upon a time. But with the new school year comes a revision to school policy: Boys are to be admitted into the student body for the first time ever. But on his first day at Hachimitsu, Kiyoshi Fujino discovers that he''s one of only five boys enrolled at the school. Their numbers overwhelmed by the thousand girls in the student body, is it heaven or hell that awaits these five (un)fortunates?!.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.3,'TV',2,0,'24 min','J.C.STAFF','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20807-8nFoO0AUdGsy.jpg','["Comedy","Ecchi"]',253435,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20829,26243,'Owari no Seraph','Seraph of the End: Vampire Reign',replace('The story takes place in a world where an unknown virus has killed the entire human population except for children under 13. Those children were then enslaved by vampires. The manga centers on Yuichiro Hyakuya, a human who dreams of becoming strong enough to kill all vampires.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.3,'TV',2,0,'24 min','WIT STUDIO','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20829-pgsXVjrfyI5V.png','["Action","Drama","Fantasy","Mystery","Supernatural"]',335284,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20832,29803,'Overlord','Overlord',replace('The story takes place in the year 2138 when virtual reality gaming is booming. Yggdrasil, a popular online game is quietly shut down one day. However, the protagonist Momonga decides to not log out. Momonga is then transformed into the image of a skeleton as "the most powerful wizard." The world continues to change, with non-player characters (NPCs) beginning to feel emotion. Having no parents, friends, or place in society, this ordinary young man Momonga then strives to take over the new world the game has become.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.6,'TV',2,0,'24 min','MADHOUSE','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20832-vUNm5zrYWifc.jpg','["Action","Adventure","Fantasy"]',413766,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20850,27899,'Tokyo Ghoul √A','Tokyo Ghoul √A',replace('The ghouls of Anteiku invaded the Aogiri''s site in order to rescue Ken Kaneki who is being tortured. Due to provocation, he unleashed greater power enough to defeat Yamori. To become stronger, he decided to join Aogiri and left Anteiku. Ghoul investigators also making their moves by collecting information about the eye-patched ghoul - Ken Kaneki.\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.7,'TV',2,0,'24 min','Studio Pierrot','WINTER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20850-glDf9EMKeCwe.jpg','["Action","Drama","Horror","Mystery","Psychological","Supernatural"]',414077,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20872,27775,'Plastic Memories','Plastic Memories',replace('This story takes place in a future not too far away when androids that look exactly like humans begin to spread across the world. The android production company SA Corp. produced Giftia, a new kind of android that has the most amount of emotion and human-like qualities out of any other model ever seen. However, due to problems in technology, the androids have a service life, and once they pass that, they... Well, it gets pretty bad. For this reason, SA Corp. creates a terminal service in order to retrieve Giftia that have gone past their service life. A new employee at the terminal service named Tsukasa Mizugaki forms a team with the Giftia Isla to retrieve the other androids, but...\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.7,'TV',2,0,'24 min','Doga Kobo','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20872-j5PBzzVtrYDM.jpg','["Drama","Romance","Sci-Fi","Slice of Life"]',263828,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20910,29786,'Shimoneta to Iu Gainen ga Sonzai Shinai Taikutsu na Sekai','SHIMONETA: A Boring World Where the Concept of Dirty Jokes Doesn’t Exist',replace('The novel''s story is set 16 years after the "Law for Public Order and Morals in Healthy Child-Raising" banned coarse language in the country. Tanukichi Okuma enrolls in the country''s leading elite public morals school and is soon invited into the Anti-Societal Organization (SOX) by its founder, Ayame Kajou. As a member blackmailed into joining by Ayame, Tanukichi ends up taking part in obscene acts of terrorism against the talented student council president Anna (for whom Tanukichi has a crush).\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.9,'TV',2,0,'23 min','J.C.STAFF','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20910-U7txwG3o9gma.jpg','["Comedy","Ecchi"]',211313,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20920,28121,'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka','Is It Wrong to Try to Pick Up Girls in a Dungeon?',replace('Some adventurers delve into the sprawling labyrinths beneath the city of Orario to find fame and fortune. Others come to test their skills against the legions of monsters lurking in the darkness below. However, Bell Cranel’s grandfather told him a different reason: it’s a great place to rescue (and subsequently meet) girls! Now that Bell’s a dungeon delver himself, the ladies he’s encountering aren’t the helpless damsels in distress he’d imagined, and one of them, the beautiful swordswoman Ais Wallenstein, keeps rescuing Bell instead. As embarrassing as that is, it’s nothing compared to what happens when goddesses get involved. Freya, Hephaistos, and Loki, with their powerful Familias, are intimidating enough, but there’s one goddess whose relationship with Bell is certain to spark trouble.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.3,'TV',2,0,'24 min','J.C.STAFF','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20920-MTREwZOG4BAD.jpg','["Action","Adventure","Comedy","Fantasy","Romance"]',404281,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20923,28171,'Shokugeki no Souma','Food Wars!',replace('Ever since he was little, Souma Yukihira’s main goals have been to beat his father in a cooking contest and take over the family diner. That’s why, when his dad suddenly announces that he’s shutting the restaurant down and sending Souma to cooking school, Souma is shocked. However, Totsuki Academy is no ordinary cooking school. This elite institution is filled with culinary giants like Erina “God Tongue” Nakiri, who does her best to keep a lowly short-order like Souma from even making it inside the door. However, if the snobs can dish it out, Souma can serve it up, and when he learns that only a handful of the students manage to graduate every year, he swears that the only way he’ll leave is as number one!\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.8,'TV',2,0,'25 min','J.C.STAFF','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20923-pNT38pjW3RFH.jpg','["Comedy","Ecchi"]',409143,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20931,28223,'Death Parade','Death Parade',replace('When two people die at the same time, they’re sent to a place that’s neither heaven nor hell—a lavish bar between worlds where the stakes are high and the rules are simple: if you win you live again, if you die… you’re gone for good.\n\n\n\nDecim is the bartender charged with serving the souls who enter Quindecim. He may make a mean cocktail, but his true profession is to play the role of arbiter—a judge who determines whether or not a soul is worthy of reincarnation. To aid in his judgment, the bar’s patrons are forced to play simple games laced with sadistic twists designed to bring their true natures to light. To Decim, judgment has always been black and white—that is—until he meets a mysterious young woman whose fate seems impossible to decide. His indecision shakes the very foundation of the games and raises the biggest question of all: Who is fit to judge the dead?\n\n\n\n(Source: Funimation)','\n',char(10)),8,'TV',2,0,'23 min','MADHOUSE','WINTER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx20931-bktYqOcxPERi.jpg','["Drama","Mystery","Psychological","Supernatural","Thriller"]',474522,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20954,28851,'Koe no Katachi','A Silent Voice',replace('After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends.\n\n\n\n(Source: Eleven Arts)','\n',char(10)),8.8,'MOVIE',2,0,'130 min','Kyoto Animation','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20954-sYRfE5jQRtSB.jpg','["Drama","Romance","Slice of Life"]',733239,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20958,25777,'Shingeki no Kyojin Season 2','Attack on Titan Season 2',replace('Eren Jaeger swore to wipe out every last Titan, but in a battle for his life he wound up becoming the thing he hates most. With his new powers, he fights for humanity''s freedom facing the monsters that threaten his home. After a bittersweet victory against the Female Titan, Eren finds no time to rest—a horde of Titans is approaching Wall Rose and the battle for humanity continues!\n\n\n\n(Source: Funimation)','\n',char(10)),8.5,'TV',2,0,'25 min','WIT STUDIO','SPRING 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20958-HuFJyr54Mmir.jpg','["Action","Drama","Fantasy","Mystery"]',748889,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20966,28677,'Yamada-kun to 7-nin no Majo','Yamada and the Seven Witches','Ryu Yamada is a second year student at Suzaku High. Ryu is always late for school, naps in class and gets abysmal grades. His life is a dead bore. The beautiful Urara Shiraishi, on the other hand, is Suzaku High''s brightest student. One day, without explanation, their bodies are swapped! Ryu ends up in Urara''s body, and Urara in Ryu''s.',7.3,'TV',2,0,'24 min','LIDENFILMS','SPRING 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20966-HboUtUzEKWl6.jpg','["Comedy","Mystery","Romance","Supernatural"]',192986,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20987,28825,'Himouto! Umaru-chan','Himouto! Umaru-chan',replace('Umaru is a renowned beautiful 16-year-old girl, living with her elder brother Taihei. She''s a perfect little sister: Popular, smart, kind-hearted, everybody admires her. So who would believe Umaru keeps a certain secret? Sleeping, gaming, watching TV, eating junk food, drinking cola… that''s almost all she does at home, leaving all the housework to her brother.\n\n\n\n(Source: Crunchyroll, edited)','\n',char(10)),6.7,'TV',2,0,'24 min','Doga Kobo','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20987-9Tq7kZTeJPMo.jpg','["Comedy","Slice of Life"]',175593,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20992,28891,'Haikyuu!! 2nd Season','HAIKYU!! 2nd Season',replace('Following their participation at the Inter-High, the Karasuno High School volleyball team attempts to refocus their efforts, aiming to conquer the Spring tournament instead.\n\n\n\nWhen they receive an invitation from long-standing rival Nekoma High, Karasuno agrees to take part in a large training camp alongside many notable volleyball teams in Tokyo and even some national level players. By playing with some of the toughest teams in Japan, they hope not only to sharpen their skills, but also come up with new attacks that would strengthen them. Moreover, Hinata and Kageyama attempt to devise a more powerful weapon, one that could possibly break the sturdiest of blocks.\n\n\n\nFacing what may be their last chance at victory before the senior players graduate, the members of Karasuno''s volleyball team must learn to settle their differences and train harder than ever if they hope to overcome formidable opponents old and new—including their archrival Aoba Jousai and its world-class setter Tooru Oikawa.\n\n\n\n[Written by MAL Rewrite]','\n',char(10)),8.6,'TV',2,0,'24 min','Production I.G','FALL 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20992-aHgNbcalVEqk.png','["Comedy","Drama","Sports"]',405282,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20993,28927,'Owari no Seraph: Nagoya Kessen-hen','Seraph of the End: Battle in Nagoya',replace('Yuuichirou has reunited with Mikaela at the Shinjuku Battle. But Mikaela was turned into a vampire... To save the "family," and to protect his fellow members, Yuuichirou needed to gain knowledge and power. He searched for ways to bring back vampire to human beings, and at the same time, trained hard working on the Cursed Gear. \n\n\n\nMeanwhile, Kureto calls Guren and tells him a shocking truth. That in one month, the main unit of the vampire will start attacking Tokyo. To get a head start against vampires, Kureto orders Guren to go to Nagoya. The noble extermination mission is about to open fire!\n\n\n\n(Source: Official website)','\n',char(10)),7.5,'TV',2,0,'23 min','WIT STUDIO','FALL 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20993-c34UTma2bCcv.jpg','["Action","Drama","Fantasy","Supernatural"]',201287,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20994,28907,'GATE: Jieitai Kanochi nite, Kaku Tatakaeri','Gate',replace('The military fantasy series begins when a gate appears in Tokyo''s Ginza district sometime in the 21st century. From the gate pours out monsters, knights from middle-age Europe, and other fantasy-like beings, and they kill many of the citizens of Tokyo. This event is known as the Ginza Incident.\n\n\n\nThe government sends a small group of soldiers from the Japanese Self-Defense Forces (a replacement for Japan''s military) to the alternate world beyond the gate. Led by otaku soldier Youji, they find that the villages in the world are being attacked by a dragon. An elf girl who is a survivor from the dragon''s rampage joins the group in their travels across the dangerous new world.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.4,'TV',2,0,'23 min','A-1 Pictures','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20994-pSDk4I58jAK5.jpg','["Action","Adventure","Fantasy"]',201763,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(20997,28999,'Charlotte','Charlotte(シャーロット)',replace('Very few adolescent boys and girls develop special abilities. Yuu Otosaka is one such man who uses his ability, unbeknownst to others, in order to lead a satisfying school life. Then one day, a girl named Nao Tomori suddenly appears before him. Their encounter reveals the destiny for wielders of special abilities. This is a story of those gifted youth and how they spend their adolescence.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.5,'TV',2,0,'24 min','P.A.WORKS','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20997-axVYrsIfjtYJ.jpg','["Comedy","Drama","Romance","Sci-Fi","Supernatural"]',442322,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21049,30015,'ReLIFE','ReLIFE','The story follows Kaizaki Arata, a 27-year-old jobless man, who fails at every job interview he had after quitting his last company. His life changes after he met Yoake Ryou of the ReLife Research Institute, who offered him a drug that can change his appearance to 17-years-old and to become a subject in an experiment for one year. Thus, he begins his life as a high school student once more.',7.8,'ONA',2,0,'24 min','TMS Entertainment','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21049-4AHSLeiDE9eg.png','["Comedy","Drama","Romance","Slice of Life"]',265005,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21058,30123,'Akagami no Shirayuki-hime','Snow White with the Red Hair',replace('In the kingdom of Tanbarun lives Shirayuki, an independent and strong-willed young woman. Her resourceful intelligence has led her become a skilled pharmacist, but her most defining trait is her shock of beautiful apple-red hair. Her dazzling mane gets her noticed by the prince of the kingdom, but instead of romancing her, he demands she be his concubine. Shirayuki refuses, chops off her lovely locks, and runs away to the neighboring kingdom of Clarines. There, she befriends a young man named Zen, who, SURPRISE, is also a prince, although with a much better temperament than the previous one. Watch as Shirayuki finds her place in the new kingdom, and in Zen’s heart.\n\n\n\n(Source: FUNimation)','\n',char(10)),7.7,'TV',2,0,'24 min','bones','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21058-GRqasG1xk3bD.jpg','["Drama","Fantasy","Romance"]',185103,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21087,30276,'One Punch Man','One-Punch Man',replace('Saitama has a rather peculiar hobby, being a superhero, but despite his heroic deeds and superhuman abilities, a shadow looms over his life. He''s become much too powerful, to the point that every opponent ends up defeated with a single punch.\n\n\n\nThe lack of challenge has driven him into a state of apathy, as he watches his life pass by having lost all enthusiasm, at least until he''s unwillingly thrust in the role of being a mentor to the young and revenge-driven Genos.','\n',char(10)),8.2,'TV',2,0,'24 min','MADHOUSE','FALL 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21087-B5DHjqZ3kW4b.jpg','["Action","Comedy","Sci-Fi","Supernatural"]',780721,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21092,30296,'Rakudai Kishi no Cavalry','Chivalry of a Failed Knight',replace('The "school sword action" story revolves around Magic Knights, modern magic-users who fight with weapons converted from their souls. Ikki Kurogane goes to a school for these Magic Knights, but he is the "Failed Knight" or "Worst One" who is failing because he has no magical skills. However, one day, he is challenged to a duel by Stella, a foreign princess and the "Number One" student. In this duel, "the loser must be obedient for life."\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.2,'TV',2,0,'23 min','SILVER LINK.','FALL 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx21092-1NML6TdngmBq.jpg','["Action","Ecchi","Fantasy","Romance"]',250988,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21093,30307,'Monster Musume no Iru Nichijou','Monster Musume: Everyday Life With Monster Girls',replace('Monsters: they''re real, and they want to date us!\n\n\n\nThree years ago, the world learned that harpies, centaurs, catgirls, and all manners of fabulous creatures are not merely fiction; they are flesh and blood - not to mention scale, feather, horn, and fang. Thanks to the "Cultural Exchange Between Species Act," these once-mythical creatures have assimilated into society, or at least, they''re trying.\n\n\n\nWhen a hapless human teenager named Kurusu Kimihito is inducted as a "volunteer" into the government exchange program, his world is turned upside down. A snake-like lamia named Miia comes to live with him, and it is Kurusu''s job to take care of her and make sure she integrates into his everyday life.\n\n\n\nUnfortunately for Kurusu, Miia is undeniably sexy, and the law against interspecies breeding is very strict. Even worse, when a ravishing centaur girl and a flirtatious harpy move in, what''s a full-blooded teenage human with raging hormones to do?!\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.5,'TV',2,0,'24 min','Lerche','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21093-fVFDznAnJZmL.png','["Comedy","Ecchi","Fantasy","Romance"]',173925,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21127,30484,'Steins;Gate 0','Steins;Gate 0',replace('The eccentric, self-proclaimed mad scientist Rintarou Okabe has become a shell of his former self. Depressed and traumatized after failing to rescue his friend, he has decided to forsake his mad scientist alter ego and live as an ordinary college student. Surrounded by friends who know little of his time travel experiences, Okabe spends his days trying to forget the horrors of his adventures alone.\n\n\n\nWhile working as a receptionist at a college technology forum, Okabe meets the short, spunky Maho Hiyajo, who\nlater turns out to be the interpreter at the forum''s presentation, conducted by Professor Alexis Leskinen. In front of a stunned crowd, Alexis and Maho unveil Amadeus—a revolutionary AI capable of storing a person''s memories and creating a perfect simulation of that person complete with their personality and quirks. Meeting with Maho and Alexis after the presentation, Okabe learns that the two were Kurisu''s colleagues in university, and that they have simulated her in Amadeus. Hired by Alexis to research the simulation''s behavior, Okabe is given the chance to interact with the shadow of a long-lost dear friend. Dangerously tangled in the past, Okabe must face the harsh reality and carefully maneuver around the disastrous consequences that come with disturbing the natural flow of time.','\n',char(10)),8.4,'TV',2,0,'24 min','WHITE FOX','SPRING 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21127-7ARWZkDXKiiD.jpg','["Drama","Psychological","Sci-Fi","Thriller"]',226873,1794735120,23,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21128,30503,'Noragami ARAGOTO','Noragami Aragoto',replace('Life for minor god Yato isn''t getting any easier. He''s still broke, shrineless, and his partner-slash-sword-regalia has zero respect for him. Worse yet, Bishamon, one of the deadliest war gods, is after his life. Blaming him for the death of her past regalia, she won''t stop until she kills him. But there''s more to that story than she could ever realize. And as if that''s not bad enough, there''s someone working against her behind the scenes! Can Yato take on a god as powerful as Bishamon? Or will things take a more dangerous turn?\n\n\n\nBetween all of this godly drama and even more dangerous battles, Yato still needs to figure out how to help Hiyori. But all options lead to losing her, and he''s not willing to make that choice – no matter what.\n\n\n\nFive yen doesn''t even begin to cover his trouble!\n\n\n\n(Source: Funimation)','\n',char(10)),8,'TV',2,0,'24 min','bones','FALL 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21128-eQgH3TG4nngo.jpg','["Action","Adventure","Comedy","Supernatural"]',315235,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21170,30654,'Ansatsu Kyoushitsu 2nd Season','Assassination Classroom Second Season',replace('The students return as school is back in session for the second semester. Following their exploits on the island during summer vacation, Class 3-E continues to sharpen their blades with their sights set on their teacher, the slippery Koro-sensei. They have more to worry about than just their teacher, however, as enemy assassins, both old and new, are out for the increased bounty on the octopus'' head.\n\n\n\nMoreover, their rivals in Class A, as well as Kunugigaoka Junior High''s fearsome principal, stand to block Class E from achieving academic excellence. With all of these obstacles opposing them, the group must continue to work together in order to overcome their foes and accomplish their goal of successfully assassinating their teacher.','\n',char(10)),8.3,'TV',2,0,'23 min','Lerche','WINTER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21170-kbcfTTZGSaFt.jpg','["Action","Comedy","Drama","Supernatural"]',375855,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21175,30694,'Dragon Ball Super','Dragon Ball Super',replace('After 18 years, we have the newest Dragon Ball story from creator Akira Toriyama. With Majin Buu defeated, Goku has taken a completely new role as...a radish farmer?! With Earth at peace, our heroes have settled into normal lives. But they can’t get too comfortable. Far away, the powerful God of Destruction, Beerus, awakens to a prophecy revealing his demise at the hands of an even more formidable being. When his search for the Saiyan God brings him to Earth, can Goku and his friends take on their strongest foe yet?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.3,'TV',2,0,'24 min','Toei Animation','SUMMER 2015','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21175-EH06qlfF8TnB.jpg','["Action","Adventure","Comedy","Fantasy","Sci-Fi"]',223479,1794735120,131,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21196,28623,'Koutetsujou no Kabaneri','Kabaneri of the Iron Fortress','As the world is in the middle of an industrial revolution, a monster appears that cannot be defeated unless its heart, which is protected by a layer of iron, is pierced. By infecting humans with its bite, the monster can create aggressive and undead creatures known as Kabane. On the island Hinomoto, located in the far east, people have built stations to shelter themselves from these creatures. People access the station, as well as transport wares between them, with the help of a locomotive running on steam, called Hayajiro. Ikoma, a boy who lives in the Aragane station and helps to build Hayajiro, creates his own weapon called Tsuranukizutsu in order to defeat the creatures. One day, as he waits for an opportunity to use his weapon, he meets a girl named Mumei, who is excused from the mandatory Kabane inspection. During the night, Ikoma meets Mumei again as he sees Hayajiro going out of control. The staff on the locomotive has turned into the creatures. The station, now under attack by Kabane, is the opportunity Ikoma has been looking for.',7.1,'TV',2,0,'23 min','WIT STUDIO','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21196-2PfPfIDrxKki.jpg','["Action","Drama","Fantasy","Horror","Supernatural"]',200869,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21202,30831,'Kono Subarashii Sekai ni Shukufuku wo!','KONOSUBA -God''s blessing on this wonderful world!',replace('Kazuma Satou decides that today is the day to get out of the house for a bit. Since he dies, pointlessly, it''s clearly a bad choice. The goddess who greets him in the afterlife, however, offers him a chance to be reborn in a world not unlike that of a video game, and as a bonus she''ll even throw in a cool item or power! Can''t possibly be a bad choice, right? Except he arrives with no money at all, dead average skills, and his "bonus" isn''t useful at all--since he picked the goddess, Aqua, herself. How are the two of them supposed to defeat the evil Devil King and live happily ever after? Well, for them, it probably starts with day laboring rather than adventuring. And it''s only going to get more disappointing from there!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.9,'TV',2,0,'23 min','Studio DEEN','WINTER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21202-mPOr80AEjUcZ.png','["Adventure","Comedy","Ecchi","Fantasy"]',529035,1794735119,10,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21234,31043,'Boku dake ga Inai Machi','ERASED','Satoru Fujinuma is a 29 year old manga artist struggling to make a name for himself following his debut. But, that was not the only thing in his life that Satoru was feeling frustrated about… He has a unique supernatural ability of being forced to prevent deaths and catastrophes by being sent back in time before the incident occurred, repeating time until the accident is prevented. One day, he gets involved in an accident that has him framed as a murderer. Desperate to save the victim, he sends himself back in time only to find himself as a grade-schooler one month before fellow classmate Kayo Hinazuki went missing. Satoru now embarks on a new quest: to save Kayo and solve the mystery behind her disappearance.',8.1,'TV',2,0,'23 min','A-1 Pictures','WINTER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21234-XmqW39aQ9o7O.jpg','["Drama","Mystery","Psychological","Supernatural","Thriller"]',616616,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21311,31478,'Bungou Stray Dogs','Bungo Stray Dogs',replace('Stalked by a beastly white tiger, Atsushi Nakajima has no idea that the menace lives inside him—a power that catches the attention of the Armed Detective Agency. Using inhuman abilities to combat crime, this team takes Atsushi under the wing of their most eccentric member, Dazai. Together, they tear through mafia-muddled mysteries while enemies keep an eye on the tiger’s lofty bounty.\n\n\n\n(Source: Funimation)','\n',char(10)),7.7,'TV',2,0,'24 min','bones','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21311-hAXyT8Yoh6G9.jpg','["Action","Comedy","Mystery","Supernatural"]',428204,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21355,31240,'Re:Zero kara Hajimeru Isekai Seikatsu','Re:ZERO -Starting Life in Another World-',replace('In the story, Subaru Natsuki is an ordinary high school student who is lost in an alternate world, where he is rescued by a beautiful, silver-haired girl. He stays near her to return the favor, but the destiny she is burdened with is more than Subaru can imagine. Enemies attack one by one, and both of them are killed. He then finds out he has the power to rewind death, back to the time he first came to this world. But only he remembers what has happened since.\n\n\n\n(Source: Anime News Network)\n\n\n\nNotes:\n\n- The first episode aired with a runtime of ~50 minutes as opposed to the standard 25 minute long episode.\n\n- In the Winter 2020 season, Re:ZERO was rebroadcast and re-edited to fit into an hour time-slot. This edit included the first OVA and added slight modifications to certain scenes throughout. It also added an additional scene at the end of the final episode.','\n',char(10)),8.1,'TV',2,0,'25 min','WHITE FOX','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21355-wRVUrGxpvIQQ.jpg','["Action","Adventure","Drama","Fantasy","Psychological","Romance","Thriller"]',638477,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21366,31646,'3-gatsu no Lion','March comes in like a lion',replace('Rei Kiriyama is a 17 year old boy who recently started living alone, financed by his salary as a professional Shogi player. Despite his independence, however, he''s yet to mature emotionally, and his problems continue to haunt him in his daily life. His relationship with his adoptive family is strained, and he has difficulties interacting with his fellow high school students.\n\n\n\nMeanwhile, his professional career in Shogi has entered a slump. Burdened with the heavy expectations placed upon him, his wins and losses are fluctuating as his record and progression into the ranks begin to stagnate.\n\n\n\nAcquainted with Rei are the three Kawamoto sisters: Akari, Hinata, and Momo. Unlike Rei, they live happily in their modest home, which they warmly welcome Rei into as if he were one of their own.  He frequently visits the family, interacting with them and receiving the kind of care and affection he never quite had while under his foster home.\n\nThis is the story of Rei''s triumphs and failures, relationships new and old, and his growth as a person.','\n',char(10)),8.3,'TV',2,0,'25 min','Shaft','FALL 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21366-0wrYK0kjKeFn.jpg','["Drama","Slice of Life"]',217429,1794735120,22,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21385,31722,'Nanatsu no Taizai: Seisen no Shirushi','The Seven Deadly Sins: Signs of A Holy War','Four-part original story by mangaka Nakaba Suzuki. Having taken the kingdom of Leones back from Holy Knights, the Seven Deadly Sins, along with Elizabeth and Hawk, can finally enjoy peaceful lives they earned. However, with premonitions of a new threat looming, their happy, ordinary days are about to end.',6.7,'TV',2,0,'25 min','A-1 Pictures','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21385-0rOBu6r4C4b9.jpg','["Action","Adventure","Comedy","Ecchi","Fantasy","Supernatural"]',174707,1794735120,4,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21403,31765,'Sword Art Online: Ordinal Scale','Sword Art Online the Movie: Ordinal Scale',replace('In 2022, the world of virtual reality was upended by the arrival of a new invention from a genius programmer, Akihiko Kayaba. Called NerveGear, it was the first full-dive system and with it, came endless possibilities to VRMMORPGs.\n\n\n\nIn 2026, a new machine called the Augma is developed to compete against the NerveGear and its successor, the Amusphere. A next-gen wearable device, the Augma doesn''t have a full-dive function like its predecessors. Instead, it uses Augmented Reality to get players into the game. It is safe, user-friendly and lets users play while they are conscious, making it an instant hit on the market. The most popular game on the system is “Ordinal Scale” (aka: OS), an ARMMORPG developed exclusively for the Augma.\n\n\n\nAsuna and the gang have already been playing OS for a while, by the time Kirito decides to join them. They’re about to find out that Ordinal Scale isn’t all fun and games…\n\n\n\n(Source: Official website)','\n',char(10)),7.3,'MOVIE',2,0,'119 min','A-1 Pictures','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx21403-k8DZhZ3x1BCO.png','["Action","Adventure","Fantasy","Romance","Sci-Fi"]',198523,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21421,31798,'Kiznaiver','Kiznaiver',replace('The fictional Japanese city named Sugomori City is built on reclaimed land. But as the years go by, the city''s population is decreasing. One day, Sonozaki tells her classmate Katsuhira: "You have been selected to be a Kiznaiver." The Kizuna System, which allows Katsuhira to share his wounds, connects him to the classmates whose lives and personalities completely differ from his. The Kizuna System is an incomplete system for the implementation of world peace that connects people through wounds. All those who are connected to this system are called Kiznaivers. When one Kiznaiver is wounded, the system divides and transmits the wound among the other Kiznaivers.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.1,'TV',2,0,'24 min','TRIGGER','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21421-5y8ryXsMB7aJ.jpg','["Drama","Romance","Sci-Fi"]',205750,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21428,31859,'Hai to Gensou no Grimgar','Grimgar of Fantasy and Ash',replace('Fear, survival, instinct. Thrown into a foreign land with nothing but hazy memories and the knowledge of their name, they can feel only these three emotions resonating deep within their souls. A group of strangers is given no other choice than to accept the only paying job in this game-like world—the role of a soldier in the Reserve Army—and eliminate anything that threatens the peace in their new world, Grimgar.\n\n\n\nWhen all of the stronger candidates join together, those left behind must create a party together to survive: Manato, a charismatic leader and priest; Haruhiro, a nervous thief; Yume, a cheerful hunter; Shihoru, a shy mage; Mogzo, a kind warrior; and Ranta, a rowdy dark knight. Despite its resemblance to one, this is no game—there are no redos or respawns; it is kill or be killed.\n\n\n\nIt is now up to this ragtag group of unlikely fighters to survive together in a world where life and death are separated only by a fine line.','\n',char(10)),7.4,'TV',2,0,'24 min','A-1 Pictures','WINTER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21428-dFVIHeZ8McBe.jpg','["Action","Adventure","Drama","Fantasy"]',187015,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21450,31933,'JoJo no Kimyou na Bouken: Diamond wa Kudakenai','JoJo''s Bizarre Adventure: Diamond is Unbreakable',replace('It''s the year 1999, 11 years after Jotaro Kujo''s desperate fight against DIO in Egypt. Jotaro meets with Josuke Higashikata, the illegitimate son of his grandfather Joseph Joestar. He discovers that Josuke also has the same "Stand" power and that a new threat is surfacing in Morioh City.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.4,'TV',2,0,'24 min','david production','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21450-D7XFwEQjZ5GA.jpg','["Action","Adventure","Drama","Mystery","Supernatural"]',322834,1794735119,39,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21459,31964,'Boku no Hero Academia','My Hero Academia',replace('What would the world be like if 80 percent of the population manifested extraordinary superpowers called “Quirks” at age four? Heroes and villains would be battling it out everywhere! Becoming a hero would mean learning to use your power, but where would you go to study? U.A. High''s Hero Program of course! But what would you do if you were one of the 20 percent who were born Quirkless?\n\n\n\nMiddle school student Izuku Midoriya wants to be a hero more than anything, but he hasn''t got an ounce of power in him. With no chance of ever getting into the prestigious U.A. High School for budding heroes, his life is looking more and more like a dead end. Then an encounter with All Might, the greatest hero of them all gives him a chance to change his destiny…\n\n\n\n(Source: VIZ Media)','\n',char(10)),7.6,'TV',2,0,'24 min','bones','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21459-nYh85uj2Fuwr.jpg','["Action","Adventure","Comedy"]',890747,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21507,32182,'Mob Psycho 100','Mob Psycho 100',replace('The story revolves around "Mob," a boy who will explode if his emotional capacity reaches 100%. This boy with psychic powers earned his nickname "Mob" because he does not stand out among other people. He keeps his psychic powers bottled up so he can live normally, but if his emotional level reaches 100, something will overwhelm his entire body.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.4,'TV',2,0,'24 min','bones','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21507-6YUSbh2m0N1p.jpg','["Action","Comedy","Drama","Psychological","Slice of Life","Supernatural"]',639487,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21518,32282,'Shokugeki no Souma: Ni no Sara','Food Wars! The Second Plate',replace('At the Totsuki Culinary Academy, the first rule is survival of the fittest, and if you don''t have what it takes to become a master chef, you need to get out of the kitchen before you get burned. With the wheat of first-year students separated from the chaff, cocky former diner cook Yukihira Souma is one of the handful of kitchen whizzes still standing. As the next round of the Autumn Elections gets underway, can he survive a brutal bento boxing match with the chemistry-obsessed granddaughter of the Academy''s director? And which of the other contenders; Megumi, Ryou, Akira, Hisako, Takumi or sinister dark-horse Subaru; will advance to fight for the gold medal?\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.8,'TV',2,0,'24 min','J.C.STAFF','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21518-uBqzDGIuSxJ5.jpg','["Comedy","Ecchi"]',263806,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21519,32281,'Kimi no Na wa.','Your Name.',replace('Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture.\n\n\n\nOne day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another.\n\n\n\nKimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.5,'MOVIE',2,0,'107 min','CoMix Wave','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21519-SUo3ZQuCbYhJ.png','["Drama","Romance","Supernatural"]',729102,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21552,32353,'BONOBONO (2016)','Bono Bono (2016)','A new adaptation of the adventures of three forest friends - a raccoon, a squirrel and a sea otter.',5.9,'TV_SHORT',1,0,'8 min','Eiken','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b21552-MKlX4WRvlfjp.png','["Comedy"]',817,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21595,32542,'Sakamoto desu ga?','Haven''t You Heard? I''m Sakamoto',replace('First year high school student Sakamoto isn''t just cool, he''s the coolest! Almost immediately after starting school, he began attracting everyone''s attention. The girls love him, and most of the boys resent him. There''s even a boy in the class who works as a model, but who is constantly upstaged by Sakamoto! No matter what tricks the other boys try to play on him, Sakamoto always manages to foil them with ease and grace. Though Sakamoto may seem cool and aloof, he helps others when asked, such as in the case of the boy in his class who was being constantly bullied. No matter what difficulties Sakamoto encounters, he moves through his high school life with confidence and class!\n\n\n\n(Source: MangaHelpers)','\n',char(10)),7.3,'TV',2,0,'24 min','Studio DEEN','SPRING 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21595-vQ658r2Roe1g.jpg','["Comedy","Slice of Life"]',194084,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21613,32615,'Youjo Senki','Saga of Tanya the Evil',replace('The novel series centers on a young girl who fights on the frontlines in war. She has blonde hair, blue eyes, and nearly transparent white skin, and she flies through the air and mercilessly strikes down her opponents. Her name is Tanya Degurechaff, and she speaks with a young girl''s lisp and commands the army. Tanya used to be one of Japan''s elite office workers, but because of a wrathful god, was reborn as a little girl. Tanya prioritizes optimization and career advancement above all, and she will become the most dangerous entity among the Imperial Army''s sorcerers.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.8,'TV',2,0,'24 min','NUT','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21613-qT3NiwYP5dYc.png','["Action","Fantasy"]',286465,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21647,32729,'orange','Orange',replace('Everyone has regrets in life. So who wouldn''t take the chance to change the past if given the opportunity? When sixteen-year-old Takamiya Naho receives a mysterious letter, claiming to be from her twenty-seven-year-old self, her life is suddenly thrown into flux. The letter tells her that a new transfer student by the name of Naruse Kakeru will be joining her class, and to keep her eye on him. But why? Naho must decide what to make of the letter and its cryptic warning, and what it means not only for her future, but for Kakeru''s as well.\n\n\n(Source: Anime News Network)\n\n\n\nNote: The last episode aired with a runtime of ~40 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),7.5,'TV',2,0,'24 min','Telecom Animation Film','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21647-zMUXNhcVyRyv.png','["Drama","Romance","Supernatural"]',239967,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21679,32867,'Bungou Stray Dogs 2nd Season','Bungo Stray Dogs 2',replace('Despite their differences in position, three men—the youngest senior executive of the Port Mafia, Osamu Dazai, the lowest ranking member, Sakunosuke Oda, and the intelligence agent, Angou Sakaguchi—gather at the Lupin Bar at the end of the day to relax and take delight in the company of friends.\n\n\n\nHowever, one night, Angou disappears. A photograph taken at the bar is all that is left of the three together.\n\n\n\nFast forward to the present, and Dazai is now a member of the Armed Detective Agency. The Guild, an American gifted organization, has entered the fray and is intent on taking the Agency''s work permit. They must now divide their attention between the two groups, the Guild and the Port Mafia, who oppose their very existence.','\n',char(10)),8.1,'TV',2,0,'24 min','bones','FALL 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21679-9MKdz1A7YLV7.jpg','["Action","Comedy","Mystery","Supernatural"]',242219,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21685,32901,'Eromanga Sensei','Eromanga Sensei',replace('The "new sibling romantic comedy" revolves around Masamune Izumi, a light novel author in high school. Masamune''s little sister is Sagiri, a shut-in girl who hasn''t left her room for an entire year. She even forces her brother to make and bring her meals when she stomps the floor. Masamune wants his sister to leave her room, because the two of them are each other''s only family.\n\n\n\nMasamune''s novel illustrator, penname “Ero Manga Sensei,” draws extremely perverted drawings, and is very reliable. Masamune had never met his illustrator, and figured he was just a disgusting, perverted otaku. However, the truth is revealed … that his “Ero Manga Sensei” is his own younger sister! To add to the chaos that erupts between the siblings, a beautiful, female, best-selling shoujo manga creator becomes their rival!\n\n\n\n(Source: Anime News Network)','\n',char(10)),5.9,'TV',2,0,'24 min','A-1 Pictures','SPRING 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21685-h1SrcpaNnrIq.jpg','["Comedy","Drama","Ecchi","Romance","Slice of Life"]',189137,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21698,32935,'Haikyuu!!: Karasuno Koukou VS Shiratorizawa Gakuen Koukou','HAIKYU!! 3rd Season',replace('After the victory against Aoba Jousai High, Karasuno High School, once called “a fallen powerhouse, a crow that can’t fly,” has finally reached the climax of the heated Spring tournament. Now, to advance to nationals, the Karasuno team has to defeat the powerhouse Shiratorizawa Academy. Karasuno’s greatest hurdle is their adversary’s ace, Wakatoshi Ushijima, the number one player in the Miyagi Prefecture, and one of the country’s top three aces.\n\n\n\nOnly the strongest team will make it to the national tournament. Since this match is the third-year players’ last chance to qualify for nationals, Karasuno has to use everything they learned during the training camp and prior matches to attain victory. Filled with restlessness and excitement, both teams are determined to come out on top in the third season of Haikyuu!!.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.7,'TV',2,0,'25 min','Production I.G','FALL 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21698-RL71mr1YU5Io.png','["Comedy","Drama","Sports"]',368171,1794735119,10,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21699,32937,'Kono Subarashii Sekai ni Shukufuku wo! 2','KONOSUBA -God''s blessing on this wonderful world! 2',replace('When Kazuma Satou died, he was given two choices: pass on to heaven or be revived in a fantasy world. After choosing the new world, the goddess Aqua tasked him with defeating the Demon King, and let him choose any weapon to aid him. Unfortunately, Kazuma chose to bring Aqua herself and has regretted the decision ever since then.\n\n\n\nNot only is he stuck with a useless deity turned party archpriest, the pair also has to make enough money for living expenses. To add to their problems, their group continued to grow as more problematic adventurers joined their ranks. Their token spellcaster, Megumin, is an explosion magic specialist who can only cast one spell once per day and refuses to learn anything else. There is also their stalwart crusader, Lalatina "Darkness" Dustiness Ford, a helpless masochist who makes Kazuma look pure in comparison.\n\n\n\nKono Subarashii Sekai ni Shukufuku wo! 2 continues to follow Kazuma and the rest of his party through countless more adventures as they struggle to earn money and have to deal with one another''s problematic personalities. However, things rarely go as planned, and they are often sidetracked by their own idiotic tendencies.','\n',char(10)),8,'TV',2,0,'23 min','Studio DEEN','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21699-Fkbnkl9ZC6fW.png','["Adventure","Comedy","Ecchi","Fantasy"]',383753,1794735119,10,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21700,32951,'Rokudenashi Majutsu Koushi to Akashic Records','Akashic Records of Bastard Magic Instructor',replace('In the "action fantasy" story, Glenn is a part-time teacher at a magic school who is inclined to write "self-study" on the blackboard and then take a nap. One of his students, Sistine, gets angry and challenges him to a duel and he is easily defeated. However, when a terrible incident threatens the school, Glenn shows intense dedication to protecting his students.\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.8,'TV',2,0,'25 min','LIDENFILMS','SPRING 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21700-HhTEXPZKxupP.jpg','["Action","Comedy","Fantasy"]',204721,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21701,32949,'Kuzu no Honkai','Scum''s Wish',replace('Hanabi has loved her older friend Narumi for years, but she’s still in high school and not only is Narumi now her new homeroom teacher, he’s also clearly in love with the music teacher, Akane. And as awkward as being the unwanted third in a romantic triangle can be, things become even more twisted for Hanabi when she learns that another student, Mugi, is in love with Akane. That leads to a strange idea: since the ones that Mugi and Hanabi are in love with aren’t available, the two unrequited thirds start to explore the idea of becoming each other’s substitute surrogate relationship. It’s not about romance, of course. Just sex and convenience.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),6.8,'TV',2,0,'23 min','Lerche','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21701-j81oh6WCNlsQ.jpg','["Drama","Ecchi","Psychological","Romance"]',184947,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21709,32995,'Yuuri!!! on ICE','Yuri!!! on ICE',replace('Yuri Katsuki makes his way to the Grand Prix ice skating competition as Japan’s top representative with his eyes on the prize. However, instead of celebrating, Yuri walks away defeated and ready to retire for good. But a run-in with champion Viktor Nikiforov and rising star Yuri Plisetsky ignites a new fire within him. With the two of them close by his side, Yuri will take to the ice once more.\n\n\n\n(Source: Funimation)','\n',char(10)),7.8,'TV',2,0,'24 min','MAPPA','FALL 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21709-aqPBDxJPruYR.png','["Comedy","Drama","Sports"]',234795,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21711,32998,'91Days','91 Days',replace('The "classic mafia drama" takes place during the prohibition era. In the Lawless district the law has no power, the mafia rule the streets, and the illegally made liquor flows freely. At one time Avilio lived in this district, but after a mafia dispute ended in the murder of his family, he went into hiding. Later, Avilio receives a letter from a mysterious person that ignites his passion for revenge and leads him to return to Lawless. There, he infiltrates the Vanetti family and gets close to Nero.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.6,'TV',2,0,'24 min','Shuka','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21711-EQN4sCIXRhKf.png','["Action","Drama","Psychological"]',202051,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21776,33206,'Kobayashi-san Chi no Maidragon','Miss Kobayashi''s Dragon Maid',replace('What happens when a drunken promise leads to living with a dragon? That’s Miss Kobayashi’s new reality when Tohru appears in her life. With a maid-slash-dragon in her home, she’s experiencing a whole new level of domestic bliss! But the dragons don’t stop there. On a mission to find Tohru appears Kanna, a little dragon with a big attitude. Before she knows it, Kobayashi’s got a house full of dragons—one serving tail and the other serving serious moe! Together, they live side by side with only the occasional disaster…well, maybe. But nothing beats coming home to the warm welcome of a dragon maid!\n\n\n\n(Source: Funimation)','\n',char(10)),7.7,'TV',2,0,'24 min','Kyoto Animation','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21776-bwPaYKhnKfUs.png','["Comedy","Fantasy","Slice of Life"]',334772,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21804,33255,'Saiki Kusuo no Ψ-nan','The Disastrous Life of Saiki K.',replace('To the average person, psychic abilities might seem a blessing; for Kusuo Saiki, however, this couldn''t be further from the truth. Gifted with a wide assortment of supernatural abilities ranging from telepathy to x-ray vision, he finds this so-called blessing to be nothing but a curse. As all the inconveniences his powers cause constantly pile up, all Kusuo aims for is an ordinary, hassle-free life—a life where ignorance is bliss.\n\n\n\n\nUnfortunately, the life of a psychic is far from quiet. Though Kusuo tries to stay out of the spotlight by keeping his powers a secret from his classmates, he ends up inadvertently attracting the attention of many odd characters, such as the empty-headed Riki Nendou and the delusional Shun Kaidou. Forced to deal with the craziness of the people around him, Kusuo comes to learn that the ordinary life he has been striving for is a lot more difficult to achieve than expected.\n\n\nNote: Aired in 2 versions, a 120-episode 5-minute short series, and a combined 24-episode 24-minute TV series with the same content.','\n',char(10)),8.3,'TV_SHORT',2,0,'5 min','J.C.STAFF','SUMMER 2016','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21804-As6tDLAvEvNY.jpg','["Comedy","Slice of Life","Supernatural"]',367148,1794735119,120,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21827,33352,'Violet Evergarden','Violet Evergarden',replace('A certain point in time, in the continent of Telesis. The great war which divided the continent into North and South has ended after four years, and the people are welcoming a new generation. Violet Evergarden, a young girl formerly known as “the weapon”, has left the battlefield to start a new life at CH Postal Service. There, she is deeply moved by the work of “Auto Memories Dolls”, who carry people''s thoughts and convert them into words. Violet begins her journey as an Auto Memories Doll, and comes face to face with various people''s emotions and differing shapes of love. There are words Violet heard on the battlefield, which she cannot forget. These words were given to her by someone she holds dear, more than anyone else. She does not yet know their meaning but she searches to find it.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.5,'TV',2,0,'24 min','Kyoto Animation','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21827-ubzq619ZA2E9.png','["Drama","Fantasy","Slice of Life"]',558039,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21856,33486,'Boku no Hero Academia 2','My Hero Academia Season 2',replace('Taking off right after the last episode of the first season. The school is temporarily closed due to security. When U.A. restarts, it is announced that the highly anticipated School Sports Festival will soon be taking place. All classes: Hero, Support, General and Business will be participating. Tournaments all round will decide who is the top Hero in training.\n\n(Source: Anime News Network)','\n',char(10)),7.9,'TV',2,0,'24 min','bones','SPRING 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21856-gutauxhWAwn6.png','["Action","Adventure","Comedy"]',666219,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21857,33487,'Masamune-kun no Revenge','Masamune-kun''s Revenge',replace('As an overweight child, Makabe Masamune was mercilessly teased and bullied by one particular girl, Adagaki Aki. Determined to one day exact his revenge upon her, Makabe begins a rigorous regimen of self-improvement and personal transformation.\n\nYears later, Masamune re-emerges as a new man. Handsome, popular, with perfect grades and good at sports, Masamune-kun transfers to Aki''s school, and is unrecognizable to her. Now, Masamune-kun is ready to confront the girl who bullied him so many years ago and humiliate her at last. But will revenge be as sweet as he thought?\n\n\n\n(Source: Seven Seas Entertainment)','\n',char(10)),6.6,'TV',2,0,'24 min','SILVER LINK.','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx21857-haPDVD7DKDpg.jpg','["Comedy","Romance","Slice of Life"]',248952,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21858,33489,'Little Witch Academia (TV)','Little Witch Academia (TV)',replace('In a time when magic is on the decline amid society, Atsuko Kagari is a cheerful girl who enters Luna Nova Academy in order to accomplish her dream of becoming a witch like her idol, Shiny Chariot. Shiny is a famous witch who disappeared from public view many years ago. On her way to school, Kagari meets the kind Lotte Yanson and the mischevious Sucy Manbavaran and the three become friends as they share a bedroom in campus. At the academy, Atsuko soon discovers she is in serious disadvantage compared to the other girls since she doesn`t come from a magical family and is required to learn the magical curriculum from scratch. Having found an item that once belonged to Chariot, Atsuko must discover how to activate and properly use the mysterious Shiny Rod as she hopes it might lead to finding out what has truly happened to her vanished idol.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.7,'TV',2,0,'24 min','TRIGGER','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21858-huBrbIOGMYXv.jpg','["Comedy","Fantasy"]',169499,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21861,33506,'Ao no Exorcist: Kyoto Fujouou-hen','Blue Exorcist: Kyoto Saga',replace('In the late Edo Period, a demon known as the Impure King killed thousands of people. After defeating the demon, the Knights of the True Cross kept its left eye safely sealed away on Academy grounds - but now someone has stolen it! Hearing the thief has taken a child hostage, Yukio and Rin go to help. The investigation and pursuit will lead Rin and his friends to Kyoto and involve them even deeper in a sinister plot! But will his friends'' knowledge that Rin is the son of Satan drive a wedge between them?\n\n\n\n(Source: VIZ Media)','\n',char(10)),7.2,'TV',2,0,'24 min','A-1 Pictures','WINTER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21861-KDvJJQenJJlT.jpg','["Action","Fantasy","Supernatural"]',181179,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(21875,33674,'No Game No Life Zero','No Game, No Life Zero',replace('Six thousand years before Sora and Shiro were even a blink in the history of Disboard, war consumed the land, tearing apart the heavens, destroying stars, and even threatening to wipe out the human race. Amid the chaos and destruction, a young man named Riku leads humanity toward the tomorrow his heart believes in. One day, in the ruins of an Elf city, he meets Schwi, a female exiled "Ex Machina" android who asks him to teach her what it means to have a human heart.\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.9,'MOVIE',2,0,'110 min','MADHOUSE','SUMMER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx21875-ybSgx75MgRMM.png','["Action","Adventure","Drama","Fantasy","Romance"]',233725,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(97668,34134,'One Punch Man 2','One-Punch Man Season 2','Saitama is a hero who only became a hero for fun. After three years of “special training,” he’s become so strong that he’s practically invincible. In fact, he’s too strong—even his mightiest opponents are taken out with a single punch. Now, the great seer Madame Shibabawa’s prediction about the Earth being doomed seems to be coming true as the frequency of monster incidents escalates. Alongside Genos, his faithful disciple, Saitama begins his official hero duties as a member of the Hero Association, while Garou, a man utterly fascinated by monsters, makes his appearance.',7.4,'TV',2,0,'24 min','J.C.STAFF','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97668-nC8gQrXVxt7k.png','["Action","Comedy","Sci-Fi","Supernatural"]',475756,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(97766,34280,'Gamers!','GAMERS!',replace('Keita Amano is a fan of one thing: gaming! Whether he’s on his phone or console, he just loves playing video games. And when the beautiful president of the game club, Karen Tendou, invites him to join, it seems like an EZ choice. Except, he declines! KO’d by the shock, Karen suddenly makes getting close to Amano her main quest. But she’s not the only one interested in him!\n\n\n\n(Source: Funimation)','\n',char(10)),6.5,'TV',2,0,'24 min','PINE JAM','SUMMER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97766-AKr0m3uHkKyW.jpg','["Comedy","Drama","Romance","Slice of Life"]',177783,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(97922,34542,'Inuyashiki','INUYASHIKI LAST HERO',replace('Ichiro Inuyashiki is down on his luck. While only 58 years old, his geriatric looks often have him written off as a pathetic old man by the world around him and he''s constantly ignored and disrespected by his family despite all that he''s done to support them. On top of everything else, his doctor has revealed that he has cancer and it appears that he has little time left in this world. But just when it seems things couldn''t get any worse, a blinding light in the night sky strikes the earth where Ichiro stands. He later wakes up to find himself unscathed, but he soon starts to notice that there''s something…different about himself.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.4,'TV',2,0,'23 min','MAPPA','FALL 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97922-qrGn5fkQinDs.jpg','["Action","Drama","Psychological","Sci-Fi"]',177106,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(97938,34566,'BORUTO: NARUTO NEXT GENERATIONS','Boruto: Naruto Next Generations',replace('Naruto was a young shinobi with an incorrigible knack for mischief. He achieved his dream to become the greatest ninja in the village and his face sits atop the Hokage monument. But this is not his story... A new generation of ninja are ready to take the stage, led by Naruto''s own son, Boruto!\n\n\n\n(Source: VIZ Media)','\n',char(10)),5.6,'TV',2,0,'24 min','Studio Pierrot','SPRING 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97938-BnF6M5yTaNB1.jpg','["Action","Adventure","Fantasy"]',228716,1794735120,293,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(97940,34572,'Black Clover','Black Clover',replace('In a world where magic is everything, Asta and Yuno are both found abandoned at a church on the same day. While Yuno is gifted with exceptional magical powers, Asta is the only one in this world without any. At the age of fifteen, both receive grimoires, magic books that amplify their holder’s magic. Asta’s is a rare Grimoire of Anti-Magic that negates and repels his opponent’s spells. Being opposite but good rivals, Yuno and Asta are ready for the hardest of challenges to achieve their common dream: to be the Wizard King. Giving up is never an option!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.9,'TV',2,0,'24 min','Studio Pierrot','FALL 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97940-fyh8o7gNbha0.png','["Action","Adventure","Comedy","Fantasy"]',605106,1794735119,170,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(97986,34599,'Made in Abyss','Made in Abyss',replace('The "Abyss" is the last unexplored place in the world. Strange and wonderful creatures roam within, and it is full of precious relics that present humans can''t recreate. Those that dare to explore the depths are known as "Cave Raiders." An orphan girl named Riko lives on the rim. Her dream is to become a Cave Raider like her mother and solve the mysteries of the cave system. One day, Riko starts exploring the caves and discovers a robot who resembles a human boy.\n\n\n\n(Source: Anime News Network, edited)\n\n\n\nNote: The last episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),8.4,'TV',2,0,'25 min','Kinema Citrus','SUMMER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97986-TQ7dCgbS3y5s.jpg','["Adventure","Drama","Fantasy","Horror","Mystery","Sci-Fi"]',413593,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(97994,34618,'Blend S','BLEND-S',replace('The story centers on a girl named Maika who gets a job at a cafe where all the waitresses are given certain attributes — such as "tsundere" or "little sister" — to embody while serving customers. The manager asks Maika to be the "Do S" (extreme sadist) waitress, so she will have to adopt a dominant and aggressive persona.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7,'TV',2,0,'24 min','A-1 Pictures','FALL 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97994-JZ1rLkJBcO8V.png','["Comedy","Slice of Life"]',183257,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(98034,34612,'Saiki Kusuo no Ψ-nan 2','The Disastrous Life of Saiki K. Season 2','The disastrous life of the gifted psychic Kusuo Saiki continues, despite his utmost effort to live an ordinary life. Although he has certainly grown accustomed to dealing with his troublesome friends—who are his biggest hurdle to achieving a peaceful life—he still has a long way to go. Also joining the usual oddballs are a few new faces whose shenanigans add to Saiki''s misery, making his dreams of a hassle-free life a distant fantasy.',8.3,'TV',2,0,'24 min','J.C.STAFF','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx98034-1eQ4F7SKxVas.jpg','["Comedy","Slice of Life","Supernatural"]',193454,1794735120,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(98291,34902,'Tsurezure Children','Tsuredure Children',replace('To those of you out there who never could say "I love you"— This story is about ordinary highschoolers and how love makes them fired up, shaken, laugh, cry, and hurt. Whether things go well or not, this story of adolescence and romance will show you how they spend their precious youth. Every character is the main character here, and you''re sure to find one you can sympathize with.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.4,'TV_SHORT',2,0,'13 min','Studio Gokumi','SUMMER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98291-LY6txxZTX8We.jpg','["Comedy","Drama","Romance","Slice of Life"]',199826,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(98314,34933,'Kakegurui','Kakegurui',replace('During daylight hours, an exclusive, elite private school prepares its illustrious students for careers in business, politics, and high society. But when darkness falls, the halls of this esteemed establishment transform into an underground gambling den where bright-eyed youngsters learn the timeless art of bluffing, backdoor dealings and social manipulation. In this school for the rich and elite, money is power, and the tyrant of the betting books rules with an iron fist. So when the beautiful Yumeko Jabami upsets the academy hierarchy with her voracious appetite for the thrill of the gamble, the entire student body mobilizes to send her house of cards tumbling down.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7,'TV',2,0,'25 min','MAPPA','SUMMER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b98314-TSJykxVwCCQN.jpg','["Drama","Mystery","Psychological"]',463116,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(98436,35062,'Mahoutsukai no Yome','The Ancient Magus'' Bride',replace('Chise Hatori has lived a life full of neglect and abuse, devoid of anything resembling love. Far from the warmth of family, she has had her share of troubles and pitfalls. Just when all hope seems lost, a fateful encounter awaits her. When a man with the head of a beast, wielding strange powers, obtains her through a slave auction, Chise''s life will never be the same again.\n\n\n\n(Source: Seven Seas Entertainment)','\n',char(10)),7.8,'TV',2,0,'25 min','WIT STUDIO','FALL 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98436-n7sK6POCd0XV.png','["Drama","Fantasy","Romance","Slice of Life","Supernatural"]',250060,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(98437,35073,'Overlord II','Overlord II',replace('Continuing his quest to rule this new world, Ains begins to put the pieces in place for his conquest. But between a Lizard Man tribe uprising, and performing missions as adamantite adventurer Lord Momon, Ains has his work cut out for him! Thankfully he has his most loyal and willing subordinates to do his bidding. Nothing and no one can stop the supreme and mighty Overlord in his quest to rule all!\n\n\n\n(Source: Manga Entertainment)','\n',char(10)),7.6,'TV',2,0,'24 min','MADHOUSE','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98437-5q0GWqHhNAgJ.jpg','["Action","Adventure","Fantasy"]',271939,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(98460,35120,'DEVILMAN crybaby','Devilman Crybaby',replace('The protagonist Akira Fudou learns from his best friend, Ryou Asuka, that an ancient race of demons has returned to take back the world from humans. Ryou tells Akira that the only way to defeat the demons is to incorporate their supernatural powers, and suggests that he unite with a demon himself. Akira succeeds in transforming into Devilman, who possesses both the powers of a demon and the soul of a human. The battle of Devilman and Akira Fudou begins.\n\n\n\n(Source: Netflix)\n\n\n\nNote: New Devilman project marking Go Nagai''s 50th anniversary as a creator.','\n',char(10)),7.6,'ONA',2,0,'25 min','Science SARU','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98460-bLtH2c3jd6sV.png','["Action","Drama","Horror","Psychological","Supernatural"]',359185,1794735119,10,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(98659,35507,'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e','Classroom of the Elite',replace('Koudo Ikusei Senior High School is a leading school with state-of-the-art facilities. The students there have the freedom to wear any hairstyle and bring any personal effects they desire. Koudo Ikusei is like a utopia, but the truth is that only the most superior students receive favorable treatment.\n\n\n\nKiyotaka Ayanokouji is a student of D-class, which is where the school dumps its "inferior" students in order to ridicule them. For a certain reason, Kiyotaka was careless on his entrance examination, and was put in D-class. After meeting Suzune Horikita and Kikyou Kushida, two other students in his class, Kiyotaka''s situation begins to change. \n\n\n(Source: Anime News Network, edited)','\n',char(10)),7.6,'TV',2,0,'24 min','Lerche','SUMMER 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98659-WNyPLIZDpGGY.jpg','["Drama","Psychological"]',457919,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99147,35760,'Shingeki no Kyojin Season 3','Attack on Titan Season 3',replace('Eren and his companions in the 104th are assigned to the newly-formed Levi Squad, whose assignment is to keep Eren and Historia safe given Eren''s newly-discovered power and Historia''s knowledge and pedigree. Levi and Erwin have good reason to be concerned, because the priest of the Church that Hanji had hidden away was found tortured to death, making it clear that the Military Police are involved with the cover-up. Things get more harrowing when the MPs make a move on Erwin and the Levi Squad narrowly avoids capture. Eren is also having problems with his Titan transformation, and a deadly killer has been hired to secure Eren and Historia, one Levi knows all too well from his youth.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.6,'TV',2,0,'24 min','WIT STUDIO','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99147-AiPDD8cwlCfi.jpg','["Action","Drama","Fantasy","Mystery"]',700978,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99255,35788,'Shokugeki no Souma: San no Sara','Food Wars! The Third Plate',replace('At the Moon Festival, Totsuki Academy’s annual gourmet jubilee, students wage fierce culinary war as they try to out-earn their peers by selling the most of their chosen cuisine. Souma Yukihira, however, has his sights set on a grander prize: challenging the Elite Ten, who rule over the academy with iron fists. But Souma might have to put his grand ambitions on hold for the time being, because an insidious scheme to upset the balance of Totsuki Academy has begun to emerge from the shadows…\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.8,'TV',2,0,'24 min','J.C.STAFF','FALL 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx99255-heGTtj5b4owl.jpg','["Comedy","Ecchi"]',230842,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99263,35790,'Tate no Yuusha no Nariagari','The Rising of the Shield Hero',replace('Naofumi Iwatani, an uncharismatic Otaku who spends his days on games and manga, suddenly finds himself summoned to a parallel universe! He discovers he is one of four heroes equipped with legendary weapons and tasked with saving the world from its prophesied destruction. As the Shield Hero, the weakest of the heroes, all is not as it seems. Naofumi is soon alone, penniless, and betrayed. With no one to turn to, and nowhere to run, he is left with only his shield. Now, Naofumi must rise to become the legendary Shield Hero and save the world!\n\n\n\nNote:\n\n- The first episode was pre-aired on December 27th, 2018. Regular broadcast began on January 9th, 2019.\n\n- The first episode aired with a runtime of ~47 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),7.6,'TV',2,0,'24 min','Kinema Citrus','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99263-LcazQwdlWzMy.jpg','["Action","Adventure","Fantasy"]',470212,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99423,35849,'Darling in the Franxx','DARLING in the FRANXX',replace('The distant future: Humanity established the mobile fort city, Plantation, upon the ruined wasteland. Within the city were pilot quarters, Mistilteinn, otherwise known as the “Birdcage.” That is where the children live... Their only mission in life was the fight. Their enemies are the mysterious giant organisms known as Kyoryu. The children operate robots known as FRANXX in order to face these still unseen enemies. Among them was a boy who was once called a child prodigy: Code number 016, Hiro. One day, a mysterious girl called Zero Two appears in front of Hiro. “I’ve found you, my Darling.”\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.9,'TV',2,0,'24 min','TRIGGER','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx99423-8MBxtwCeHf8B.png','["Action","Drama","Mecha","Psychological","Romance","Sci-Fi"]',510358,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99426,35839,'Sora yori mo Tooi Basho','A Place Further Than the Universe',replace('Mari Tamaki is in her second year of high school and wants to start something. It''s then that she meets Shirase, a girl with few friends who''s considered weirdo by the rest of the class and nicknamed "Antarctic" since it''s all she ever talks about. Unlike her peers, Mari is moved by Shirase''s dedication and decides that even though it''s unlikely that high school girls will ever go to Antarctica, she''s going to try to go with Shirase.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.4,'TV',2,0,'24 min','MADHOUSE','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99426-ti5BL69Ip3kZ.png','["Adventure","Comedy","Drama"]',169871,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99468,35860,'Karakai Jouzu no Takagi-san','Teasing Master Takagi-san',replace('Having a friend that knows you inside out should be a good thing, but in Nishikata''s case, the opposite is true.\n\n\n\nHis classmate Takagi loves to tease him on a daily basis, and she uses her extensive knowledge of his behavior to predict exactly how he will react to her teasing, making it nearly impossible for Nishikata to ever make a successful comeback. Despite this, Nishikata vows to someday give Takagi a taste of her own medicine by making her blush out of embarrassment from his teasing.','\n',char(10)),7.4,'TV',2,0,'24 min','Shin-Ei Animation','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99468-XayCplkIL3Gf.png','["Comedy","Romance","Slice of Life"]',172901,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99539,34577,'Nanatsu no Taizai: Imashime no Fukkatsu','The Seven Deadly Sins: Revival of the Commandments',replace('Melodias, Hawk, and Elizabeth retook the Kingdom of Leones from the Holy Knights. The festival went off without a hitch and the crew enjoyed their well-earned peace. And yet, another threat looms on the horizon. The Ten Commandments, a group of elite demon clan warriors, have their sights set on the kingdom.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.3,'TV',2,0,'25 min','A-1 Pictures','WINTER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99539-caPX28RSsgRP.jpg','["Action","Adventure","Comedy","Ecchi","Fantasy","Supernatural"]',291090,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99578,35968,'Wotaku ni Koi wa Muzukashii','Wotakoi: Love is Hard for Otaku',replace('Having slept through all four of her alarms, the energetic Narumi Momose finds herself running late for her first day of work at a new office. As she races to catch her train, she makes a promise to herself that none of her coworkers will find out about her dark secret: that she is an otaku and a fujoshi. Her plan goes instantly awry, though, when she runs into Hirotaka Nifuji, an old friend from middle school. Although she tries to keep her secret by inviting him out for drinks after work, her cover is blown when he casually asks her whether or not she will be attending the upcoming Summer Comiket. Luckily for her, the only witnesses—Hanako Koyanagi and Tarou Kabakura—are otaku as well.\n\n\n\nLater that night, the pair go out for drinks so that they can catch up after all the years apart. After Narumi complains about her previous boyfriend breaking up with her because he refused to date a fujoshi, Hirotaka suggests that she try dating a fellow otaku, specifically himself. He makes a solemn promise to always be there for her, to support her, and to help her farm for rare drops in Monster Hunter. Blown away by the proposal, Narumi agrees immediately. Thus the two otaku start dating, and their adorably awkward romance begins.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'23 min','A-1 Pictures','SPRING 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx99578-oO5KChtfhzln.png','["Comedy","Romance","Slice of Life"]',334309,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99629,35994,'Satsuriku no Tenshi','Angels of Death',replace('13-year old Rachel awakens to find herself trapped in the basement of an abandoned building. Without any memories, or even a clue as to where she could be, she wanders the building, lost and dizzy. In her search, she comes across a man covered in bandages. He introduces himself as Zack and he wields a grim-reaper like sickle.\n\n\n\nA strange bond is struck between them, strengthened by strange, crazy promises…\n\n\n\nThese two, trapped in this strange building, don''t know why fate has placed them there. But they will work together desperately to find a way out…','\n',char(10)),6.7,'TV',2,0,'24 min','J.C.STAFF','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99629-BXyAJ6PDq4sr.jpg','["Action","Adventure","Horror","Psychological","Thriller"]',221803,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(99750,36098,'Kimi no Suizou wo Tabetai','I Want to Eat Your Pancreas',replace('Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: "Living with Dying." He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret.\n\n\n\nTrying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change.\n\n\n\n(Source: Aniplex USA)','\n',char(10)),8.4,'MOVIE',2,0,'108 min','Studio VOLN','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99750-pNyly9d3MEgV.jpg','["Drama","Romance","Slice of Life"]',384167,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100112,36407,'Kenja no Mago','Wise Man’s Grandchild',replace('A young man is reborn in another world where he is adopted as a baby by the hero Merlin Wolford and named Shin. By his 15th birthday, Shin has accumulated all kinds of power by studying under Merlin, but one thing his adoptive grandfather didn''t give him was a lick of common sense. \n\n\n(Source: Anime News Network)','\n',char(10)),6.4,'TV',2,0,'24 min','SILVER LINK.','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100112-eExFpnYG2QAK.jpg','["Action","Comedy","Fantasy","Romance"]',189011,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100166,36456,'Boku no Hero Academia 3','My Hero Academia Season 3',replace('Summer is here, and the heroes of Class 1-A and 1-B are in for the toughest training camp of their lives! A group of seasoned pros pushes everyone''s Quirks to new heights as the students face one overwhelming challenge after another. Braving the elements in this secret location becomes the least of their worries when routine training turns into a critical struggle for survival.\n\n(Source: Crunchyroll)','\n',char(10)),7.9,'TV',2,0,'24 min','bones','SPRING 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100166-jUCZYbzn2XLw.jpg','["Action","Adventure","Comedy","Drama"]',610687,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100182,36474,'Sword Art Online: Alicization','Sword Art Online: Alicization',replace('Kirito awakens in a vast, fantastical forest filled with towering trees. In his search for clues to the truth of his surroundings, he encounters a young boy who seems to know him. He ought to be a simple NPC, but the depth of his emotions seem no different than a human. As they search for the boy''s parents, Kirito finds a peculiar memory returning to him. A memory from his own childhood, of this boy and a girl, too, with golden hair, and a name he should have never forgotten - Alice.\n\n\n\n(Source: Yen Press)\n\n\n\nNote: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),7.5,'TV',2,0,'24 min','A-1 Pictures','FALL 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx100182-KctPmCJ2smHQ.jpg','["Action","Adventure","Fantasy","Sci-Fi"]',294217,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100183,36475,'Sword Art Online Alternative: Gun Gale Online','Sword Art Online Alternative: Gun Gale Online',replace('The story follows Karen Kohiruimaki, a 183-centimeter-tall (6-foot-tall) college student who''s insecure about her height, and is bad at dealing with people in the real world. She enters the world of Gun Gale Online with her avatar, Ren, who is less than 150 centimeters (5 feet) tall and wears all pink. She meets a beautiful, brown-skinned female player who goes by Pitohui. They hit it off, but one day Pitohui pressures her to participate in "Squad Jam," a team battle royale variation of the Bullet of Bullets tournament.\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.9,'TV',2,0,'24 min','Studio 3Hz','SPRING 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx100183-v4S2sGAG3A24.jpg','["Action","Sci-Fi"]',169830,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100240,36511,'Tokyo Ghoul:re','Tokyo Ghoul:re',replace('Two years have passed since the CCG''s raid on Anteiku. Although the atmosphere in Tokyo has changed drastically due to the increased influence of the CCG, ghouls continue to pose a problem as they have begun taking caution, especially the terrorist organization Aogiri Tree, who acknowledge the CCG''s growing threat to their existence.\n\n\n\nThe creation of a special team, known as the Quinx Squad, may provide the CCG with the push they need to exterminate Tokyo''s unwanted residents. As humans who have undergone surgery in order to make use of the special abilities of ghouls, they participate in operations to eradicate the dangerous creatures. The leader of this group, Haise Sasaki, is a half-ghoul, half-human who has been trained by famed special class investigator, Kishou Arima. However, there''s more to this young man than meets the eye, as unknown memories claw at his mind, slowly reminding him of the person he used to be.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),6.1,'TV',2,0,'24 min','Studio Pierrot','SPRING 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx100240-vJNaKd5HwPJ2.jpg','["Action","Horror","Mystery","Psychological","Supernatural"]',313559,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100388,36649,'BANANA FISH','BANANA FISH',replace('Nature made Ash Lynx beautiful; nurture made him a cold ruthless killer. A runaway brought up as the adopted heir and sex toy of "Papa" Dino Golzine, Ash, now at the rebellious age of seventeen, forsakes the kingdom held out by the devil who raised him. But the hideous secret that drove Ash''s older brother mad in Vietnam has suddenly fallen into Papa''s insatiably ambitious hands—and it''s exactly the wrong time for Eiji Okamura, a pure-hearted young photographer from Japan, to make Ash Lynx''s acquaintance...\n\n\n\n(Source: VIZ Media)','\n',char(10)),8.4,'TV',2,0,'23 min','MAPPA','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100388-hjkg1AnlJR5z.jpg','["Action","Drama","Psychological","Thriller"]',314173,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100668,36882,'Arifureta Shokugyou de Sekai Saikyou','Arifureta: From Commonplace to World''s Strongest',replace('When a classroom of students is transported to another world to act as its saviors, Hajime Nagumo finds himself the weakest link. As his friends and classmates are granted strong classes and impressive abilities due to their existing skills, he is given the weak title of Synergist. When a dungeon quest leaves him separated from his group, Hajime must discover his own talents or be left to rot in this world forever.\n\n\n\n(Source: Seven Seas Entertainment)','\n',char(10)),6.5,'TV',2,0,'24 min','WHITE FOX','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100668-DvOn5bMOt4cy.jpg','["Action","Adventure","Fantasy","Psychological"]',235831,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100723,36896,'Boku no Hero Academia THE MOVIE: Futari no Hero','My Hero Academia: Two Heroes',replace('The climactic finals are over, and U.A. is getting ready for the summer training camp. Deku and All Might receive an invitation from a certain person to go overseas to a giant artificial moving city called I-Island. This island, a kind of “science Hollywood” that gathers the knowledge of scientists from around the world, is holding an exhibition called I-Expo showcasing the results of Quirk and hero item research. In the midst of all this, Deku meets a Quirkless girl named Melissa and remembers his own Quirkless past. Out of the blue, the impregnable security system the island boasts is hacked by villains, and all the people on the island are taken as hostages! Now, a plan that could shake hero society has been put into motion! The man who holds the key to it all is the number one hero and Symbol of Peace, All Might.\n\n\n\n(Source: Funimation)','\n',char(10)),7.4,'MOVIE',2,0,'96 min','bones','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100723-7f5e1BCTCDoB.jpg','["Action","Comedy","Drama","Sci-Fi"]',225719,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100773,36949,'Shokugeki no Souma: San no Sara - Tootsuki Ressha-hen','Food Wars! The Third Plate: Totsuki Train Arc',replace('A dark age of cooking befalls Tootsuki Culinary Academy. With the Elite Ten''s devastating coup d''état, Azami Nakiri is now the director of the prestigious school. Students must now conform to Azami''s ideology of "true gourmet food" and are forbidden to express creativity, or else face expulsion.\n\n\n\nHowever, Souma Yukihira and the members of the Polar Star Dormitory refuse to accept these changes. Aided by other rebellious first-years, including the tenth seat, Erina Nakiri, Souma and his allies band together to fight off supporters of Azami''s regime. But corrupt instructors and the menacing Central organization stand in their way, and so they must work together, harder than ever before, to survive every underhanded plot designed to banish them from the school.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.7,'TV',2,0,'24 min','J.C.STAFF','SPRING 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx100773-KLx4vR0TiC5o.jpg','["Comedy","Ecchi"]',174712,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100876,37086,'Kakegurui ××','Kakegurui xx',replace('At Hyakkao Private Academy, Yumeko Jabami’s star rises just as the student council’s reputation starts to dim. In the shadows of the council’s dwindling power, discord reigns supreme. In a bold effort to rebalance the social scales, student council president Kirari Momobami intends to place her bet on the election for the council’s next president. Everyone starts with a single chip, and at the end of 30 days, the whoever holds the most becomes the president of the Momobami Clan. But chips aren’t the only things students can wager as they fight tooth and nail to ascend to the council presidency, and Yumeko Jabami intends to clean house no matter the prizes she must risk in the betting pool.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7,'TV',2,0,'24 min','MAPPA','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100876-RfvmpW1B8bDQ.png','["Drama","Mystery","Psychological"]',240409,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100922,37105,'Grand Blue','Grand Blue Dreaming','A new life begins for Kitahara Iori as he begins his college career near the ocean in Izu city, full of excitement for his new life. He will be moving into his Uncle''s diving store "Grand Blue." There he finds the beautiful ocean, beautiful women, and men that love diving and alcohol. Will Iori be able to live his dream college life?',8.2,'TV',2,0,'24 min','Zero-G','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100922-uxEhaCsqMMp3.png','["Comedy","Slice of Life","Sports"]',240965,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(100977,37141,'Hataraku Saibou','Cells at Work!',replace('The average human body contains about 60 trillion cells, and each of them has work to do! But when you get injured, viruses or bacteria invade, or when an allergic reaction flares up, everyone from the silent but deadly white blood cells to the brainy neurons has to work together to get through the crisis!\n\n\n\n(Source: Kodansha US)','\n',char(10)),7.3,'TV',2,0,'24 min','david production','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100977-nH1J2dR7GGAk.jpg','["Action","Comedy","Sci-Fi"]',204500,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101004,37210,'Isekai Maou to Shoukan Shoujo no Dorei Majutsu','How NOT to Summon a Demon Lord',replace('In the MMORPG Cross Reverie, Takuma Sakamoto is so powerful that he is lauded as the “Demon Lord” by other players. One day, he is summoned to another world – but with the same appearance he had in the game! There, he meets two girls who both proclaim themselves to be his Summoner. They had performed an Enslavement Ritual to turn him into their Summon... but that''s when Takuma''s passive ability <> activated! Instead, it was the girls who had become enslaved! Though Takuma may have been the strongest Sorcerer there was, he had no idea how to talk with other people. That''s when he makes his choice: to act based on his persona from the game!\n\n\n\n“Amazing? But of course... I am Diablo, the being known and feared as the Demon Lord!”\n\n\n\nSo begins a tale of adventure with an earth-shakingly powerful Demon Lord (or at least someone who acts like one) taking on another world!\n\n\n\n(Source: J-Novel Club)','\n',char(10)),6.6,'TV',2,0,'24 min','Ajiado','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101004-rJLBIWGypbYK.png','["Comedy","Ecchi","Fantasy"]',210436,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101165,37349,'Goblin Slayer','GOBLIN SLAYER',replace('A young priestess has formed her first adventuring party, but almost immediately they find themselves in distress. It''s the Goblin Slayer who comes to their rescue--a man who''s dedicated his life to the extermination of all goblins, by any means necessary. And when rumors of his feats begin to circulate, there''s no telling who might come calling next...\n\n\n\n(Source: Yen Press)','\n',char(10)),7.1,'TV',2,0,'24 min','WHITE FOX','FALL 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101165-v5NwPXWPFDuD.jpg','["Action","Adventure","Fantasy"]',309020,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101167,37347,'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka II','Is It Wrong to Try to Pick Up Girls in a Dungeon? II',replace('There''s rarely a dull moment when you''re the champion of a tiny Familia, and things only get rougher for Bell when the God Apollo declares war on Hestia and her followers. With Apollo''s Familia able to field a hundred times as many men, Hestia will have to work a lot of favors to keep her Familia from being completely destroyed.\n\n\n\nEven if Bell and Hestia manage to pull off the impossible, a major debt that Hestia owes is about to come due and Lili''s sordid past comes back to haunt her! Which means that when Bell and his friends come to Lili''s aid, it sets into motion yet another impending clash of the titans that may destroy everything!\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.1,'TV',2,0,'24 min','J.C.STAFF','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101167-Yasvj97UR9ue.png','["Action","Adventure","Comedy","Fantasy","Romance"]',248633,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101184,36064,'Fate/Grand Order CMs','Fate/Grand Order CMs',replace('Assorted commercials for the Fate/Grand Order mobile RPG. These short animations are aired on TV and posted to Type-Moon''s official YouTube channel, and advertise the game itself or promote a new in-game event. The animation is unique to these commercials and is not present in the game nor in the Fate/Grand Order series.\n\n\n\nThe list of the commercials is as follows (note that CMs without animation are not present and, for the ones with long and short versions, the longer version is taken into consideration)\n\n\n\n1) Fate/Grand Order TV-CM 第1弾 (27 Dec 2014)\n\n\n2) Fate/Grand Order TV-CM 第2弾 (27 June 2015)\n\n\n3) Fate/Grand Order TV-CM 第3弾 (6 Nov 2015)\n\n\n4) Fate/Grand Order TV-CM 第4弾 (30 Dec 2015)\n\n\n5)『Fate/Grand Order』×『空の境界』コラボCM (19 Feb 2016)\n\n\n6) Fate/Grand Order TV-CM 第5弾 (25 Mar 2016)\n\n\n7) 「Fate/Accel Zero Order」告知CM (20 Apr 2016)\n\n\n8) Fate/Grand Order TV-CM 第6弾 (6 July 2016)\n\n\n9) 夏だ！ 海だ！ FGO 2016 Summer TVCM (8 Aug 2016)\n\n\n10) 『魔法少女紀行 ～プリズマ・コーズ～』告知CM\n\n\n11) TVCM 第7弾 (6 Dec 2016)\n\n\n12) TVCM 第8弾 (22 Feb 2017)\n\n\n13) Fate/EXTRA CCC×Fate/Grand Order GW･EXスペシャルイベント「BBちゃんの逆襲/電子の海で会いましょう！」告知CM (26 Apr 2017)\n\n\n14) TVCM 第9弾 (28 June 2017)\n\n\n15) デッドヒート･サマーレース！TVCM (5 Aug 2017)\n\n\n16) 「Fate Grand Order」TVCM 第10弾 (16 Oct 2017)\n\n\n17) 亜種特異点Ⅳ 禁忌降臨庭園 セイレム TVCM (28 Nov 2017)\n\n\n18) Fate/Grand Order -Cosmos in the Lostbelt-」永久凍土帝国 アナスタシア 30秒CM (3 Apr 2018)\n\n\n19) Fate/Apocrypha × Fate/Grand Order スペシャルイベント「Apocrypha/Inheritance of Glory」告知CM (18 May 2018)\n\n\n20) ぐだぐだ帝都聖杯奇譚 告知CM (6 June 2018)\n\n\n21) Lostbelt No.2 無間氷焔世紀 ゲッテルデメルング 消えぬ炎の快男児 30秒TVCM (18 July 2018)\n\n\n22) サーヴァント･サマー･フェスティバル！ 告知CM (7 Aug 2018)\n