INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101280,37430,'Tensei Shitara Slime Datta Ken','That Time I Got Reincarnated as a Slime',replace('Lonely thirty-seven-year-old Satoru Mikami is stuck in a dead-end job, unhappy with his mundane life, but after dying at the hands of a robber, he awakens to a fresh start in a fantasy realm...as a slime monster! As he acclimates to his goopy new existence, his exploits with the other monsters set off a chain of events that will change his new world forever!\n\n\n\n(Source: Yen Press)','\n',char(10)),8,'TV',2,0,'24 min','8-bit','FALL 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101280-tDxCVJm714nt.jpg','["Action","Adventure","Comedy","Fantasy"]',475591,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101291,37450,'Seishun Buta Yarou wa Bunny Girl Senpai no Yume wo Minai','Rascal Does Not Dream of Bunny Girl Senpai',replace('There''s a rumor about a mysterious phenomenon called "puberty syndrome." For example, Sakuta Azusagawa is a high school student who suddenly sees a bunny girl appear in front of him. The girl is actually a girl named Mai Sakurajima, who is Sakuta''s upperclassman who is also a famous actress who has gone on hiatus from the entertainment industry. For some reason, the people around Mai cannot see her bunny-girl figure. Sakuta sets out to solve this mystery, and as he spends time with Mai, he learns her secret feelings. Other heroines who have "puberty syndrome" start to appear in front of Sakuta.\n\n\n(Source: Anime News Network)','\n',char(10)),8.1,'TV',2,0,'25 min','CloverWorks','FALL 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101291-wfEdgPqtfU0l.jpg','["Comedy","Drama","Mystery","Psychological","Romance","Supernatural"]',592436,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101338,37510,'Mob Psycho 100 II','Mob Psycho 100 II',replace('Kageyama is an ordinary 8th grader who just wants to live a normal life. Although he can disappear in the crowd in a flash, he was actually the most powerful psychic. The lives of those around Mob and his numerous feelings that softly piles up for the eventual explosion. The mysterious group "Claw" stands before him once again. In the midst of his youthful days, where will his roaring heart take him!?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.7,'TV',2,0,'24 min','bones','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101338-rokVscjRYzdP.jpg','["Action","Comedy","Drama","Psychological","Slice of Life","Supernatural"]',457390,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101347,37520,'Dororo','Dororo','Dororo, a young orphan thief, meets Hyakkimaru, a powerful ronin. Hyakkimaru''s father, a greedy feudal lord, had made a pact with 12 demons, offering his yet-unborn son''s body parts in exchange for great power. Thus, Hyakkimaru - who was born without arms, legs, eyes, ears, a nose or a mouth - was abandoned in a river as a baby. Rescued and raised by Dr. Honma, who equips him with artificial limbs and teaches him sword-fighting techniques, Hyakkimaru discovers that each time he slays a demon, a piece of his body is restored. Now, he roams the war-torn countryside in search of demons.',8.1,'TV',2,0,'24 min','MAPPA','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101347-TGaDwEYqLfm1.jpg','["Action","Adventure","Drama","Supernatural"]',382014,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101348,37521,'VINLAND SAGA','Vinland Saga',replace('Thorfinn is son to one of the Vikings'' greatest warriors, but when his father is killed in battle by the mercenary leader Askeladd, he swears to have his revenge. Thorfinn joins Askeladd''s band in order to challenge him to a duel, and ends up caught in the middle of a war for the crown of England.\n\n\n\n(Source: Kodansha USA)','\n',char(10)),8.7,'TV',2,0,'24 min','WIT STUDIO','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101348-2fhDFPCuMNiz.jpg','["Action","Adventure","Drama"]',560514,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101474,37675,'Overlord III','Overlord III',replace('With his foundations now set in this new world, the first steps of Ains Ooal Gown''s master plan apparent begin to come to fruition. The value of Carne village and especially the political value of his alter ego Momon are reaffirmed; the “hidden” genius of his actions is continuously met with shock and awe by Demiurge, Albedo, the rest of his guardians, and even Ains himself at his “great wisdom.” His attempts to act in a way befitting the ruler of Nazarick, continuing to further cement his guardian’s loyalty, push him ever further down the path of not-so-intentional world domination. Without human conscience due to being undead, he is motivated only to continue searching for other players from Yggdrasil and to gain power to better protect the children and home of him and his forty former companions. Lord Ains Ooal Gown maintains his mantle of Overlord and leads the Great Tomb of Nazarick unto the world stage, directly into a vicious power struggle between two great empires.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.7,'TV',2,0,'24 min','MADHOUSE','SUMMER 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101474-tGRyvSAWMjU9.jpg','["Action","Adventure","Fantasy"]',251716,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101759,37779,'Yakusoku no Neverland','The Promised Neverland',replace('Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing.\n\n\n\n(Source: VIZ Media)','\n',char(10)),8.3,'TV',2,0,'23 min','CloverWorks','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101759-8UR7r9MNVpz2.jpg','["Drama","Fantasy","Horror","Mystery","Psychological","Thriller"]',643620,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101906,29427,'Mori no Ratio','Ratio of Forest','Ratio is a girl living in a ice world with his hairy friend Jammon, she will learn various things from the spirits and the people she encounters in every episode.',0,'TV_SHORT',1,0,'5 min','-','SPRING 2010','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101906-wNhuSdTewGUw.jpg','["Adventure","Fantasy","Slice of Life"]',352,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101921,37999,'Kaguya-sama wa Kokurasetai: Tensaitachi no Renai Zunousen','Kaguya-sama: Love is War',replace('Known for being both brilliant and powerful, Miyuki Shirogane and Kaguya Shinomiya lead the illustrious Shuchiin Academy as near equals. And everyone thinks they’d make a great couple. Pride and arrogance are in ample supply, so the only logical move is to trick the other into instigating a date! Who will come out on top in this psychological war where the first move is the only one that matters?\n\n\n\n(Source: Aniplex)','\n',char(10)),8.3,'TV',2,0,'24 min','A-1 Pictures','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101921-ufrjLzhSz7L1.jpg','["Comedy","Psychological","Romance","Slice of Life"]',570600,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(101922,38000,'Kimetsu no Yaiba','Demon Slayer: Kimetsu no Yaiba',replace('It is the Taisho Period in Japan. Tanjiro, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. To make matters worse, his younger sister Nezuko, the sole survivor, has been transformed into a demon herself. Though devastated by this grim reality, Tanjiro resolves to become a “demon slayer” so that he can turn his sister back into a human, and kill the demon that massacred his family.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.2,'TV',2,0,'24 min','ufotable','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101922-WBsBl0ClmgYL.jpg','["Action","Adventure","Drama","Fantasy","Supernatural"]',1014997,1794735119,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(102351,37799,'Tokyo Ghoul:re 2','Tokyo Ghoul:re 2',replace('Kaneki Ken has finally regained memories of his former self, but this once again leaves him at a crossroads in the war between human and ghoul. After donning a pair of glasses to mirror his mentor Arima, Kaneki''s new assignment is to manage the interrogation of Eto, the One-Eyed Owl, after she reveals her ghoul nature in a press conference about the publication of her newest book, which she claims will bridge the gap between the two warring sides. Now interred in Cochlea, Eto eagerly awaits the awakening of the "One-Eyed King", but only Kaneki seems to understand what she''s really planning. As Aogiri Tree descends on the facility to rescue their leader, Kaneki turns to one of his oldest friends for help in his new secret mission.\n\n\n\n(Source: Anime News Network)\n\n\nNote: The first episode was distributed online via GYAO! on September 29, 2018. TV broadcast began on October 9, 2018.','\n',char(10)),6.2,'TV',2,0,'24 min','Studio Pierrot','FALL 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx102351-yD3Ty9YZFMsf.jpg','["Action","Horror","Mystery","Psychological","Supernatural"]',242082,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(102763,30088,'Ryoutei no Aji','料亭の味',replace('Short stories capturing the bittersweet and tender moments of everyday family life, made for Marukome Co., Ltd. a miso soup paste manufacturer.\n\n\n\nList of commercials:\n\n• #1: Mother and Son (たっぷりお徳 母と息子篇)\n\n• #2: Working away from Home (即席生みそ汁 単身赴任篇)\n\n• #3: A Midnight Snack (カップみそ汁 夜食篇)\n\n• #4: Coming to Tokyo (液みそ 上京篇)\n\n• #5: Being a mother (無添加 母になれば篇)\n\n• #6: Miso Soup (お徳用あおさ ミソスープ篇)\n\n• #7: Home Sick Together (米麦合わせ ふたりでおやすみ篇)\n\n• #8: Together Forever (液みそ いつまでも一緒に篇)\n\n• #9: Look After Yourself (フリーズドライ 顆粒みそ 気をつけてね篇)\n\n• #10: Memories of Summer Vacation (夏休みの思い出篇)\n\n• #11: My Whimsical Little Boy (息⼦にはかなわない篇)\n\n• #12: Home for the Holidays (帰省篇)\n\n• #13: Cooking Is Super Cool (料理ってすごいね篇)\n\n• #14: My grandma (わたしのおばあちゃん篇)','\n',char(10)),6.2,'SPECIAL',1,0,'2 min','Robot','WINTER 2014','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx102763-HM9mNUiJrz44.jpg','["Slice of Life"]',794,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(102883,37991,'JoJo no Kimyou na Bouken: Ougon no Kaze','JoJo''s Bizarre Adventure: Golden Wind',replace('Giorno Giovanna, a young man living in Naples, has the blood of DIO -- the eternal enemy of the Joestar clan -- running in his veins. Giorno becomes a delinquent due to being persecuted since childhood. However, he''s led back onto the right path thanks to a gangster who saved him and taught him to believe in others. Bizarrely enough, this gang of people who didn''t forget honor, gratitude, and respect made him reform. This is how Giorno came to admire gangsters. In the backstreets of Italy, Giorno causes trouble alongside his gang "Passione," and ends up being targeted...\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.5,'TV',2,0,'24 min','david production','FALL 2018','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx102883-S9KzdMJhDswJ.png','["Action","Adventure","Drama","Mystery","Supernatural"]',306956,1794735119,39,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(102976,38040,'Kono Subarashii Sekai ni Shukufuku wo! Kurenai Densetsu','KONOSUBA -God''s blessing on this wonderful world!- Legend of Crimson',replace('A video game-loving shut-in, Satou Kazuma''s life should''ve ended when he was hit by a truck, but through a twist of fate, he ends up reincarnating in another world--and dragging the troublemaking goddess, Aqua, the wildly dorky mage, Megumin, and the unrelentingly delusional lady knight, Darkness, with him.\n\n\n\nNow, the Crimson Demon village that Megumin and Yunyun are from is facing a threat that could mean its ending. Kazuma and his gang follow Yunyun, who returns to the Crimson Demon village intent on saving it... when they are faced with their greatest threat yet! What will become of the unremarkable adventurer Kazuma''s life in another world?!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.2,'MOVIE',2,0,'90 min','J.C.STAFF','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx102976-2Yi5icRbjukO.png','["Action","Adventure","Comedy","Ecchi","Fantasy","Supernatural"]',247573,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(103047,37987,'Violet Evergarden Movie','Violet Evergarden: the Movie',replace('While writing other people’s emotions, she may have neglected her own. Violet Evergarden, the child soldier turned Auto Memory Doll, writes letters that evoke the words her clients can’t. But when a terminally ill boy requests her services for his family, her own feelings about love and loss resurface. Now she must confront her past and the death of the Major.\n\n\n\n(Source: Funimation)','\n',char(10)),8.7,'MOVIE',2,0,'140 min','Kyoto Animation','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103047-odblDHHEdehK.jpg','["Drama","Fantasy","Slice of Life"]',205216,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(103139,37982,'Domestic na Kanojo','Domestic Girlfriend',replace('Natsuo Fuji has a serious crush on one of his teachers, Hina Tachibana, but since he knows he has zero chance of ever being in a relationship with her, he lets his friends talk him into going to a party where he meets Rui. One thing leads to another and then, well, neither of them is a virgin anymore. Unfortunately, it wasn''t what they expected, but that''s fine. They''re just ships passing in the night and they''ll never have to see each other again, right? Except when Natsuo''s father announces that he''s getting married again, Natsuo discovers that he''s getting two new step-sisters as well. Now there''s a problem, because one is his teacher, Hina, and the other is Rui.\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),6.3,'TV',2,0,'25 min','diomedéa','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx103139-2TfvRyGTE1qp.jpg','["Drama","Ecchi","Romance"]',227112,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(103223,38003,'Bungou Stray Dogs 3rd Season','Bungo Stray Dogs 3',replace('The White Tiger and the Black Beast – Nakajima Atsushi and Akutagawa Ryunosuke’s fight against Francis F. brings an end to the great war against the Guild. Life goes on as normal in Yokohama, thanks to the continued truce between the Armed Detective Agency and the Port Mafia, who, together, saved the city from ruin. But there are still rumors of Guild stragglers and other crime organizations making their way in from abroad. Meanwhile, Dazai Osamu had premonitions of another impending disaster. Lurking in the darkness is the Fyodor D., leader of pirate organization Rats in the House of the Dead, his dreadful plans on the verge of execution.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.1,'TV',2,0,'24 min','bones','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103223-bfdnnKWxE4YE.jpg','["Action","Comedy","Mystery","Supernatural"]',200987,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(103572,38101,'Go-toubun no Hanayome','The Quintessential Quintuplets',replace('Uesugi Fuutarou, a high school second-year from a poor family, receives a highly appealing offer to work part-time as a tutor... but his students turn out to be girls from his own class! What''s more, they''re quintuplets... and all five are beautiful, but happen to be problem students who have borderline grades and hate studying! Looks like his first assignment will be to win all the sisters'' trust?! Every day is a wild party in this rom-com centering around the quintuplet sisters of the Nakano household!\n\n\n(Source: Crunchyroll)','\n',char(10)),7.5,'TV',2,0,'24 min','Tezuka Productions','WINTER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103572-cchriAdH95cQ.png','["Comedy","Drama","Romance","Slice of Life"]',331537,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(104157,38329,'Seishun Buta Yarou wa Yumemiru Shoujo no Yume wo Minai','Rascal Does Not Dream of a Dreaming Girl',replace('In Fujisawa, where the skies are bright and the seas glisten, Sakuta Azusagawa is in his second year of high school. His blissful days with his girlfriend and upperclassman, Mai Sakurajima, are interrupted with the appearance of his first crush, Shouko Makinohara. For reasons unknown, he encounters two Shouko''s: one in middle school and another who has become an adult.\n\n\n\n\nAs Sakuta finds himself helplessly living with the Shouko''s, the adult Shouko leads him around by the nose, causing a huge rift in his relationship with Mai.\n\n\n\n\nIn the midst of all of this, he discovers that the middle school Shouko is suffering from a grave illness and his scar begins to throb...\n\n\n\n\n(Source: Aniplex USA)','\n',char(10)),8.4,'MOVIE',2,0,'90 min','CloverWorks','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104157-rk99XI56PaIC.jpg','["Drama","Psychological","Romance","Supernatural"]',266375,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(104276,38408,'Boku no Hero Academia 4','My Hero Academia Season 4',replace('The villain world teeters on the brink of war now that All For One is out of the picture. Shigaraki of the League of Villains squares off with Overhaul of the yakuza, vying for total control of the shadows. Meanwhile, Deku gets tangled in another dangerous internship as he struggles to keep pace with his upperclassman—Mirio.\n\n(Source: Crunchyroll)','\n',char(10)),7.8,'TV',2,0,'24 min','bones','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104276-SnEowMvesWIE.png','["Action","Adventure","Comedy","Drama","Sci-Fi"]',541712,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(104578,38524,'Shingeki no Kyojin Season 3 Part 2','Attack on Titan Season 3 Part 2',replace('The battle to retake Wall Maria begins now! With Eren’s new hardening ability, the Scouts are confident they can seal the wall and take back Shiganshina District. If they succeed, Eren can finally unlock the secrets of the basement—and the world. But danger lies in wait as Reiner, Bertholdt, and the Beast Titan have plans of their own. Could this be humanity’s final battle for survival?\n\n\n\n(Source: Funimation)','\n',char(10)),8.9,'TV',2,0,'24 min','WIT STUDIO','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104578-k61nx3LPjvgd.jpg','["Action","Drama","Fantasy","Mystery"]',624175,1794735119,10,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(105156,38659,'Shinchou Yuusha: Kono Yuusha ga Ore TUEEE Kuse ni Shinchou Sugiru','Cautious Hero: The Hero Is Overpowered but Overly Cautious','The goddess Rista summons a hero to help her hard mode video game-like world. The hero, Seiya, is exceptional in every way, but he is incredibly cautious to the point of buying three sets of armor (one to wear, a spare, and a spare for the spare) and going full power against weak slimes (just in case).',7.3,'TV',2,0,'24 min','WHITE FOX','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105156-ZVtxISdoUqnY.png','["Action","Adventure","Comedy","Fantasy"]',204784,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(105190,38656,'Darwin''s Game','Darwin''s Game',replace('Kaname Sudou, an ordinary high school student, receives an invitation email to try a mysterious app called "Darwin''s Game." Kaname, upon launching the app, is drawn into a game where players fight one another using superpowers called Sigils. Without knowing the reason for all this, can Kaname survive furious battles against the powerful players who attack him?\n\n\n\n(Source: Aniplex of America)\n\n\n\nNote: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),7,'TV',2,0,'24 min','Nexus','WINTER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105190-lSoQNlnMF6UP.jpg','["Action","Mystery","Sci-Fi","Thriller"]',176588,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(105228,38668,'Dorohedoro','Dorohedoro','The story revolves around Kaiman, who does not remember who he was before he was transfigured by a Magic user. This transformation left him with a reptile''s head, and a desire to find out the truth about who he really is. Accompanied by Nikaido, his female companion, he tracks down Magic Users in "The Hole" and unceremoniously chomps down on their head, hoping to find out who it was that put him in this state. One by one, they witness this "second man" inside the head of Kaiman, and after pulling them back out of his mouth he asks them all a question... "What did the guy inside my head say?"',7.9,'TV',2,0,'24 min','MAPPA','WINTER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105228-I4xr84QS9Pvk.jpg','["Action","Adventure","Comedy","Fantasy","Horror","Mystery"]',194882,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(105310,38671,'Enen no Shouboutai','Fire Force',replace('Year 198 of the Solar Era in Tokyo, special fire brigades are fighting against a phenomenon called spontaneous human combustion where human beings are turned into living infernos called "Infernals.” While the Infernals are first-generation cases of spontaneous human combustion, later generations possess the ability to manipulate flames while retaining human form. Shinra Kusakabe, a youth who gained the nickname Devil’s Footprints for his ability to ignite his feet at will, joins the Special Fire Force Company 8 which composes of other flames users as they work to extinguish any Infernals they encounter. As a faction that is creating Infernals appears, Shinra begins to uncover the truth behind a mysterious fire that caused the death of his family twelve years ago.\n\n (Source: Official Website)','\n',char(10)),7.6,'TV',2,0,'24 min','david production','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105310-2PKUvoaA6fTn.jpg','["Action","Drama","Sci-Fi","Supernatural"]',494058,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(105333,38691,'Dr. STONE','Dr. STONE',replace('After five years of harboring unspoken feelings, high-schooler Taiju Ooki is finally ready to confess his love to Yuzuriha Ogawa. Just when Taiju begins his confession however, a blinding green light strikes the Earth and petrifies mankind around the world— turning every single human into stone.\n\n\n\nSeveral millennia later, Taiju awakens to find the modern world completely nonexistent, as nature has flourished in the years humanity stood still. Among a stone world of statues, Taiju encounters one other living human: his science-loving friend Senkuu, who has been active for a few months. Taiju learns that Senkuu has developed a grand scheme—to launch the complete revival of civilization with science. Taiju''s brawn and Senkuu''s brains combine to forge a formidable partnership, and they soon uncover a method to revive those petrified.\n\n\n\nHowever, Senkuu''s master plan is threatened when his ideologies are challenged by those who awaken. All the while, the reason for mankind''s petrification remains unknown.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.1,'TV',2,0,'24 min','TMS Entertainment','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105333-GybuoSoOZfpH.jpg','["Action","Adventure","Comedy","Sci-Fi"]',565973,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(105334,38680,'Fruits Basket: 1st Season','Fruits Basket (2019)',replace('Tohru Honda thought her life was headed for misfortune when a family tragedy left her living in a tent. When her small home is discovered by the mysterious Soma clan, she suddenly finds herself living with Yuki, Kyo, and Shigure Soma. But she quickly learns their family has a bizarre secret of their own: when hugged by the opposite sex, they turn into the animals of the Zodiac!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.2,'TV',2,0,'24 min','TMS Entertainment','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105334-AZwEdMu4KFtV.jpg','["Comedy","Drama","Romance","Slice of Life","Supernatural"]',317094,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(106286,38826,'Tenki no Ko','Weathering With You',replace('High school student Hodaka leaves his home on an isolated island and moves to Tokyo, but he immediately becomes broke. He lives his days in isolation, but finally finds a job as a writer for a shady occult magazine. After he starts his job, the weather has been rainy day after day. In a corner of the crowded and busy city, Hodaka meets a young woman named Hina. Due to certain circumstances, Hina and her younger brother live together, but have a cheerful and sturdy life. Hina also has a certain power: the power to stop the rain and clear the sky.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.1,'MOVIE',2,0,'115 min','CoMix Wave','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx106286-5COcpd0J9VbL.png','["Drama","Romance","Slice of Life","Supernatural"]',363330,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(106479,38790,'Itai no wa Iya nano de Bougyoryoku ni Kyokufuri Shitai to Omoimasu.','BOFURI: I Don''t Want to Get Hurt, so I''ll Max Out My Defense.',replace('The story centers on Kaede Honjou, who is invited by her friend Risa Shiramine to play a virtual reality MMO game with her. While Kaede doesn''t dislike games, what she really, truly dislikes is being in pain. She creates a character named Maple, and decides to put all her points in VIT to minimize pain. As a result, she moves slowly, can''t use magic, and even a rabbit can get the best of her. However, as it turns out, she acquires a skill known as "Absolute Defense" as a result of her pumping points into VIT, as well as a "Counter Skill" that works against special moves. Now, with her ability to nullify all damage, she goes on adventures.\n\n(Source: Anime News Network, edited)','\n',char(10)),7.3,'TV',2,0,'24 min','SILVER LINK.','WINTER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx106479-JmPk1F5ubMtm.png','["Action","Adventure","Comedy","Fantasy","Slice of Life"]',186546,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(106625,38883,'Haikyuu!! TO THE TOP','HAIKYU!! TO THE TOP',replace('The Karasuno High School Volleyball Club finally won their way into the nationals after an intense battle for the Miyagi Prefecture Spring Tournament qualifiers. As they were preparing for the nationals, Kageyama is invited to go to All-Japan Youth Training Camp. At the same time, Tsukishima is invited to go to a special rookie select training camp for first-years in Miyagi Prefecture. Hinata feels panic that he’s being left behind as one of the first-years and then decides to show up at the Miyagi Prefecture rookie select training camp anyway... \n\n(Source: Crunchyroll)','\n',char(10)),8.3,'TV',2,0,'24 min','Production I.G','WINTER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx106625-UR22wB2NuNVi.png','["Comedy","Drama","Sports"]',298758,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(107660,39195,'BEASTARS','BEASTARS',replace('In a world populated by anthropomorphic animals, herbivores and carnivores coexist with each other. For the adolescents of Cherryton Academy, school life is filled with hope, romance, distrust, and uneasiness.\n\n\nThe main character is Legoshi the wolf, a member of the drama club. Despite his menacing appearance, he has a very gentle heart. Throughout most of his life, he has always been an object of fear and hatred by other animals, and he’s been quite accustomed to that lifestyle. But soon, he finds himself becoming more involved with his fellow classmates who have their own share of insecurities and finds his life in school changing slowly.\n\n\n(Source: moetron)','\n',char(10)),7.6,'TV',2,0,'23 min','Orange','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx107660-hgknnyaLchJW.png','["Drama","Mystery","Psychological","Romance","Slice of Life"]',261980,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(107693,39196,'Mairimashita! Iruma-kun','Welcome to Demon School! Iruma-kun','Suzuki Iruma has just been abandoned and sold to a demon by his irresponsible parents! Surprisingly, the next thing he knows he''s living with the demon who has adopted him as his new grandson, and has been transferred into a school in the demon world where his new "demon" grandfather works as the principal. Thus begins the cowardly Iruma-kun''s extraordinary school life among the otherworldly as he faces his true self, takes on challenges, and rises to become someone great...',7.7,'TV',2,0,'25 min','Bandai Namco Pictures','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx107693-A9bSSFAMxA6j.jpg','["Comedy","Fantasy"]',173166,1794735120,23,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108430,39533,'Given','given',replace('Tightly clutching his Gibson guitar, Mafuyu Satou steps out of his dark apartment to begin another day of his high school life. While taking a nap in a quiet spot on the gymnasium staircase, he has a chance encounter with fellow student Ritsuka Uenoyama, who berates him for letting his guitar''s strings rust and break. Noticing Uenoyama''s knowledge of the instrument, Satou pleads for him to fix it and to teach him how to play. Uenoyama eventually agrees and invites him to sit in on a jam session with his two band mates: bassist Haruki Nakayama and drummer Akihiko Kaji.\n\n\n\nSatou''s voice is strikingly beautiful, filling Uenoyama with the determination to make Satou the lead singer of the band. Though reticent at first, Satou takes the offer after an emotional meeting with an old friend. With the support of his new friends, Satou must not only learn how to play guitar, but also come to terms with the mysterious circumstances that led him to be its owner.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.3,'TV',2,0,'23 min','Lerche','SUMMER 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108430-UdruJPro4vDK.jpg','["Drama","Music","Romance","Slice of Life"]',214348,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108463,39534,'Jibaku Shounen Hanako-kun','Toilet-bound Hanako-kun',replace('"Hanako-san, Hanako-san... are you there?"\n\n\n\nAt Kamome Academy, rumors abound about the school''s Seven Mysteries, one of which is Hanako-san. Said to occupy the third stall of the third floor girls'' bathroom in the old school building, Hanako-san grants any wish when summoned. Nene Yashiro, an occult-loving high school girl who dreams of romance, ventures into this haunted bathroom... but the Hanako-san she meets there is nothing like she imagined! Kamome Academy''s Hanako-san... is a boy!\n\n\n\n(Source: Yen Press)','\n',char(10)),7.7,'TV',2,0,'24 min','Lerche','WINTER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108463-u03vrYnyB3L9.jpg','["Action","Comedy","Drama","Mystery","Supernatural"]',242403,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108465,39535,'Mushoku Tensei: Isekai Ittara Honki Dasu','Mushoku Tensei: Jobless Reincarnation',replace('When a 34-year-old underachiever gets run over by a bus, his story doesn’t end there. Reincarnated in a new world as an infant, Rudeus will seize every opportunity to live the life he’s always wanted. Armed with new friends, some freshly acquired magical abilities, and the courage to do the things he’s always dreamed of, he’s embarking on an epic adventure—with all of his past experience intact!\n\n\n\n(Source: Funimation, edited)\n\n\n\nNote: The anime pre-screened its 1st and 2nd episode starting on the 27th of December on the Nico Nico Live Broadcasting and D Anime Store services','\n',char(10)),8.1,'TV',2,0,'24 min','Studio Bind','WINTER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108465-1ANspF1EWyFx.jpg','["Adventure","Drama","Ecchi","Fantasy"]',472442,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108489,39547,'Yahari Ore no Seishun Love Come wa Machigatteiru. Kan','My Teen Romantic Comedy SNAFU Climax!',replace('As the members of the Service Club band together to host a school prom, Hachiman, Yukino and Yui will have to put their feelings into words and truly learn to understand each other at long last… if the Service Club can even stay afloat, that is!\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),8.2,'TV',2,0,'24 min','feel.','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108489-yGmYCE6dhFta.png','["Comedy","Drama","Romance","Slice of Life"]',229312,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108511,39551,'Tensei Shitara Slime Datta Ken 2nd Season','That Time I Got Reincarnated as a Slime Season 2',replace('Now that the Jura Tempest Alliance is growing even further, they will now be meeting the animal kingdom of Eurazania, reuniting with King Gazel, rising tensions between monsters and humans, and Rimuru encountering the strongest enemy he’s ever faced.\n\n\n\n(Source: Funimation)','\n',char(10)),8.2,'TV',2,0,'24 min','8-bit','WINTER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108511-PufFordLNyIb.jpg','["Action","Adventure","Comedy","Fantasy"]',330110,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108553,39565,'Boku no Hero Academia THE MOVIE: Heroes:Rising','My Hero Academia: Heroes Rising',replace('The aspiring heroes of UA Class 1-A have been given a new training opportunity during their winter break: To establish and maintain their own professional Hero Agency on the idyllic island of Nabu far off the coast of Japan. There, they''ll experience the everyday travails of being heroes, for the first time without the support of their instructors or chaperons. It''s a challenging assignment, but one the plucky students of UA are more than equipped to face – that is, until the arrival of a team of villains lead by the ruthless Nine and his eerily familiar quirk. Cut off from any backup and facing their greatest threat yet, it''s up to Deku, Bakugo, and their classmates to face unspeakable danger to protect not only the people of the island, but the future of all Hero society.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.8,'MOVIE',2,0,'104 min','bones','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108553-yOLfFogpWnTF.jpg','["Action","Sci-Fi"]',177729,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108632,39587,'Re:Zero kara Hajimeru Isekai Seikatsu 2nd Season','Re:ZERO -Starting Life in Another World- Season 2',replace('Even after dying countless times, Subaru finally ended the threat of the White Whale and defeated the Witch Cult''s Sin Archbishop representing sloth, Petelgeuse Romaneeconti. But only shortly after overcoming a tragic ending and reuniting with his beloved Emilia, Subaru learns that Rem has been erased from this world, having fallen victim to the White Whale''s Fog of Elimination in the midst of Subaru''s death loop. With the White Whale now gone, Subaru and Emilia are forced to confront a reality they never dreamed would happen.\n\n(Source: Crunchyroll)','\n',char(10)),8.3,'TV',2,0,'26 min','WHITE FOX','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108632-lQWnmw7XaNOK.jpg','["Action","Adventure","Drama","Fantasy","Psychological","Thriller"]',390755,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108725,39617,'Yakusoku no Neverland 2','The Promised Neverland Season 2',replace('Fifteen children escape Grace Field House, a false paradise, hoping for a chance at freedom. Instead, they encounter plants and animals they have never before seen, and are chased by demons. The outside world is so beautiful, and yet is almost too cruel to face.\n\n\n\nEven so, the children refuse to give up. They are guided in their search for better lives only by a message from Minerva and a pen Norman left behind in order to fulfill their promise to return to the House to save those of their family who are still trapped within.\n\n\n(Source: Aniplex of America)\n\n\n\nNote: Episode 1 streamed early on Amazon Prime on Jan 7, 2021. The regular TV broadcast started on Jan 8, 2021.','\n',char(10)),5.1,'TV',2,0,'23 min','CloverWorks','WINTER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108725-ZKivuyr4Jtc9.jpg','["Action","Adventure","Drama","Fantasy","Horror","Psychological","Thriller"]',325866,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108759,39597,'Sword Art Online: Alicization - War of Underworld','Sword Art Online: Alicization - War of Underworld',replace('Kirito, Eugeo, and Alice. Six months have passed since the two disciples and an Integrity Knight brought down the pontifex, Administrator. With the fighting over, Alice has been living in her hometown of Rulid Village. Beside her is Kirito, who has not only lost his arm and soul, but also his dear friend. As Alice devotes herself to looking after Kirito, she too has lost the will to fight she once had as a knight.\n\n\n\nNevertheless, the time for the final stress test – one which will engulf the entire Underworld with tragedy – draws relentlessly closer.\n\n\n\nMeanwhile, in the deepest areas of the Dark Territory, the Dark God Vecta has resurrected, as if to have waited for this very moment. Leading an army of dark forces, they begin their invasion into the human empire in hopes of attaining the Priestess of Light. The human empire force led by the Integrity Knight Bercouli prepares for a war of an unimaginable scale against the army of the Dark Territory. Even then, Alice is nowhere to be seen, nor the two heroes that saved the realm...\n\n\n\n(Source: Official Website)','\n',char(10)),7.5,'TV',2,0,'24 min','A-1 Pictures','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108759-jcXbDf9BJTcb.jpg','["Action","Adventure","Drama","Fantasy","Sci-Fi"]',225616,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(108928,39701,'Nanatsu no Taizai: Kamigami no Gekirin','The Seven Deadly Sins: Imperial Wrath of the Gods','Despite repelling the demon invasion of the Kingdom of Lioness, the war is far from over, for Arthur''s Kingdom of Camelot is still being occupied by the demon army and the surviving members of Jikkai. However, in order to begin counter-offensive, the Seven Deadly Sins needs all of its members. Unfortunately, King and Diane are still hiding in the Fairy King''s Forest, where they are made to discover the strange history of Jikkai.',6.3,'TV',2,0,'24 min','Studio DEEN','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108928-DuyUzi0JyPIr.jpg','["Action","Adventure","Comedy","Ecchi","Fantasy","Supernatural"]',206384,1794735120,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(109261,39783,'Go-toubun no Hanayome ∬','The Quintessential Quintuplets 2',replace('Through their tutor Fuutarou Uesugi''s diligent guidance, the Nakano quintuplets'' academic performance shows signs of improvement, even if their path to graduation is still rocky. However, as they continue to cause various situations that delay any actual tutoring, Fuutarou becomes increasingly involved with their personal lives, further complicating their relationship with each other.\n\n\n\nOn another note, Fuutarou slowly begins to realize the existence of a possible connection between him and the past he believes to have shared with one of the five girls. With everyone''s feelings beginning to develop and overlap, will they be able to keep their bond strictly to that of a teacher and his students—or will it mature into something else entirely?\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.9,'TV',2,0,'24 min','Bibury Animation Studios','WINTER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx109261-65rKxMDlcU9r.png','["Comedy","Drama","Romance","Slice of Life"]',239117,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(109963,39940,'Shokugeki no Souma: Shin no Sara','Food Wars! The Fourth Plate',replace('The ultimate Regimental Food War continues as the culinary rebels led by Souma and the members of Kyokusei square off against epicurean elitist Azami and the Toutsuki Ten. At stake – the future of dining across Japan. Because if the rebels fail, Azami intends to impose his own tastes and techniques on the entire restaurant industry!\n\n\n\nBut the fine dining control freak has made a serious mistake in threatening the futures of Souma’s friends and family, as while the rebels may seem less experienced overall, this is ultimately a clash of skill, dedication, and, most of all, taste. That may be a recipe for disaster for the seasoned veterans!\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.6,'TV',2,0,'24 min','J.C.STAFF','FALL 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx109963-t8E9axH0Dvrn.jpg','["Comedy","Ecchi"]',178927,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(110277,40028,'Shingeki no Kyojin: The Final Season','Attack on Titan Final Season',replace('It’s been four years since the Scout Regiment reached the shoreline, and the world looks different now. Things are heating up as the fate of the Scout Regiment—and the people of Paradis—are determined at last. However, Eren is missing. Will he reappear before age-old tensions between Marleyans and Eldians result in the war of all wars?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.7,'TV',2,0,'24 min','MAPPA','WINTER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx110277-sKUNXAsWMNFw.jpg','["Action","Drama","Fantasy","Mystery"]',656938,1794735119,16,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(110349,40052,'GREAT PRETENDER','Great Pretender',replace('Self-styled “Japan''s greatest swindler” Makoto Edamura is mainly targeting elder people and occasional foreign travelers. But when he tries to scam an apparently clueless French tourist in Tokyo, he can''t possibly imagine that what looked like just another ordinary job is going to take him all the way to Los Angeles, tied upside-down on the famous Hollywood sign… And he is yet to find out what fate awaits him!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.1,'ONA',2,0,'23 min','WIT STUDIO','SPRING 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx110349-59hhZ9CNHVdk.png','["Action","Comedy","Drama","Thriller"]',234799,1794735119,23,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(110694,37290,'ANI × PARA: Anata no Hero wa Dare desu ka','Animation × Paralympic: Who Is Your Hero?',replace('“ANIMATION × PARALYMPIC: Who Is Your Hero?” is a special series featuring fictional Paralympic athletes depicted in world-renowned Japanese animation. The project aims to introduce new Paralympic sports heroes through attractive characters and stories that will be created by the collaboration of famous comic creators and animation film directors. The series will increase the number of featured sports by 2020.\n\n\n\nAn episode animated by Kyoto Animation was scheduled to be broadcast in August 2019, but was later announced to be cancelled after it was determined production could not be completed in time for the 2020 Paralympic Games due to a tragic arson attack on the studio.','\n',char(10)),5.8,'SPECIAL',1,0,'5 min','Nippon Animation','FALL 2017','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b110694-h0RmA1JtT14f.jpg','["Sports"]',1002,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(111321,40356,'Tate no Yuusha no Nariagari Season 2','The Rising of the Shield Hero Season 2',replace('With another Wave happening in a week, Naofumi Iwatani and his party have no time to waste. However, when bat familiars raid Lurolona Village and the Wave countdown comes to a halt, the Four Cardinal Heroes reconvene with the queen, Mirelia Q Melromarc, for a quick briefing. The queen presumes that the odd occurrences are linked to the Spirit Tortoise—a threatening creature that has awakened from its slumber, back to cause havoc once again. A plan to put the Spirit Tortoise to rest is devised—but out of the four men, only the cursed Shield Hero agrees to help.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),6.5,'TV',2,0,'24 min','Kinema Citrus','SPRING 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx111321-dIr3dEKOIPer.png','["Action","Adventure","Fantasy"]',250954,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(111762,40417,'Fruits Basket: 2nd Season','Fruits Basket Season 2',replace('A year has passed since Tohru Honda began living in the Souma residence, and she has since created stronger relationships with its inhabitants Shigure, Kyou, and Yuki. She has also grown closer to the rest of the Souma family and has become familiar with their ancestral secret, having helped them with many of their personal issues. The closer Tohru gets, however, the more she begins to realize that their secret holds a darker truth than she first presumed.\n\n\nSummer is approaching and Tohru is invited to spend her days with the Soumas, mainly Kyou and Yuki. Tohru wishes for an easy-going vacation, but her close relationships with the two boys and the rest of the Soumas may prove to cause trouble. As they grow more intimate, their carefree time together is hindered by older hardships and feelings from the past that begin to resurface. The Eternal Banquet also dawns on the members of the zodiac, and they must tend to their duties alongside the unnerving head of the family, Akito Souma.\n\n\nWith the banquet approaching and a plethora of feelings to be solved, will Tohru''s life with the Soumas remain peaceful, or will she find herself in a situation from which she cannot escape?','\n',char(10)),8.5,'TV',2,0,'24 min','TMS Entertainment','SPRING 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx111762-C8TNf5uRlVNQ.jpg','["Comedy","Drama","Psychological","Romance","Slice of Life","Supernatural"]',189278,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(112124,40454,'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka III','Is It Wrong to Try to Pick Up Girls in a Dungeon? III',replace('When Bell encounters a frightened little girl in the dungeon, he doesn’t think twice to help. But this simple act of kindness has consequences. The girl is a monster and proof that monsters can be eerily human. And not everyone can accept this...\n\n\n\n(Source: HIDIVE)','\n',char(10)),7.4,'TV',2,0,'24 min','J.C.STAFF','FALL 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112124-ZmoOntBuiSUU.jpg','["Action","Adventure","Comedy","Fantasy","Romance"]',203656,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(112151,40456,'Kimetsu no Yaiba: Mugen Ressha-hen','Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train','This Demon Slayer movie sees Tanjiro Kamado and friends from the Demon Slayer corps board the Infinity Train on a new mission to investigate a mysterious series of disappearances, perpetrated by a demon who has been tormenting people and killing the demon slayers who oppose it.',8.4,'MOVIE',2,0,'117 min','ufotable','FALL 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112151-1qlQwPB1RrJe.png','["Action","Adventure","Drama","Fantasy","Mystery","Supernatural"]',518623,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(112301,40496,'Maou Gakuin no Futekigousha: Shijou Saikyou no Maou no Shiso, Tensei shite Shison-tachi no Gakkou e Kayou','The Misfit of Demon King Academy: History’s Strongest Demon King Reincarnates and Goes to School with His Descendants',replace('Anos, the Demon King of Tyranny, has defeated humans, spirits, and gods alike. But even demon kings get tired of all the fighting sometimes! Hoping for a more peaceful life, Anos decides to reincarnate himself. When he wakes two thousand years later, though, he finds the world has become too peaceful--his descendants have grown weak and magic is in serious decline. Intending to reclaim his rightful place, he enrolls in Demon King Academy, where he finds that his magical power is off the charts. Literally. And because they can''t measure his power, the faculty and other students regard Anos as a misfit. With the support of Misha, the one student he manages to befriend, the misfit (Demon King) begins his climb up the demon ranks!\n\n\n\n(Source: Square Enix)','\n',char(10)),7.2,'TV',2,0,'24 min','SILVER LINK.','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112301-f88Fs2es4pSr.jpg','["Action","Comedy","Fantasy"]',273199,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(112641,40591,'Kaguya-sama wa Kokurasetai?: Tensaitachi no Renai Zunousen','Kaguya-sama: Love is War?',replace('After a slow but eventful summer vacation, Shuchiin Academy''s second term is now starting in full force. As August transitions into September, Miyuki Shirogane''s birthday looms ever closer, leaving Kaguya Shinomiya in a serious predicament as to how to celebrate it. Furthermore, the tenure of the school''s 67th student council is coming to an end. Due to the council members being in different classes, the only time Kaguya and Miyuki have to be together will soon disappear, putting all of their cunning plans at risk.\n\n\nA long and difficult election that will decide the fate of the new student council awaits, as multiple challengers fight for the coveted title of president.\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.5,'TV',2,0,'25 min','A-1 Pictures','SPRING 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112641-zoGC8d6FaPXU.jpg','["Comedy","Psychological","Romance","Slice of Life"]',442432,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(113415,40748,'Jujutsu Kaisen','JUJUTSU KAISEN',replace('A boy fights... for "the right death."\n\n\n\nHardship, regret, shame: the negative feelings that humans feel become Curses that lurk in our everyday lives. The Curses run rampant throughout the world, capable of leading people to terrible misfortune and even death. What''s more, the Curses can only be exorcised by another Curse.\n\n\n\nItadori Yuji is a boy with tremendous physical strength, though he lives a completely ordinary high school life. One day, to save a friend who has been attacked by Curses, he eats the finger of the Double-Faced Specter, taking the Curse into his own soul. From then on, he shares one body with the Double-Faced Specter. Guided by the most powerful of sorcerers, Gojou Satoru, Itadori is admitted to the Tokyo Metropolitan Technical High School of Sorcery, an organization that fights the Curses... and thus begins the heroic tale of a boy who became a Curse to exorcise a Curse, a life from which he could never turn back.\n\n\n\n(Source: Crunchyroll)\n\n\n\nNote: The first episode received an early web premiere on September 19th, 2020. The regular TV broadcast started on October 3rd, 2020.','\n',char(10)),8.4,'TV',2,0,'24 min','MAPPA','FALL 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113415-LHBAeoZDIsnF.jpg','["Action","Drama","Supernatural"]',996637,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(113538,40776,'Haikyuu!! TO THE TOP 2','HAIKYU!! TO THE TOP Part 2','The second half of Haikyuu!! 4th season kicks-off where the first part ended. Karasuno High won their first match of The Spring Nationals against Tsubakihara Academy. Karasuno High is excited to be back in the Spring Nationals after many years of not making it, so can they handle the pressure of playing against the best teams in Japan? Will they make it to the top?',8.5,'TV',2,0,'24 min','Production I.G','FALL 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113538-tHVE8j5mOPLu.jpg','["Comedy","Drama","Sports"]',259481,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(113596,40787,'Josee to Tora to Sakanatachi','Josee, the Tiger and the Fish',replace('The story centers on the relationship between Tsuneo and Josee. Tsuneo is a university student, and Josee is a young girl who has rarely gone out of the house by herself due to her being unable to walk. The two meet when Tsuneo finds Josee''s grandmother taking her out for a morning walk.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.2,'MOVIE',2,0,'98 min','bones','FALL 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113596-LKA0bYJGjLnB.jpg','["Drama","Romance","Slice of Life"]',191035,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(113717,40834,'Ousama Ranking','Ranking of Kings',replace('Unable to hear, speak, or wield a sword, Prince Bojji doesn’t seem like a typical heir to the throne—and his kingdom agrees. But his fateful encounter with Kage, a shadow on the ground, gives him his first true friend. The two set off on a grand adventure and, together, form a bond that can overcome any obstacle...even being king.\n\n\n\n(Source: Funimation)','\n',char(10)),8.3,'TV',2,0,'23 min','WIT STUDIO','FALL 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113717-9sNnN8WRgK15.jpg','["Action","Adventure","Drama","Fantasy"]',228656,1794735120,23,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(113813,40839,'Kanojo, Okarishimasu','Rent-a-Girlfriend',replace('Kinoshita Kazuya is a 20-year-old failure of a college student. He managed to kiss his girlfriend once, but was dumped after a month. "Ugh... Damn it. I never want to go through that again." \n\n\n\nCompletely spiteful, Kazuya uses a certain method to date a girl. He goes to their meeting place and suddenly hears, "You''re Kazuya-kun, right?" A beautiful girl brushing her long, black hair behind her ear was there, smiling at him. Her name was Mizuhara Chizuru. Something real is born after just a single rental! A reckless rom-com filled with love and excitement is about to begin!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.5,'TV',2,0,'24 min','TMS Entertainment','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113813-SnljeXpU3Pw7.jpg','["Comedy","Drama","Romance"]',313481,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(113936,40852,'Dr. STONE: STONE WARS','Dr. STONE: STONE WARS',replace('Armed with the power of science and a genius intellect, Senkuu is determined to save humanity. However, Tsukasa’s empire goes on the offensive to halt the progress of science. Bolder choices are made as these two start a war that rocks the Stone World. \n\n\n(Source: Crunchyroll)','\n',char(10)),8.1,'TV',2,0,'24 min','TMS Entertainment','WINTER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113936-D4eYd4XwslVI.jpg','["Action","Adventure","Comedy","Sci-Fi"]',341676,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(114232,40938,'Hige wo Soru. Soshite Joshikousei wo Hirou.','Higehiro: After Being Rejected, I Shaved and Took in a High School Runaway',replace('On his way home from drinking his sorrows away after being rejected by his crush, the 26 year old salaryman, Yoshida, finds a high school girl named Sayu sitting on the side of the road. Yoshida is completely drunk out of his mind and ends up letting Sayu stay at his place overnight. Not having the heart to put Sayu out on the streets since she ran away from home, Yoshida allows her to stay at his place... And so began the awkward, irritable, and slightly heartwarming relationship between a runaway high school girl and a salaryman living together.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7,'TV',2,0,'24 min','project No.9','SPRING 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114232-2rm50ZD1cQgP.jpg','["Drama","Romance","Slice of Life"]',190851,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(114236,40956,'Enen no Shouboutai: Ni no Shou','Fire Force Season 2',replace('Shinra and Company 8 have figured out the Evangelist’s goal: to gather Adolla Bursts from Shinra and Shou. After learning more about his past from Captain Burns, Shinra becomes more motivated to discover the truth about his mother and save Shou again.\n\n\n\nBut a mysterious girl known as the “First Pillar” reveals the Evangelist’s master plan to start another Great Cataclysm!\n\n\n\n(Source: Funimation)','\n',char(10)),7.8,'TV',2,0,'24 min','david production','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114236-wfQOWF0Ii3h2.png','["Action","Drama","Sci-Fi","Supernatural"]',306956,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(114308,40540,'Sword Art Online: Alicization - War of Underworld Part 2','Sword Art Online: Alicization - War of Underworld Part 2',replace('The final load test... The war between the Human Empire and the Dark Territory has engulfed Underworld entirely. The battle has shifted course with the Dark Territory army led by Gabriel, who seeks to capture Alice, the Priestess of Light, against Asuna and the Human Empire forces fighting to save Underworld.\n\n\n\nAs Kirito''s consciousness remains buried in a deep sleep, Gabriel, standing in as the Dark God Vecta, has recruited thousands of American players to log in to Underworld to annihilate the Human Empire forces. Meanwhile, Asuna, Sinon, and Leafa have joined the battle utilizing three super-accounts of the deities of the Underworld. As the Goddess of Creation Stacia Asuna fights alongside the Human Empire forces to take on the American players in a vicious combat. Sinon, who has gained the super-account for the Sun Goddess Solus, is in pursuit of Gabriel, who has abducted Alice, while Leafa arrives to Underworld with the super-account Earth Goddess Terraria.\n\n\n\nBut that is not all...\n\n\n\nThe impassioned speech by Lisbeth has convinced many ALO players to join the fight with the Human Empire despite the risks. With this great war, not only Underworld''s continued existence, but the bottom-up artificial intelligence, the ultimate AI, and even the future of mankind is at stake.\n\n\n\nThough he has yet to awaken, only one man holds the fate of this world: the Black Swordsman.\n\n\n\n(Source: Official Website)','\n',char(10)),7.4,'TV',2,0,'24 min','A-1 Pictures','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114308-8UBiS7U9buzu.jpg','["Action","Adventure","Fantasy"]',200489,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(114535,41025,'Fumetsu no Anata e','To Your Eternity',replace('In the beginning, an "orb" is cast unto Earth. "It" can do two things: change into the form of the thing that stimulates "it"; and come back to life after death. "It" morphs from orb to rock, then to wolf, and finally to boy, but roams about like a newborn who knows nothing. As a boy, "it" becomes Fushi.\n\n\n\nThrough encounters with human kindness, Fushi not only gains survival skills but grows as a "person". But his journey is darkened by the inexplicable and destructive enemy Nokker and cruel partings with the people he loves.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.1,'TV',2,0,'25 min','Brain''s Base','SPRING 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114535-y3NnjexcqKG1.jpg','["Adventure","Drama","Fantasy","Psychological","Supernatural"]',323569,1794735119,20,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(114963,41168,'Nakitai Watashi wa Neko wo Kaburu','A Whisker Away',replace('Miyo Sasaki is an energetic high school girl who comes from a broken family consisting of her unconfident father and an overly invested stepmother, whose attempts at connecting with Miyo come across as bothersome. Seeing Kento Hinode as a refuge from all her personal issues, she can''t help herself from forcing her unorthodox demonstrations of love onto her crush.\n\n\n\nWhile Miyo is unable to get Kento''s attention as herself, she manages to succeed by interacting with him in the form of a white cat, affectionately nicknamed ""Tarou"" by Kento. But Miyo soon realizes that she can''t help Kento with the various problems she overhears in her cat form and is now caught between two tough choices. Will she continue her relationship with him as a cat, or will she reveal her identity and risk what they have, in order to help him as her human self?\n\n\n\n[Written by MAL Rewrite]\n\n\n\nNote: The film was slated to open in theaters in Japan on June 5, but was postponed due to COVID-19 and received an exclusive streaming on Netflix beginning on June 18.','\n',char(10)),7.3,'MOVIE',2,0,'104 min','Studio Colorido','SPRING 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114963-QWMbi5ttovSK.png','["Drama","Fantasy","Romance"]',194991,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(115230,40221,'Kami no Tou: Tower of God','Tower of God',replace('There is a tower that summons chosen people called "Regulars" with the promise of granting their deepest desires. Whether it be wealth, fame, authority, or something that surpasses them all—everything awaits those who reach the top.\n\n\n\nTwenty-Fifth Bam is a boy who had only known a dark cave, a dirty cloth, and an unreachable light his entire life. So when a girl named Rachel came to him through the light, his entire world changed. Becoming close friends with Rachel, he learned various things about the outside world from her. But when Rachel says she must leave him to climb the Tower, his world shatters around him. Vowing to follow after her no matter what it takes, he sets his sight on the tower, and a miracle occurs.\n\n\n\nThus begins the journey of Bam, a young boy who was not chosen by the Tower but opened its gates by himself. They call his kind "Irregulars"—beings that have shaken the very foundation of the Tower each time they set foot inside it.','\n',char(10)),7.4,'TV',2,0,'25 min','Telecom Animation Film','SPRING 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx115230-QHOdSN7yt8ab.jpg','["Action","Adventure","Drama","Fantasy","Mystery"]',341495,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(116006,41353,'THE GOD OF HIGH SCHOOL','The God of High School',replace('It all began as a fighting tournament to seek out for the best fighter among all high school students in Korea. Mori Jin, a Taekwondo specialist and a high school student, soon learns that there is something much greater beneath the stage of the tournament.\n\n(Source: WEBTOON)','\n',char(10)),6.9,'TV',2,0,'24 min','MAPPA','SUMMER 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx116006-Wt8JSA1ZQxlM.png','["Action","Fantasy"]',304133,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(116267,41389,'Tonikaku Kawaii','TONIKAWA: Over The Moon For You',replace('The story follows a protagonist whose name is written with the characters for "Hoshizora" ("Starry Sky" in Japanese), but whose name is pronounced as "Nasa". On the day of his high school entrance exams, Nasa encounters a beautiful girl named Tsukasa. For Nasa, it feels like destiny is finally calling out to him that he will have a girlfriend, but things take a turn for the worse when Nasa is hit by a car and unable to attend his entrance exams.\n\n\n\nAfter Tsukasa helps the injured Nasa, he confesses his feelings to her, and she agrees to go out with him, but only if Nasa agrees to marry her first. A year later Nasa aces the entrance exams, but he decides to work a part time job and live by himself instead of going to school. After Nasa turns 18, Tsukasa re-appears, and their happy, romantic, and mysterious married life together begins.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.7,'TV',2,0,'24 min','Seven Arcs','FALL 2020','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx116267-Eo1biPBTlL4i.jpg','["Comedy","Romance","Slice of Life"]',252022,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(116589,41457,'86: Eighty Six','86 EIGHTY-SIX',replace('Called “Juggernaut,” these are the unmanned combat drones developed by the Republic of San Magnolia in answer to the attacks by the autonomous unmanned drones of the neighboring Empire of Giad, the “Legion”. But they’re only unmanned in name. In reality, they are piloted by the Eighty-sixers—those considered to be less than human and treated as mere tools.\n\n\n\nDetermined to achieve his own mysterious ends, Shin, the captain of Spearhead Squadron, which is comprised of Eighty-sixers, continues to fight a hopeless war on a battlefield where only death awaits him.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.3,'TV',2,0,'24 min','A-1 Pictures','SPRING 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx116589-KawXHB6sApFt.jpg','["Action","Drama","Mecha","Sci-Fi"]',334814,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(116674,41467,'BLEACH: Sennen Kessen-hen','BLEACH: Thousand-Year Blood War',replace('Was it all just a coincidence, or was it inevitable?\n\n\n\nIchigo Kurosaki gained the powers of a Soul Reaper through a chance encounter. As a Substitute\nSoul Reaper, Ichigo became caught in the turmoil of the Soul Society, a place where deceased\nsouls gather. But with help from his friends, Ichigo overcame every challenge to become even\nstronger.\n\n\n\nWhen new Soul Reapers and a new enemy appear in his hometown of Karakura, Ichigo jumps\nback into the battlefield with his Zanpakuto to help those in need. Meanwhile, the Soul Society\nis observing a sudden surge in the number of Hollows being destroyed in the World of the Living.\nThey also receive separate reports of residents in the Rukon District having gone missing. Finally,\nthe Seireitei, home of the Soul Reapers, comes under attack by a group calling themselves the\nWandenreich.\n\n\n\nLed by Yhwach, the father of all Quincies, the Wandenreich declare war against the Soul Reapers\nwith the following message: "Five days from now, the Soul Society will be annihilated by the\nWandenreich."\n\n\n\nThe history and truth kept hidden by the Soul Reapers for a thousand long years is finally brought\nto light.\n\n\n\nAll things must come to an end as Ichigo Kurosaki''s final battle begins!','\n',char(10)),8.8,'TV',2,0,'24 min','Studio Pierrot','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx116674-p3zK4PUX2Aag.jpg','["Action","Adventure","Supernatural"]',215295,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(116742,41487,'Tensei Shitara Slime Datta Ken 2nd Season Part 2','That Time I Got Reincarnated as a Slime Season 2 Part 2',replace('The nation of Tempest is in a festive mood after successfully overcoming the surprise attack from the Falmuth Army and the Western Holy Church. Beyond the festivities lies a meeting between Tempest and its allies to decide the future of the Nation of Monsters. The aftermath of the Falmuth invasion, Milim Nava''s suspicious behavior, and the disappearance of Demon Lord Carrion—the problems seem to keep on piling up.\n\n\n\nRimuru Tempest, now awakened as a "True Demon Lord," decides to go on the offensive against Clayman. With the fully revived "Storm Dragon" Veldora, "Ultimate Skill" Raphael, and other powerful comrades, the ruler of the Tempest is confident in taking down his enemies one by one until he can face the man pulling the strings.','\n',char(10)),8.2,'TV',2,0,'24 min','8-bit','SUMMER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx116742-jn0dW23ftehq.jpg','["Action","Adventure","Comedy","Fantasy"]',278274,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(117193,41587,'Boku no Hero Academia 5','My Hero Academia Season 5',replace('The rivalry between Class 1-A and Class 1-B heats up in a joint training battle. Eager to be a part of the hero course, brainwashing buff Shinso is tasked with competing on both sides.\n\n\n\nBut as each team faces their own weaknesses and discovers new strengths, this showdown might just become a toss-up.\n\n\n(Source: Funimation)','\n',char(10)),7.3,'TV',2,0,'24 min','bones','SPRING 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx117193-E75BlZmDh1aB.jpg','["Action","Adventure","Comedy","Sci-Fi"]',423023,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(118123,44042,'Holo no Graffiti','ホロのぐらふぃてぃ',replace('From unraveling the secrets of opening and closing doors to defusing surprise packages more commonly known as bombs, there is never a dull day at the Hololive Production office! Holo no Graffiti follows an eccentric cast of Virtual YouTubers, also known as "VTubers," going about their absurd yet hilarious daily lives, detailing all their cute moments and mishaps.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'ONA',1,7,'2 min','Cover Corp','SPRING 2019','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx118123-xqn5fYsjKXJU.png','["Action","Adventure","Comedy"]',14889,1794782800,0,1795338000,393);
