INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(131518,48549,'Dr. STONE: NEW WORLD','Dr. STONE New World',replace('Senkuu and the Kingdom of Science sail to new lands to uncover more scientific secrets! \n\n\n(Source: Crunchyroll)','\n',char(10)),8.1,'TV',2,0,'24 min','TMS Entertainment','SPRING 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131518-RU7RoUmGb2sP.jpg','["Action","Adventure","Comedy","Sci-Fi"]',207052,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(131565,48556,'takt op.Destiny','takt op.Destiny',replace('Music is the light that illuminates people''s hearts-- and that "light" was suddenly taken from the world. The world changed the night the black "Kuroya Meteorite" fell. Grotesque monsters known as D2 emerged from the meteorite and began to overrun the land and people. As the D2 were drawn to melodies people played, eventually "music" itself became taboo. \n\n\n\nHowever, those who opposed the monsters appeared. They the "Musicart," girls who draw power from music. They possess the great operas and musical scores of humanity history and use them to defeat the D2.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.9,'TV',2,0,'24 min','MADHOUSE','FALL 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131565-3W2YEX6V3K3i.jpg','["Action","Fantasy","Music"]',171666,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(131573,48561,'Jujutsu Kaisen 0','JUJUTSU KAISEN 0',replace('Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him?\n\n\n\n(Source: VIZ Media)','\n',char(10)),8.3,'MOVIE',2,0,'105 min','MAPPA','FALL 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131573-rpl82vDEDRm6.jpg','["Action","Supernatural"]',448834,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(131586,48569,'86: Eighty Six Part 2','86 EIGHTY-SIX Part 2',replace('Having bid Lena farewell, Shin and the surviving members of the Spearhead squadron continue into the heart of Legion territory. There, they endure countless hardships until they''re rescued by the Federal Republic of Giad, a reformed nation that offers them a second chance at a peaceful life. But it isn''t long before a sense of duty calls the Eighty-Six back to the battlefield. Choosing to enlist in the military, they willingly walk back through the gates of hell, this time joined by a peculiar new ally-Frederica Rosenfort: a haughty young girl with a rare ability and wisdom far beyond her years.\n\n\n\n(Source: Yen Press)\n\n\n\nNote: The last two episodes were originally set to air in the first two weeks of January 2022, but were postponed to the second and third week of March due to production issues.','\n',char(10)),8.7,'TV',2,0,'24 min','A-1 Pictures','FALL 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131586-JhC0wcBi09EZ.jpg','["Action","Drama","Mecha","Sci-Fi"]',203080,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(131646,48580,'Vanitas no Carte','The Case Study of Vanitas',replace('It’s 19th-century Paris, and young vampire Noé hunts for the Book of Vanitas. Attacked by a vampire driven insane, a human intercedes, rescues Noé, and heals the sick creature. Commanding the book and calling himself Vanitas, this doctor tempts Noé with a mad crusade to “cure” the entire vampire race. Allying with one who wields arcane power so easily may be dangerous, but does he have a choice?\n\n\n\n(Source: Funimation)','\n',char(10)),7.8,'TV',2,0,'23 min','bones','SUMMER 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131646-cuyGfKcekZ62.jpg','["Action","Drama","Fantasy","Mystery","Supernatural"]',215056,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(131681,48583,'Shingeki no Kyojin: The Final Season Part 2','Attack on Titan Final Season Part 2',replace('The war for Paradis zeroes in on Shiganshina just as Jaegerists have seized control. After taking a huge blow from a surprise attack led by Eren, Marley swiftly acts to return the favor. With Zeke’s true plan revealed and a military forced under new rule, this battle might be fought on two fronts. Does Eren intend on fulfilling his half-brother’s wishes or does he have a plan of his own?\n\n\n\n(Source: Funimation)','\n',char(10)),8.7,'TV',2,0,'24 min','MAPPA','WINTER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131681-5ooUqvqNtee1.jpg','["Action","Drama","Fantasy","Mystery","Psychological"]',452606,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(131942,48661,'JoJo no Kimyou na Bouken: Stone Ocean','JoJo''s Bizarre Adventure: STONE OCEAN',replace('In Florida, 2011, Jolyne Kuujou sits in a jail cell like her father Joutarou once did; yet this situation is not of her own choice. Framed for a crime she didn’t commit, and manipulated into serving a longer sentence, Jolyne is ready to resign to a dire fate as a prisoner of Green Dolphin Street Jail. Though all hope seems lost, a gift from Joutarou ends up awakening her latent abilities, manifesting into her Stand, Stone Free. Now armed with the power to change her fate, Jolyne sets out to find an escape from the stone ocean that holds her.\n\n\n\nHowever, she soon discovers that her incarceration is merely a small part of a grand plot: one that not only takes aim at her family, but has additional far-reaching consequences. What''s more, the mastermind is lurking within the very same prison, and is under the protection of a lineup of menacing Stand users. Finding unlikely allies to help her cause, Jolyne sets course to stop their plot, clear her name, and take back her life.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8,'ONA',2,0,'24 min','david production','FALL 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131942-rermlZ9lplHX.png','["Action","Adventure","Drama","Supernatural"]',198457,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(132405,48736,'Sono Bisque Doll wa Koi wo Suru','My Dress-Up Darling',replace('High schooler Wakana Gojou cares about one thing: making Hina dolls. With nobody to share his obsession, he has trouble finding friends—or even holding conversation. But after the school’s most popular girl, Marin Kitagawa, reveals a secret of her own, he discovers a new purpose for his sewing skills. Together, they’ll make her cosplay dreams come true! \n\n\n\n(Source: Funimation)','\n',char(10)),8,'TV',2,0,'24 min','CloverWorks','WINTER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx132405-qP7FQYGmNI3d.jpg','["Comedy","Ecchi","Romance","Slice of Life"]',443361,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(133844,48895,'Overlord IV','Overlord IV',replace('E-Rantel, the capital city of the newly established Sorcerer Kingdom, suffers from a dire shortage of goods. Once a prosperous city known for its trade, it now faces a crisis due to its caution—or even fear—of its king, Ainz Ooal Gown. To make amends, Ainz sends Albedo to the city as a diplomatic envoy.\n\n\n\nMeanwhile, the cardinals of the Slane Theocracy discuss how to retaliate against Ainz after his attack crippled the Re-Estize Kingdom''s army, plotting for the Baharuth Empire to take over the Sorcerer Kingdom. However, when Emperor Jircniv Rune Farlord El Nix arranges a meeting with the Theocracy''s messengers at a colosseum, he is confronted by none other than Ainz himself.\n\n\n\nWith their secret gathering now out in the open, the emperor and his guests learn that Ainz has challenged the Warrior King, the empire''s greatest fighter, to a duel. With Ainz''s motivations beyond his comprehension, Jircniv can do nothing but watch as humanity''s future changes before his very eyes.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8,'TV',2,0,'24 min','MADHOUSE','SUMMER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx133844-E32FjKZ0XxEs.jpg','["Action","Adventure","Fantasy"]',182927,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(133965,48926,'Komi-san wa, Komyushou desu.','Komi Can’t Communicate',replace('Timid Tadano is a total wallflower, and that’s just the way he likes it. But all that changes when he finds himself alone in a classroom on the first day of high school with the legendary Komi. He quickly realizes she isn’t aloof—she’s just super awkward. Now he’s made it his mission to help her on her quest to make 100 friends!\n\n\n\n(Source: VIZ Media)','\n',char(10)),7.6,'TV',2,0,'24 min','OLM','FALL 2021','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx133965-9TZBS4m4yvED.png','["Comedy","Romance","Slice of Life"]',328008,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(134107,48956,'Wu Shang Shen Di 2','无上神帝 第二季','The second season of Wu Shang Shen Di.',6.8,'ONA',1,0,'7 min','Ruo Hong Culture','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx134107-oJ9eQNwxM5fg.jpg','["Action","Adventure","Fantasy"]',917,1794782800,620,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(136430,49387,'VINLAND SAGA SEASON 2','Vinland Saga Season 2',replace('After his father''s death and the destruction of his village at the hands of English raiders, Einar wishes for a peaceful life with his family on their newly rebuilt farms. However, fate has other plans: his village is invaded once again. Einar watches helplessly as the marauding Danes burn his lands and slaughter his family. The invaders capture Einar and take him back to Denmark as a slave.\n\n\n\nEinar clings to his mother''s final words to survive. He is purchased by Ketil, a kind slave owner and landlord who promises that Einar can regain his freedom in return for working in the fields. Soon, Einar encounters his new partner in farm cultivation—Thorfinn, a dejected and melancholic slave. As Einar and Thorfinn work together toward their freedom, they are haunted by both sins of the past and the ploys of the present. Yet they carry on, grasping for a glimmer of hope, redemption, and peace in a world that is nothing but unjust and unforgiving.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.8,'TV',2,0,'26 min','MAPPA','WINTER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx136430-gsBsJjA7hGh9.jpg','["Action","Adventure","Drama"]',284021,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(136804,49458,'Kono Subarashii Sekai ni Shukufuku wo! 3','KONOSUBA -God''s blessing on this wonderful world! 3',replace('The dysfunctional party is back, but they may be short a member soon ’cause Kazuma is over it. Disillusioned with adventure, he wants to become a monk, but Aqua, Megumin, and Darkness call bull. However, the career dispute gets put on hold when a princess requests to hear all about their tales. Will the taste of fame at the royal castle keep them together or will this mark their farewell tour?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.2,'TV',2,0,'24 min','Drive','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx136804-7FVftG67FPBc.jpg','["Action","Adventure","Comedy","Ecchi","Fantasy"]',185232,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(136862,49448,'Ni Tian Zhizun','逆天至尊','The entire universe is divided into the inner universe and the outer universe. The two universes are enemies of each other. The outer universe is ruled by demons, and the inner universe is divided into The Realm of gods, the Eternal Realm, and the Mortal Realm. In the universe, there are countless mortal worlds like the Tianfa Continent, and they are collectively referred to as the Jiutian Xin Region. In the field of Jiutian Xin, nine immortal emperors commanded all star fields in nine layers. Above the nine heavens is the realm of purification of immortal gods.',6.6,'ONA',1,0,'12 min','Soyep','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx136862-s2HpY8Lg8qTS.jpg','["Action","Fantasy"]',1224,1794782800,580,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(137653,55809,'Xian Ni','Renegade Immortal',replace('It tells the story of Wang Lin, an ordinary young man in the countryside, who is moved by his heart and cultivates against immortality. His pursuit is not only for longevity, but also for getting rid of the ants behind it. He firmly believed in human beings and entered the path of cultivation with mediocre qualifications. After experiencing ups and downs, with his wise mind, he gradually reached the pinnacle and became famous in the cultivation world with his own strength.\n\n\n\n(Source: WeTV)','\n',char(10)),8.3,'ONA',1,1,'23 min','Build Dream','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx137653-1wHbCVvABGOr.png','["Action","Adventure","Drama","Fantasy"]',6757,1794782800,180,1794794400,167);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(137671,51289,'Zhe Tian','Shrouding the Heavens',replace('The story took the nine dragons and the coffin as an introduction and brought out a huge world of primeval ages. Climbing the sky road, and singing songs, to see how Ye Fan shrouding the heavens.\n\n\n\n(Source: Webnovel)','\n',char(10)),7.4,'ONA',1,0,'22 min','Original Force','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx137671-PzYKwpStSLIF.png','["Action","Adventure","Sci-Fi"]',2108,1794782800,208,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(137683,51836,'Douluo Dalu 2: Jueshi Tangmen','Soul Land 2: The Peerless Tang Clan',replace('The Tang Sect in a turbulent world. There is nothing but martial spirit here. Ten thousand years after the founding of the Tang Sect, it is in relative decline. An extremely talented man was born. Can the new Shrek Seven Monsters revive the Tang Sect and bring it back to glory? A soul beast of over one million years old; Electrolux who can pick stars; The new soul utensil system that led to the decline of the Tang Sect... A lot of secrets are to be revealed. Can the secret weapons of the Tang Sect be sharp again? Can the Tang Sect regain its former glory?\n\n(Source: WeTV)','\n',char(10)),7.7,'ONA',1,6,'20 min','Sparkly Key Animation','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx137683-IMuvIECdZNBh.png','["Action","Adventure","Fantasy","Romance"]',3138,1794782800,182,1795226400,180);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(137822,49596,'Blue Lock','BLUE LOCK',replace('Japan’s desire for World Cup glory leads the Japanese Football Association to launch a new rigorous training program to find the national team’s next striker. Three hundred high school players are pitted against each other for the position, but only one will come out on top. Who among them will be the striker to usher in a new era of Japanese soccer?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.9,'TV',2,0,'25 min','8-bit','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx137822-U8naszP96vzC.png','["Action","Drama","Sports"]',334920,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(138416,48824,'Blue Archive Anime PVs','ブルーアーカイブ アニメPVs',replace('Animated promotional videos for the smartphone game Blue Archive.\n\n\n\n1) アニメPV フルVer. (25 January 2021)\n\n2) 便利屋68 (11 May 2021)\n\n3) トリニティの夏、ゲヘナの夏。 (24 July 2021)\n\n4) 新春狂想曲第68番 (24 December 2021)\n\n5) 1st Anniversary Animation PV (25 November 2022)\n\n6) 白亜の予告状～虚飾の館と美学の在り処～ (22 April 2023)\n\n7) 夏の特殊作戦！ RABBIT小隊と消えたエビの謎 (17 June 2023)\n\n8) 簡体字中国語版 リリースPV (3 August 2023)\n\n9) 陽ひらく彼女たちの小夜曲 (21 January 2024)\n\n10) 簡体字中国語版 ハーフアニバーサリーPV (3 February 2024)\n\n11) Say-Bing! (23 June 2024)\n\n12) Sheside outside (21 July 2024)\n\n13) Serenade Promenade (20 October 2024)\n\n14) ハイランダー鉄道爆走事件 ～そして列車はなくなった～ (20 April 2025)\n\n15) ブルーアーカイブ「6th PV」(20 April 2025)\n\n16) 百ヨリ出ズル一輪ノ 〜いざ尋常に、水上勝負〜 (21 June 2025)\n\n17) 夏空のやくそく (19 July 2025)\n\n18) 魔法少女ヘヴィキャリバー～エラの野望と正義の資格～ (18 October 2025)\n\n19) Summer Sky''s Promise (30 November 2025)\n\n20) 5周年アニメPV (17 January 2026)\n\n21) ブルーアーカイブ「7th PV」 (19 April 2026)\n\n22) Ex.「ロア追跡」編 第1章「正午の陽炎」(19 April 2026)\n\n23) 嵐過天晴 (20 June 2026) \n\n24) 出航！万魔船　マコト議長の華麗なる避暑 (26 July 2026)','\n',char(10)),7,'SPECIAL',1,0,'1 min','Yostar Pictures','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx138416-Ez4Zd3nd3oz3.jpg','["Action","Fantasy"]',2365,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(138450,41880,'Crayon Shin-chan Specials','クレヨンしんちゃん スペシャル','',0,'SPECIAL',1,0,'47 min','Shin-Ei Animation','WINTER 1993','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b138450-3g1rSEYd3DQj.png','["Comedy","Ecchi","Slice of Life"]',331,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(139630,49918,'Boku no Hero Academia 6','My Hero Academia Season 6',replace('With Tomura Shigaraki at its helm, the former Liberation Army is now known as the Paranormal Liberation Front. This organized criminal group poses an immense threat to the Hero Association, not only because of its sheer size and strength, but also the overpowering quirks of Jin "Twice" Bubaigawara and Gigantomachia.\n\n\n\nAs new intel from the covert hero Keigo "Hawks" Takami confirms that Shigaraki is nowhere to be seen, the Hero Association decides to strike the enemy headquarters with a surprise attack using the entirety of its assets—and the UA students find themselves on the battlefield once again. As the fight rages on, the unsuspecting villains must regroup and push back, but the brave heroes are determined to eradicate every last one of them.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.2,'TV',2,0,'24 min','bones','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx139630-3v4gxWtNZxLV.jpg','["Action","Adventure"]',277823,1794735119,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(140439,50172,'Mob Psycho 100 III','Mob Psycho 100 III',replace('The appearance of a divine tree and new religion turns Mob and Reigen''s city upside down!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.7,'TV',2,0,'24 min','bones','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140439-bPKmhe1wNxc9.jpg','["Action","Comedy","Drama","Psychological","Slice of Life","Supernatural"]',271469,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(140842,50250,'Chiikawa','Chiikawa',replace('Meet Chiikawa and best friends Hachiware and Usagi as they navigate the ups and downs of everyday life in a world that''s cute, fantastical and full of surprises. Together they work hard, enjoy tasty treats, face unexpected challenges, and find joy in the little things.\n\n\n\n(Source: Chiikawa Official Youtube Channel)','\n',char(10)),8.5,'TV_SHORT',1,0,'2 min','Doga Kobo','SPRING 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140842-T0geOCa3zS0A.jpg','["Comedy","Slice of Life"]',12887,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(140960,50265,'SPY×FAMILY','SPY x FAMILY',replace('Everyone has a part of themselves they cannot show to anyone else.\n\n\n\nAt a time when all nations of the world were involved in a fierce war of information happening behind closed doors, Ostania and Westalis had been in a state of cold war against one another for decades. The Westalis Intelligence Services'' Eastern-Focused Division (WISE) sends their most talented spy, "Twilight," on a top-secret mission to investigate the movements of Donovan Desmond, the chairman of Ostania''s National Unity Party, who is threatening peace efforts between the two nations.\n\n\n\nThis mission is known as "Operation Strix." It consists of "putting together a family in one week in order to infiltrate social gatherings organized by the elite school that Desmond''s son attends." \n\n\n"Twilight" takes on the identity of psychiatrist Loid Forger and starts looking for family members. But Anya, the daughter he adopts, turns out to have the ability to read people''s minds, while his wife, Yor, is an assassin! With it being in each of their own interests to keep these facts hidden, they start living together while concealing their true identities from one another. \n\nWorld peace is now in the hands of this brand-new family as they embark on an adventure full of surprises.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.3,'TV',2,0,'24 min','CloverWorks','SPRING 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140960-Kb6R5nYQfjmP.jpg','["Action","Comedy","Slice of Life","Supernatural"]',583765,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(141014,50273,'Tomodachi Game','Tomodachi Game',replace('High school student Katagiri Yuuichi, who values friendship above all else, enjoys a fulfilling life with his close friends Sawagiri Shiho, Mikasa Tenji, Shibe Makoto, and Kokorogi Yutori.\n\n\n\nHowever, after a particular incident, they''re dragged into a debt repayment game.\n\n \n\nThe only way to beat the "Tomodachi Game" is to not doubt their friends. Bound together by solid friendships, the game should''ve been easy, but– The hugely popular comic that sold over two million copies is finally becoming an anime! Will they trust or betray their precious friends? The true nature of humanity is exposed in the ultimate psychological game!\n\n\n\n(Source: Crunchyroll)\n\n\n\nNote: Premiered on Hulu and d Anime Store at 0:00 on Wednesdays, 1 hour 29 minutes ahead of Nippon TV''s broadcast.','\n',char(10)),7.6,'ONA',2,0,'23 min','Okuruto Noboru','SPRING 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx141014-bTWr7TtS0wt9.jpg','["Drama","Mystery","Psychological","Thriller"]',171051,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(141391,50346,'Yofukashi no Uta','Call of the Night',replace('Wracked by insomnia and wanderlust, Kou Yamori is driven onto the moonlit streets every night in an aimless search for something he can’t seem to name. His nightly ritual is marked by purposeless introspection — until he meets Nazuna, who might just be a vampire! Kou’s new companion could offer him dark gifts and a vampire’s immortality. But there are conditions that must be met before Kou can sink his teeth into vampirism, and he’ll have to discover just how far he’s willing to go to satisfy his desires before he can heed the Call of the Night!\n\n\n\n(Source: Sentai Filmworks)','\n',char(10)),7.9,'TV',2,0,'23 min','LIDENFILMS','SUMMER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx141391-M3ZgUKTPENUk.jpg','["Comedy","Psychological","Romance","Slice of Life","Supernatural"]',291202,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(141949,50425,'Fuufu Ijou, Koibito Miman.','More than a Married Couple, but Not Lovers.',replace('Third-year high school student Jirou Yakuin hoped to partner with Shiori Sakurazaka of the same class in the mandatory "Couple Practical" course. In this practical, students must demonstrate that they have the necessary skillset to live with a partner of the opposite sex while presenting a certain level of harmony to the video surveillance that grades them.\n\n\n\nUnfortunately, random chance put his slightly subdued self into the practical with the person polar opposite to him, the gyaru Akari Watanabe. Akari on the other hand hoped to be paired with her crush Minami Tenjin.\n\n\n\nTheir hopes are doubly dashed when they find out that Shiori and Minami are assigned together. Thus, they reluctantly decide to cooperate to reach the top ten, which would give them the right to exchange partners if both couples agree. To that end, Jirou steals Akari''s first kiss without realizing what he''d done, while giving a hurried good-bye kiss...','\n',char(10)),7.6,'TV',2,0,'24 min','studio MOTHER','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx141949-tViCIRHPZAyG.jpg','["Comedy","Drama","Ecchi","Romance"]',173189,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(142274,50418,'Ninjala','Ninjala the Animation',replace('The year is 20XX. The ninja, who once forged the history of Japan, were scattered across the country during the Meiji Restoration. As these ninja mingled with the other clans, their bloodline thinned, and they gradually faded from sight. The descendants of these ninja clans, seeking to preserve their heritage, formed the WNA (World Ninja Association) in the hope of carrying on their legacy.\n\n\n\nAnd so it was that the WNA succeeded in developing Ninja-Gum, an art which could summon forth the strength of the Shinobi. And yet creating the most powerful Ninja-Gum requires the strongest of ninja DNA. So it was that the Ninjala Tournament was held, that the mightiest of all ninjas could be found...\n\n\n\n(Source: Official Game website)','\n',char(10)),4.9,'TV',1,0,'23 min','OLM','WINTER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx142274-qPfkeKk4caKI.png','["Action","Comedy","Sci-Fi"]',1431,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(142329,47778,'Kimetsu no Yaiba: Yuukaku-hen','Demon Slayer: Kimetsu no Yaiba Entertainment District Arc',replace('After visiting the Rengoku residence, Tanjirou and his comrades volunteer for a mission within the Entertainment District, a place where desires are sold and demons dwell. They journey alongside the flashy Sound Hashira, Tengen Uzui, in search of a monstrous foe terrorizing the town. Sworn to slay creatures of the night, the hunt continues.\n\n\n\n(Source: Funimation)\n\n\n\nNote:\n\n- The first episode aired with a runtime of ~47 minutes.\n\n- The last episode aired with a runtime of ~33 minutes.','\n',char(10)),8.5,'TV',2,0,'24 min','ufotable','WINTER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx142329-kET1PIXJv2eW.jpg','["Action","Adventure","Fantasy","Supernatural"]',496129,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(142770,50594,'Suzume no Tojimari','Suzume',replace('The story follows Suzume, a 17-year-old girl from a quiet Kyushu town who meets a young man looking for a door. They find a door within ruins in the mountain, and Suzume opens it. Soon, more doors begin to open around Japan, bringing disasters from the other side. The film depicts Suzume''s liberation and growth, as she closes the doors that are causing disaster.\n\n\n\n(Source: Anime News Network)','\n',char(10)),8.1,'MOVIE',2,0,'121 min','CoMix Wave','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx142770-dDaDIRnsv5jN.jpg','["Adventure","Fantasy","Mystery","Supernatural"]',207105,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(142838,50602,'SPY×FAMILY Part 2','SPY x FAMILY Cour 2',replace('With Anya Forger successfully enrolled at the renowned Eden Academy, Operation Strix advances to its second phase. To investigate Ostanian politician Donovan Desmond, Anya must either befriend his son Damian or collect eight Stella Stars to become an Imperial Scholar. Fortunately, Anya has already acquired her first star. In celebration, her adoptive father, Loid, decides to fulfill her wish to adopt a dog.\n\n\n\nDuring their canine search, Loid receives new orders from his superiors, who have found that a band of Berlint University students is plotting to assassinate Westalis'' Minister Brantz using bombs worn by trained dogs. While Loid tries to stop their plans, Anya stumbles upon the terrorists'' base of operations. There, she befriends a kindhearted, clairvoyant dog who the family later names Bond.\n\n\n\nAlthough the Forgers continue to lead their individual lives in secrecy, the family—with a new fluffy addition—remains united through all of the unusual obstacles thrown their way.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.1,'TV',2,0,'24 min','WIT STUDIO','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx142838-26JrqcFU1ljB.jpg','["Action","Comedy","Slice of Life","Supernatural"]',336001,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(142984,50631,'Komi-san wa, Komyushou desu. 2','Komi Can''t Communicate Part 2',replace('Komi and pals are back! Who else will Komi make friends with? How will her relationship with Tadano evolve? \n\n\n\n(Source: Netflix)','\n',char(10)),7.8,'TV',2,0,'24 min','OLM','SPRING 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx142984-nv2MWVWZ1yYH.jpg','["Comedy","Romance","Slice of Life"]',171363,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(143270,50709,'Lycoris Recoil','Lycoris Recoil',replace('“LycoReco” is a café with a traditional Japanese twist located in downtown Tokyo. But the delicious coffee and sugary sweets are not the only orders this café takes! From delivering packages short distances, to pick-ups and drop-offs on the lonely streets at night, to zombies and giant monster extermination…?! Whatever your problem, we''re here to help! We will solve any kind of "trouble" you may have!\n\n\n\nWaiting for you are the ever-smiling poster-girl and the cool, serious newcomer. A petite girl who never wants to work and a young woman approaching thirty who wants to get married. And the manager is a nice guy who’s obsessed with Japan!\n\n\n\nWhatever your order is, leave it all up to us♪\n\n\n\n(Source: Official Site)','\n',char(10)),8.1,'TV',2,0,'24 min','A-1 Pictures','SUMMER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx143270-rfkyiYXhek5w.jpg','["Action","Slice of Life"]',215699,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(143338,50739,'Otonari no Tenshi-sama ni Itsunomanika Dame Ningen ni Sareteita Ken','The Angel Next Door Spoils Me Rotten',replace('Amane lives alone in an apartment, and the most beautiful girl in school, Mahiru, lives just next door. They''ve almost never spoken&mdash;until the day he sees her in distress on a rainy day and lends her his umbrella. To return the favor, she offers him help around the house, and a relationship slowly begins to blossom as the distance between them closes...\n\n\n\n(Source: Yen Press)','\n',char(10)),7.8,'TV',2,0,'24 min','project No.9','WINTER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx143338-zhyDVYgEzsm5.png','["Romance","Slice of Life"]',180751,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(145064,51009,'Jujutsu Kaisen 2nd Season','JUJUTSU KAISEN Season 2',replace('The past comes to light when second-year students Satoru Gojou and Suguru Getou are tasked with escorting young Riko Amanai to Master Tengen. But when a non-sorcerer user tries to kill them, their mission to protect the Star Plasma Vessel threatens to turn them into bitter enemies and cement their destinies—one as the world’s strongest sorcerer, and the other its most twisted curse user!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.6,'TV',2,0,'24 min','MAPPA','SUMMER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx145064-hSNRJM03pvv1.jpg','["Action","Drama","Supernatural"]',507541,1794735119,23,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(145139,51019,'Kimetsu no Yaiba: Katanakaji no Sato-hen','Demon Slayer: Kimetsu no Yaiba Swordsmith Village Arc',replace('Tanjiro’s journey leads him to the Swordsmith Village, where he reunites with two Hashira, members of the Demon Slayer Corps’ highest-ranking swordsmen - Mist Hashira Muichiro Tokito and Love Hashira Mitsuri Kanroji. With the shadows of demons lurking near, a new battle begins for Tanjiro and his comrades.\n\n\n\nNotes:\n\n• The first episode has a runtime of ~49 minutes, and received an early premiere in cinemas worldwide as part of a special screening alongside the final two episodes of Kimetsu no Yaiba: Yuukaku-hen.\n\n• The final episode has a runtime of ~52 minutes.','\n',char(10)),8,'TV',2,0,'24 min','ufotable','SPRING 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx145139-rRimpHGWLhym.png','["Action","Adventure","Drama","Fantasy","Supernatural"]',383773,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(145545,51096,'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 2nd Season','Classroom of the Elite Season 2',replace('Tokyo Metropolitan Advanced Nurturing High School seems like a paradise, but in reality, it is an extreme meritocracy. In the class of underachievers, Kiyotaka has begun working with Suzune, who seeks to ascend higher. After a survival test on an uninhabited island, they get to enjoy a luxury liner, but a new class-scrambling test will begin.\n\n\n\n(Source: Anime News Network)','\n',char(10)),7.8,'TV',2,0,'24 min','Lerche','SUMMER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx145545-DGl3LVvFlnHi.png','["Drama","Mystery","Psychological"]',268557,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(146004,51768,'Girigiri Warukunai Watame','Watame Did Borderline Nothing Wrong',replace('A series of comedic YouTube shorts airing every Friday on Watame''s YouTube channel.\n\n\nNotes:\n\n- Episodes 1-21 (Series 1) were originally released in a vertical format, later rereleased widescreen in 8 compilation videos.\n\n- Contains special episode "Best Girl？！スペシャル回！！！"','\n',char(10)),7,'ONA',1,5,'1 min','-','WINTER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx146004-hH08KAB1yHlN.png','["Comedy","Slice of Life"]',1321,1794782800,0,1795168800,89);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(146065,51179,'Mushoku Tensei II: Isekai Ittara Honki Dasu','Mushoku Tensei: Jobless Reincarnation Season 2',replace('After his relationship with Eris Boreas Greyrat reaches new heights, Rudeus Greyrat is ecstatic. Unfortunately, his joy is short-lived, as Eris suddenly abandons him to embark on her own journey. Believing that Eris has lost all interest in him, a heartbroken and depressed Rudeus sets forth to the Northern Territories. With his sole goal being to locate his mother on the vast continent, Rudeus wonders if persisting through daily life is worth the pain, falling into a robotic routine as he endlessly ruminates on his lost love.\n\n\n\nHowever, the dangers of the North soon prove that one cannot survive with a dulled mind. While on a quest with the party Counter Arrow, with whom he recently became acquainted, Rudeus has a brush with death—an experience that forces him to finally snap out of his despair. With his newfound teammates, Rudeus rediscovers the pleasure of daily adventuring and moves forward with his original goal of living his second lease on life to the fullest.\n\n\n\n(Source: MAL Rewrite)\n\n\n\nNote: Includes episode 0, Shugo Jutsushi Fitz.','\n',char(10)),8.1,'TV',2,0,'24 min','Studio Bind','SUMMER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx146065-IjirxRK26O03.png','["Adventure","Drama","Ecchi","Fantasy"]',274139,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(146066,51180,'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 3rd Season','Classroom of the Elite Season 3',replace('The third semester kicks off in high gear with a special boot camp deep in the mountains. Forcibly separated into groups along grade and gender lines, the first, second and third years alike must work together to survive the rugged terrain. Even worse? The leader of the group that comes in last will be expelled. Can Class D make it back to campus intact, or is this where they finally say goodbye to one of their own?\n\n\n\n(Source: Seven Seas Entertainment)','\n',char(10)),7.8,'TV',2,0,'24 min','Lerche','WINTER 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx146066-zzKl6P6OeEjy.jpg','["Drama","Psychological"]',194958,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(146984,51535,'Shingeki no Kyojin: The Final Season - Kanketsu-hen Zenpen','Attack on Titan Final Season THE FINAL CHAPTERS Special 1',replace('The fate of the world hangs in the balance as Eren unleashes the ultimate power of the Titans. With a burning determination to eliminate all who threaten Eldia, he leads an unstoppable army of Colossal Titans towards Marley. Now a motley crew of his former comrades and enemies scramble to halt his deadly mission, the only question is, can they stop him?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.7,'SPECIAL',2,0,'61 min','MAPPA','WINTER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx146984-GXrLeT6vQqyP.jpg','["Action","Drama","Fantasy","Mystery","Psychological"]',258199,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(147105,51553,'Tongari Boushi no Atelier','Witch Hat Atelier',replace('In a world where everyone takes wonders like magic spells and dragons for granted, Coco is a girl with a simple dream: she wants to be a witch. But everybody knows magicians are born, not made, and Coco was not born with a gift for magic. Resigned to her un-magical life, Coco is about to give up on her dream to become a witch … until the day she meets Qifrey, a mysterious, traveling magician. After secretly seeing Qifrey perform magic in a way she’s never seen before, Coco soon learns what everybody “knows” might not be the truth, and discovers that her magical dream may not be as far away as it may seem... \n\n\n\n(Source: Kodansha USA) \n\n\n\nNote: Tongari Boushi no Atelier episode 2 was streamed a week in advance on Crunchyroll, ABEMA, and Netflix, alongside episode 1. Streaming is one week ahead of the TV broadcast.','\n',char(10)),8.5,'ONA',2,0,'24 min','BUG FILMS','SPRING 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx147105-rwOX8qyUy8gV.jpg','["Adventure","Drama","Fantasy"]',239605,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(150672,52034,'[Oshi no Ko]','OSHI NO KO',replace('When a pregnant young starlet appears in Gorou Amemiya’s countryside medical clinic, the doctor takes it upon himself to safely (and secretly) deliver Ai Hoshino’s child so she can make a scandal-free return to the stage. But no good deed goes unpunished, and on the eve of her delivery, he finds himself slain at the hands of Ai’s deluded stalker — and subsequently reborn as Ai’s child, Aquamarine Hoshino! The glitz and glamor of showbiz hide the dark underbelly of the entertainment industry, threatening to dull the shine of his favorite star. Can he help his new mother rise to the top of the charts? And what will he do when unthinkable disaster strikes? \n\n\n\n(Source: HIDIVE)\n\n\n\n\nNote: Episode 1【推しの子】Mother and Children was pre-screened in advance in Japanese theaters on March 17, 2023. The regular TV broadcast began on April 12, 2023. The first episode has an extended runtime of ~82 minutes.','\n',char(10)),8.4,'TV',2,0,'24 min','Doga Kobo','SPRING 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx150672-WqmmwZ4nMzAy.png','["Drama","Mystery","Psychological","Supernatural"]',338194,1794735119,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(151801,52211,'MASHLE','MASHLE: MAGIC AND MUSCLES',replace('This is a world of magic. This is a world in which magic is casually used by everyone.\n\n\nIn a deep, dark forest in this world of magic, there is a boy who is singlemindedly working out. His name is Mash Burnedead, and he has a secret. He can’t use magic. \n\n\nAll he wanted was to live a quiet life with his family, but people suddenly start trying to kill him one day and he somehow finds himself enrolled in Magic School. There, he sets his sights on becoming a “Divine Visionary,” the elite of the elite. \n\n Will his ripped muscles work against the best and brightest of the wizarding world? The curtain rises on this off-kilter magical fantasy in which the power of being jacked crushes any spell!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.6,'TV',2,0,'24 min','A-1 Pictures','SPRING 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx151801-XxVf22Le6C8o.png','["Action","Comedy","Fantasy"]',298671,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(151806,52305,'Tomo-chan wa Onnanoko!','Tomo-chan Is a Girl!',replace('Tomboy Tomo couldn’t have picked a more awkward high school crush ’cause it’s on her childhood friend, Junichiro, but he only sees her as one of the guys. Despite her pretty looks and signals, nothing gets through to this meathead! Will Junichiro ever realize Tomo’s into him and see her for the cutesy girl she actually is?!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.6,'TV',2,0,'24 min','Lay-duce','WINTER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx151806-IAMi2ctI5xJI.jpg','["Comedy","Romance","Slice of Life"]',182252,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(151807,52299,'Ore dake Level Up na Ken','Solo Leveling',replace('They say whatever doesn’t kill you makes you stronger, but that’s not the case for the world’s weakest hunter Seong Jin-U. After being brutally slaughtered by monsters in a high-ranking dungeon, Jin-U came back with the System, a program only he could see, that’s leveling him up in every way. Now, he’s inspired to discover the secrets behind his powers and the dungeon that spawned them.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8,'TV',2,0,'24 min','A-1 Pictures','WINTER 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx151807-it355ZgzquUd.png','["Action","Adventure","Fantasy"]',463005,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(151970,52347,'Shangri-La Frontier','Shangri-La Frontier',replace('"When was the last time I played a game that wasn''t crap?" This is a world in the near future where games that use display screens are classified as retro. Anything that can''t keep up with state-of-the-art VR technology is called a "crap game," and you see a large number of crap games coming out. Those who devote their lives to clearing these games are called "crap-game hunters," and Rakuro Hizutome is one of them. The game he''s chosen to tackle next is Shangri-La Frontier, a "god-tier game" that has a total of thirty million players. Online friends... An expansive world... Encounters with rivals... These are changing Rakuro and all the other players'' fates! The best game adventure tale by the strongest "crap game" player begins now!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8,'TV',2,0,'26 min','C2C','FALL 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx151970-xtIx3VqEk02X.jpg','["Action","Adventure","Comedy","Fantasy","Sci-Fi"]',197567,1794735120,25,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(152677,52480,'Tantei wa mou, Shindeiru. Season 2','The Detective Is Already Dead Season 2',replace('After thwarting a hijacking with beautiful, silver-haired detective Siesta, Kimihiko leads a life of globe-trotting and crime-solving—until Siesta dies. A year later, a new case will open old wounds as it threads murder, conspiracy, and his dead partner!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7,'TV',1,3,'24 min','ENGI','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx152677-gtJbgjE94lCN.png','["Comedy","Drama","Mystery","Romance","Supernatural"]',27227,1794782800,13,1795005000,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(153288,52588,'Kaijuu 8-gou','Kaiju No. 8',replace('With the highest kaiju-emergence rates in the world, Japan is no stranger to attack by deadly monsters. Enter the Japan Defense Force, a military organization tasked with the neutralization of kaiju. Kafka Hibino, a kaiju-corpse cleanup man, has always dreamed of joining the force. But when he gets another shot at achieving his childhood dream, he undergoes an unexpected transformation. How can he fight kaiju now that he’s become one himself?!\n\n\n\n(Source: VIZ Media)','\n',char(10)),8.1,'TV',2,0,'24 min','Production I.G','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx153288-25FBfFJzEQ5O.jpg','["Action","Sci-Fi"]',292403,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(153518,52701,'Dungeon Meshi','Delicious in Dungeon',replace('When young adventurer Laios and his company are attacked and soundly thrashed by a dragon deep in a dungeon, the party loses all its money and provisions...and a member! They''re eager to go back and save her, but there is just one problem: If they set out with no food or coin to speak of, they''re sure to starve on the way! But Laios comes up with a brilliant idea: "Let''s eat the monsters!" Slimes, basilisks, and even dragons...none are safe from the appetites of these dungeon-crawling gourmands! \n\n\n\n(Source: Yen Press)\n\n\n\nNote: A world premiere screening of Episode 1 was shown in the Studio TRIGGER panel at Anime Expo on July 1, 2023.','\n',char(10)),8.5,'TV',2,0,'25 min','TRIGGER','WINTER 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx153518-IVXPDY5ph3kO.jpg','["Adventure","Comedy","Fantasy"]',233408,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(154587,52991,'Sousou no Frieren','Frieren: Beyond Journey’s End',replace('The adventure is over but life goes on for an elf mage just beginning to learn what living is all about. Elf mage Frieren and her courageous fellow adventurers have defeated the Demon King and brought peace to the land. But Frieren will long outlive the rest of her former party. How will she come to understand what life means to the people around her? Decades after their victory, the funeral of one her friends confronts Frieren with her own near immortality. Frieren sets out to fulfill the last wishes of her comrades and finds herself beginning a new adventure…\n\n\n\n(Source: Crunchyroll)','\n',char(10)),9,'TV',2,0,'24 min','MADHOUSE','FALL 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx154587-qQTzQnEJJ3oB.jpg','["Adventure","Drama","Fantasy"]',499125,1794735119,28,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(154768,53065,'Sono Bisque Doll wa Koi wo Suru Season 2','My Dress-Up Darling Season 2',replace('When Marin Kitagawa and Wakana Gojo met, they grew close over their love for cosplay. Through interacting with classmates and making new cosplay friends, Marin and Wakana’s world keeps growing. New developments arise as Marin’s love for Wakana continues to be filled with endless excitement. In their ever-expanding world, Marin and Wakana’s story of cosplay and thrills continues!\n\n\n(Source: Crunchyroll)','\n',char(10)),8.2,'TV',2,0,'24 min','CloverWorks','SUMMER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx154768-DHHvNd4MjV1p.jpg','["Comedy","Ecchi","Romance","Slice of Life"]',201066,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(154965,53126,'Yamada-kun to Lv999 no Koi wo Suru','My Love Story with Yamada-kun at Lv999',replace('Akane Kinoshita, a female college student, faces the absolute worst situation when she ends up breaking up with her boyfriend after he has an affair with a woman he met playing an online game. While relieving her stress by rampaging through the open hunting grounds of an online game, Akane spills everything about her heartbreak to “Yamada”, a player she met by chance who happens to be in the same guild. “I don''t care,” is his curt reply. But when Akane gets a makeover and joins an offline event to get back at her ex-boyfriend, she hears those dreadful words again. And that was Akane''s fateful encounter with “Yamada”─！\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.7,'TV',2,0,'24 min','MADHOUSE','SPRING 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx154965-vZbBRjtmLp7S.jpg','["Comedy","Drama","Romance"]',213259,1794735120,13,0,0);
