INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(155783,53393,'Tengoku Daimakyou','Tengoku Daimakyo',replace('In the year 2024, the world has collapsed. Grotesque monsters lurk amongst the ruins of Japan, while remaining people scrape together what they can to survive. Kiruko, an odd-job girl in Nakano, accepts a mysterious woman''s dying wish to take a boy named Maru to a place called Heaven.\n\n\n\n(Source: Disney+, edited)','\n',char(10)),8.1,'TV',2,0,'24 min','Production I.G','SPRING 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx155783-YosKbsmZzuDE.jpg','["Adventure","Mystery","Sci-Fi","Thriller"]',218114,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(156822,53580,'Tensei Shitara Slime Datta Ken 3rd Season','That Time I Got Reincarnated as a Slime Season 3',replace('Rimuru has officially become a Demon Lord after defeating Clayman. Following Walpurgis, the Demon Lords'' banquet, Rimuru''s domain is expanded to include the entire Great Forest of Jura. Anticipating a flood of representatives from all races showing up to pay their respects, Rimuru decides to throw a festival to commemorate the opening of Tempest, using it as an opportunity to gain new citizens and present Demon Lord Rimuru to the world. Meanwhile, in the Holy Empire of Lubelius, home base of the monster-hating cult of Luminism, Holy Knight Captain Hinata receives a message from Rimuru. But the message is actually a fabricated declaration of war sent by some unknown party. Upon learning that Hinata is heading for Tempest, Rimuru makes a decision... Thus begins a new challenge for Rimuru, striving to distinguish friend from foe in his pursuit of the ideal nation where humans and monsters can prosper together. \n\n\n(Source: Crunchyroll)','\n',char(10)),7.8,'TV',2,0,'24 min','8-bit','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx156822-Jzo2ITWgm4kM.jpg','["Action","Adventure","Comedy","Fantasy"]',195516,1794735120,24,0,0);
