INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(159454,53907,'Tom to Jerry Gokko','Tom and Jerry Gokko',replace('To celebrate "Cheese Day," (November 11 in Japan), Cartoon Network Japan debuted an anime spin on Tom and Jerry that combines the fast-paced humor of the original with a cute, "pop" worldview. The pair are joined by the diaper-wearing Tuffy Mouse, another recurring character from the classic cartoon.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.3,'TV_SHORT',1,0,'1 min','Fanworks','FALL 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx159454-I5i5E5kXDsEY.png','["Comedy"]',1062,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(159831,54112,'Zom 100: Zombie ni Naru Made ni Shitai 100 no Koto','Zom 100: Bucket List of the Dead',replace('Surviving a zombie apocalypse beats being a wage slave any day! After spending years slaving away for a soul-crushing company, Akira''s life has lost its luster. He lives in a trash-filled apartment, his pay is abysmal, and he can''t even muster up the nerve to confess his love to his beautiful co-worker. But when a zombie apocalypse ravages his town, it gives him the push he needs to live for himself. Now Akira''s on a mission to complete all 100 items on his bucket list before he...well, kicks the bucket.\n\n\n\n(Source: VIZ Media)','\n',char(10)),7.6,'TV',2,0,'24 min','BUG FILMS','SUMMER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx159831-cJUNqCqzuApc.png','["Action","Adventure","Comedy","Horror","Supernatural"]',247846,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(160803,54344,'Mahou Shoujo Ikusei Keikaku: restart','MAGICAL GIRL RAISING PROJECT restart',replace('Some magical girls fight. Others do not. Chosen by the mysterious Land of Magic, which exists unbeknownst to the rest of the world, magical girls are each granted a unique power. Pechka, whose magic makes food delicious, is forced to take part in a mysterious virtual game together with 16 unfamiliar magical girls, each with her own distinctive personality. It was supposed to be a safe training exercise designed to improve their magical abilities. But instead, it marks the beginning of a carefully orchestrated nightmare - a forbidden trial. A new Magical Girl Raising Project has begun.\n\n\n\n(Source: OceanVeil)','\n',char(10)),6.1,'TV',1,2,'24 min','SynergySP','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx160803-Rcr3IvhE7q9c.png','["Action","Fantasy","Mahou Shoujo","Thriller"]',7817,1794782800,0,1794848400,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(161645,54492,'Kusuriya no Hitorigoto','The Apothecary Diaries',replace('Maomao lived a peaceful life with her apothecary father. Until one day, she’s sold as a lowly servant to the emperor’s palace. But she wasn’t meant for a compliant life among royalty. So when imperial heirs fall ill, she decides to step in and find a cure! This catches the eye of Jinshi, a handsome palace official who promotes her. Now, she’s making a name for herself solving medical mysteries!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.8,'TV',2,0,'23 min','OLM','FALL 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx161645-QLbzHXiYRgV2.jpg','["Drama","Mystery"]',344828,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(161964,54595,'Kage no Jitsuryokusha ni Naritakute! 2nd season','The Eminence in Shadow Season 2',replace('Everything has been going according to plan, but the hour of awakening draws near. Cid Kagenou and Shadow Garden investigate the Lawless City, a cesspool where the red moon hangs low in the sky and three powerful monarchs rule the streets. The true draw for Cid, however, is one who can draw blood–the Blood Queen, a vampire who has slumbered in her coffin for eons. Her awakening approaches, and Cid could finally face a day of reckoning. \n\n\n\n(Source: HIDIVE, edited)\n\n\n\nNote: A world premiere screening of Episode 1 was shown in the The Eminence in Shadow 2nd Season panel at Anime Expo on July 1, 2023.','\n',char(10)),8.2,'TV',2,0,'24 min','Nexus','FALL 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx161964-JpkEbHI8ivaP.jpg','["Action","Comedy","Fantasy"]',202496,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(162314,NULL,'Shingeki no Kyojin: The Final Season - Kanketsu-hen Kouhen','Attack on Titan Final Season THE FINAL CHAPTERS Special 2',replace('Eren, as the Founding Titan, advances on Fort Salta with countless other Titans. Appearing before the refugees, who stand on the brink of despair, are Mikasa, Armin, Jean, Conny, Reiner, Pieck, and Levi, who narrowly escaped from the rumbling. The battle between former comrades and childhood friends with Eren concludes here.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.7,'SPECIAL',2,0,'85 min','MAPPA','FALL 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx162314-qIWdAAFtvY8J.jpg','["Action","Drama","Fantasy","Psychological","Romance"]',172610,1794735120,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(162804,54744,'Tokidoki Bosotto Rossiya-go de Dereru Tonari no Alya-san','Alya Sometimes Hides Her Feelings in Russian',replace('Alya is a transfer student enjoying popularity at her new high school, often sporting a cold shoulder while earning high marks in class. She ignores her nerdy classmate, Kuze Masachika, except for when she blurts out a flirtatious line to him in Russian. Little does she know, Kuze understands Russian, though he pretends not to. Let’s see where this wacky love story takes them!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.5,'TV',2,0,'25 min','Doga Kobo','SUMMER 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx162804-TBeptcAfvqTd.jpg','["Comedy","Romance","Slice of Life"]',214514,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(163132,54856,'Horimiya: piece','Horimiya: The Missing Pieces',replace('As the graduation ceremony at Katagiri High School comes to an end, Kyouko Hori, her boyfriend Izumi Miyamura, and their friends begin to look back on their time as students. The moments they shared together may be fleeting, but each one is a colorful piece of their precious memories.\n\n\n\n(Source: MAL Rewrite)\n\n\n\nNote: New anime project adapting popular side stories that were left out from the previous adaptation.','\n',char(10)),8.1,'TV',2,0,'24 min','CloverWorks','SUMMER 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx163132-C220CO5UrTxY.jpg','["Comedy","Romance","Slice of Life"]',169973,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(163134,54857,'Re:Zero kara Hajimeru Isekai Seikatsu 3rd Season','Re:ZERO -Starting Life in Another World- Season 3',replace('A year has passed since Subaru’s victory at the Sanctuary. He savors a life of fulfillment while Emilia’s camp stands united for the royal selection—until a fateful letter arrives. Anastasia, a royal selection candidate, has invited Emilia to the Watergate City of Priestella. But as the party begins its journey, crisis stirs beneath the surface and Subaru meets a cruel fate once again.\n\n\n(Source: Crunchyroll) \n\n\n\nNote: The first episode has an extended runtime of ~90 minutes, and received an early premiere at Anime Expo on July 5, 2024.','\n',char(10)),8.4,'TV',2,0,'24 min','WHITE FOX','FALL 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx163134-yieRFbvUOH9a.jpg','["Action","Adventure","Drama","Fantasy","Psychological","Romance","Thriller"]',206048,1794735120,16,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(163139,54789,'Boku no Hero Academia 7','My Hero Academia Season 7',replace('Following an all-out battle with the Paranormal Liberation Front, it is difficult for the people of Japan to continue placing faith in their heroes. To combat the combined power of Tomura Shigaraki and All For One, All Might calls for his ally from the West—the strongest woman on the planet, Star and Stripe.\n\n\n\nHowever, All For One decides to intercept Star and her fleet to get his hands on her overpowered quirk before she can enter Japanese airspace. Although Endeavor, Hawks, and Best Jeanist are headed to the rendezvous point, Star makes a gamble in the present to save her comrades.\n\n\n\n(Source: MAL Rewrite)\n\n\n\nNote: The season was preceded by a 4-episode special titled ''Boku no Hero Academia: Memories'' recapping events from the 6th season along with adding a few minutes of new material each episode.','\n',char(10)),8.2,'TV',2,0,'24 min','bones','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx163139-JchZhUFlNTWU.jpg','["Action","Adventure"]',192041,1794735120,21,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(163270,54900,'WIND BREAKER','WIND BREAKER',replace('Where the average scores are the lowest, but the fights are the strongest. Furin High School is renowned as a super school of delinquents. Haruka Sakura, a first-year student, came from outside the city to fight to the top. However, Furin High School has become a group that protects the town called the “Chime of the Wind Breaker” – Bofurin. The heroic legend of high school delinquent Sakura begins here!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.7,'TV',2,0,'24 min','CloverWorks','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx163270-wboZJp0ybwVK.jpg','["Action","Comedy","Drama"]',197352,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(165159,56566,'BEYBLADE X','BEYBLADE X',replace('Bird Kazami, aiming to become a pro Blader, meets former champion Ekusu Kurosu, also known as ''Kamen X'', and forms a team so that they can aim for the "top" of the X Tower. But what awaits them is a spectacular battle that no one has ever seen before. The yet unseen ''X''. The super accelerated (Xtreme) Beyblade runs through a new era!\n\n\n\n(Source: Official website)','\n',char(10)),6.5,'TV',1,5,'22 min','OLM','FALL 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx165159-aCFC9Sng7t4M.png','["Action","Adventure","Sports"]',4968,1794782800,0,1795168800,141);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(165524,54437,'Lian Qi Shiwan Nian','炼气十万年','One hundred thousand years ago, he was the founding disciple of the Tianlan Sect, his master ascended to the top, and he was refining Qi. Ninety thousand years ago, his martial nephew ascended, and he was refining Qi. Fifty thousand years ago, the old dog who was the gatekeeper of Tianlanzong also ascended, and he was still refining Qi. Thirty thousand years ago, the old tree at the foot of the mountain also became a demon, and he was still refining Qi before he could pass the catastrophe. Ten thousand years ago, Zhang Wuji, the 9872nd generation disciple of Tianlanzong, also ascended, and Xu Yang silently refined Qi. He retreated for 10,000 years, and finally, he broke through the 9999th floor of the Qi refining period! Ten thousand years later, he broke through and came out!',6.6,'ONA',1,0,'10 min','Soyep','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b165524-XMXXm35IgGAB.jpg','["Action","Adventure","Fantasy"]',1173,1794782800,420,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(166219,56524,'Tunshi Xingkong 4','吞噬星空 第四季',replace('The fourth season of Tunshi Xingkong.\n\n\n\nNote: Episodes 86 to 260.','\n',char(10)),8.2,'ONA',1,0,'21 min','Sparkly Key Animation','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166219-tREIb5l5huVe.png','["Action","Sci-Fi"]',2038,1794782800,175,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(166240,55701,'Kimetsu no Yaiba: Hashira Geiko-hen','Demon Slayer: Kimetsu no Yaiba Hashira Training Arc',replace('The Hashira, the Demon Slayer Corps'' highest ranking swordsmen and members. The Hashira Training has begun in order to face the forthcoming battle against Muzan Kibutsuji. Each with their own thoughts and hopes held in their hearts, a new story for Tanjiro and the Hashira begins.\n\n\n(Source: Aniplex USA)\n\n\nNote: The first episode received an early premiere in cinemas as part of a special screening alongside the final episode of Kimetsu no Yaiba: Katanakaji no Sato-hen.','\n',char(10)),7.9,'TV',2,0,'30 min','ufotable','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166240-PBV7zukIHW7V.png','["Action","Adventure","Drama","Fantasy","Supernatural"]',287389,1794735119,8,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(166531,55791,'[Oshi no Ko] 2nd Season','OSHI NO KO Season 2',replace('Aqua’s desire for revenge takes center stage as he navigates the dark underbelly of the entertainment world alongside his twin sister, Ruby. While Ruby follows in their slain mother’s footsteps to become an idol, Aqua joins a famous theater troupe in hopes of uncovering clues to the identity of his father — the man who arranged their mother’s untimely death, and the man who once starred in the same troupe Aqua hopes to infiltrate.\n\n\n\n(Source: HIDIVE)','\n',char(10)),8.5,'TV',2,0,'24 min','Doga Kobo','SUMMER 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166531-dAL5MsqDHUkj.jpg','["Drama","Mystery","Psychological","Supernatural"]',183863,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(166610,55813,'MASHLE: Kami Shinkakusha Kouho Senbatsu Shiken-hen','MASHLE: MAGIC AND MUSCLES Season 2',replace('After Mash Burnedead''s clash with Magia Lupus, the secret about his powers is now out in the open. The short-lived celebration ends when the Bureau of Magic summons Mash before an audience of Divine Visionaries, who collectively decree Mash should reap the consequences and die. However, an evil shadow organization called Innocent Zero hijacks the inquiry to demand that Mash be kept alive.\n\n\n\nMash proves that he is capable of dealing with Innocent Zero, but the Divine Visionaries'' verdict remains unchanged. Luckily, Mash finds unexpected allies in Divine Visionary Rayne Ames and Headmaster Wahlberg Baigan, and they successfully defer his execution until Innocent Zero is defeated. Mash is now allowed to live under one condition: he must be selected as the Divine Visionary candidate by the year''s end.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),7.8,'TV',2,0,'24 min','A-1 Pictures','WINTER 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166610-S5q7V2v5zdDK.jpg','["Action","Comedy","Fantasy"]',188668,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(166613,55825,'Jigokuraku 2nd Season','Hell’s Paradise Season 2',replace('Seeking the key to the elixir of immortality, the group arrives at the fortress of the island''s monstrous ruler, the "Tensen." To survive and escape the island, cooperation becomes essential—regardless of whether one is a condemned criminal or an executioner.\n\n\n\nMeanwhile, the shogunate orders additional landings on the island of the Immortal Realm, led by Shugen Yamada Asayemon. Among them are the Ishigakure clan, who share a past with Gabimaru.\n\n\n\nDesperate to find the elixir and escape the island, Gabimaru and his companions face the Tensen in a battle that escalates into an all-out confrontation between humans and immortals!\n\n\n\n(Source: Twin Engine, edited)','\n',char(10)),8.2,'TV',2,0,'24 min','MAPPA','WINTER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166613-uHB8q3D4qbon.jpg','["Action","Adventure","Mystery","Supernatural"]',181897,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(166873,55888,'Mushoku Tensei II: Isekai Ittara Honki Dasu Part 2','Mushoku Tensei: Jobless Reincarnation Season 2 Part 2',replace('Following the faceless god Hitogami''s advice seems to have worked wonders for Rudeus Greyrat. After enrolling into the University of Magic as he was told, Rudeus reunites with his childhood friend Sylphiette, who put a valiant effort into curing his condition. The two grow ever closer together and decide to host a wedding party, inviting the friends they have made over the years to announce and formalize their relationship.\n\n\n\nFor all his recent blessings, however, Rudeus'' troubles are far from over. The research he is helping Shizuka Nanahoshi conduct hits a bottleneck, sending her into a deep slump much like he experienced in his previous life. Furthermore, a letter from his father, Paul, brings complications to Rudeus'' relationships, and Sylphiette still knows next to nothing about his real background. In the face of these issues, Rudeus will have to apply the lessons he has learned in this new world to navigate through the challenges that come with living a life to its fullest.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.3,'TV',2,0,'24 min','Studio Bind','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166873-xO0BRPkmwFll.png','["Adventure","Drama","Ecchi","Fantasy"]',219526,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(167152,56009,'Yuusha Kei ni Shosu: Choubatsu Yuusha 9004-tai Keimu Kiroku','Sentenced to Be a Hero',replace('In a world where heroism is a punishment, Xylo Forbartz, a condemned goddess killer, battles endless hordes of monstrous abominations as part of Penal Hero Unit 9004. Death is no escape, only a cycle of resurrection and relentless combat. But when Xylo encounters a mysterious new goddess, their unlikely alliance sparks a rebellion that could shatter the chains of eternal punishment.\n\n\n\n(Source: Crunchyroll)\n\n\n\nNotes:\n\n- The first episode aired with a runtime of ~58 minutes as opposed to the standard 24 minute long episode.\n\n- Initially scheduled to air in October, 2025','\n',char(10)),8,'TV',2,0,'25 min','Studio KAI','WINTER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx167152-O1pm6DWwifBD.jpg','["Action","Drama","Fantasy"]',169350,1794735120,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(168177,62117,'Zichuan 2','紫川 第2季',replace('To clear suspicion, words are the weakest defense. True power speaks for itself! General Zichuan Xiu, who once single-handedly executed a traitor of the Zichuan clan within the Demon Clan''s stronghold, has risen to command hundreds of thousands of allied troops in the Far East. Supported by the Guardian Elders of the Sacred Temple, this warrior now ascends as the new sovereign of the Eastern lands: The Bright King is crowned! \n\n\n\n(Source: WeTV)','\n',char(10)),0,'ONA',1,0,'20 min','Build Dream','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx168177-BrVpLVEXDiez.png','["Action","Adventure","Fantasy"]',282,1794782800,52,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(169581,56733,'Magical★Explorer: Eroge no Yuujin Chara ni Tensei Shitakedo, Game Chishiki Tsukatte Jiyuu ni Ikiru','Magical Explorer',replace('Few titles are more revered among horndogs-(ahem) connoisseurs of Japanese erotic video games-than Magical Explorer. One day, our smut-loving hero wakes up to find he has been reincarnated into the body of the game’s dreamboat protagonist! Or rather, his hapless comic-relief best friend, Kousuke Takioto. But with his unparalleled knowledge of Magical Explorer and Kousuke’s unorthodox abilities (a scarf that doubles as a fist?), our hero vows to turn the game’s unluckiest loser into its mightiest heartthrob. In this world, nothing is out of reach when you’ve got the know-how!\n\n\n\n(Source: Yen Press)\n\n\n\nNote: Each episode streamed 1 week early on ABEMA and d anime store. The original TV broadcast started on October 4th, 2026.','\n',char(10)),6.9,'ONA',1,6,'24 min','WHITE FOX','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx169581-UlAviVH36Hxi.png','["Action","Adventure","Ecchi","Fantasy","Romance"]',27079,1794782800,13,1795273200,9);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(169966,56853,'I.CINNAMOROLL Animation','I.CINNAMOROLL Animation','',6,'ONA',1,0,'3 min','J.C.STAFF','FALL 2023','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx169966-elyLBCoBAJxx.jpg','["Slice of Life"]',629,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(171018,57334,'Dandadan','DAN DA DAN',replace('This is a story about Momo, a high school girl who comes from a family of spirit mediums, and her classmate Okarun, an occult fanatic. After Momo rescues Okarun from being bullied, they begin talking. However, an argument ensues between them since Momo believes in ghosts but denies aliens exist, and Okarun believes in aliens but denies ghosts exist.\n\n\n\nTo prove to each other what they believe in is real, Momo goes to an abandoned hospital where a UFO has been spotted and Okarun goes to a tunnel rumored to be haunted. To their surprise, they each encounter overwhelming paranormal activities that transcend comprehension. Amid these predicaments, Momo awakens her hidden power and Okarun gains the power of a curse to overcome these new dangers! Their fateful love begins as well!?\n\n\n\nThe story of the occult battle and adolescence starts!\n\n\n(Source: Crunchyroll) \n\n\n\nNotes: \n\n- Worldwide premiere of Episode 1 before the Japanese television premiere occurred at Anime Expo July 6, 2024. \n\n- Episodes 1-3 titled as DAN DA DAN: FIRST ENCOUNTER was pre-screened in advance in theaters on August 31, 2024 in Asia, September 7, 2024 in Europe and September 13, 2024 in North America. The regular TV broadcast began October 4, 2024.','\n',char(10)),8.3,'TV',2,0,'24 min','Science SARU','FALL 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx171018-60q1B6GK2Ghb.jpg','["Action","Comedy","Drama","Romance","Sci-Fi","Supernatural"]',399380,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(171627,57555,'Chainsaw Man: Reze-hen','Chainsaw Man – The Movie: Reze Arc',replace('Denji became “Chainsaw Man”, a boy with a devil’s heart, and is now part of Special Division 4’s devil hunters. After a date with Makima, the woman of his dreams, Denji takes shelter from the rain. There he meets Reze, a girl who works in a café.\n\n\n\n(Source: MAPPA CHANNEL)','\n',char(10)),9,'MOVIE',2,0,'100 min','MAPPA','SUMMER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx171627-ZN9D7P46yHnw.png','["Action","Drama","Horror","Romance","Supernatural"]',253925,1794735119,1,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(172192,57612,'Kikansha no Mahou wa Tokubetsu desu 2nd Season','A Returner''s Magic Should be Special Season 2',replace('In a land dominated by the formidable Shadow Worlds, most of humanity has been destroyed. To rescue their planet from impending doom, six brave heroes fight a perilous battle…and fail. But there’s a glimpse of hope when Desir, one of the last mages, is suddenly sent back in time 13 years! Now armed with knowledge of the grim future, can he alter the course of history and save the world?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.9,'TV',1,3,'24 min','Arvo Animation','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx172192-W7P5xEUaxF3y.jpg','["Action","Adventure","Fantasy"]',35866,1794782800,0,1795016700,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(172463,57658,'Jujutsu Kaisen: Shimetsu Kaiyuu - Zenpen','JUJUTSU KAISEN Season 3: The Culling Game Part 1',replace('After the Shibuya Incident, a deadly jujutsu battle known as the Culling Game orchestrated by Noritoshi Kamo erupts across ten colonies in Japan.\n\n\nHaunted by guilt over the mass killings in Shibuya and wary of Sukuna’s interest in Fushiguro, Itadori chooses not to return to Jujutsu High. Instead, he teams up with Choso to exorcise the countless cursed spirits unleashed by Noritoshi Kamo.\nAmid this chaos, the Jujutsu Headquarters revokes Yuji Itadori’s suspended death sentence and appoints special-grade sorcerer Yuta Okkotsu as his executioner. \n\n\nNewly awakened modern sorcerers and resurrected ancient ones,  now fighting as players in the Culling Game, collide with conflicting motives, driving the world once more toward an age ruled by jujutsu.\n\n\n(Source: TOHO Animation)','\n',char(10)),8.6,'TV',2,0,'24 min','MAPPA','WINTER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx172463-LnXqHzt74SJL.jpg','["Action","Drama","Supernatural"]',273878,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(174576,58059,'Tsue to Tsurugi no Wistoria','Wistoria: Wand and Sword',replace('A hard-working boy named Will enters a magic academy in hopes of becoming a great sorcerer. Unfortunately, there''s a fatal flaw in his plan: he lacks the ability to use magic. Amid the cold stares of his classmates and instructors, Will feels discouraged at times, but he presses forward with unwavering determination. He can''t use a wand, but he can wield a sword in his battle to reach the top of a magic-dominated world. He just needs to believe in his own unique strengths and remember the promise he made with someone precious to him...\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7.9,'TV',2,0,'24 min','Actas','SUMMER 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx174576-tpKcHG0eO6CS.jpg','["Action","Comedy","Drama","Fantasy"]',183930,1794735120,12,0,0);
