INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(176301,58514,'Kusuriya no Hitorigoto 2nd Season','The Apothecary Diaries Season 2',replace('Using her wit and vast knowledge of medicines and poisons alike, Maomao played a pivotal role in solving a series of mysteries and conspiracies that plagued the imperial court. Having recently come to terms with the secrets of her parents, she returns to fulfill her normal duties on behalf of the emperor''s highest-ranking consorts. Maomao also works alongside the eunuch Jinshi to better the consorts'' many ladies-in-waiting, including helping them learn to read.\n\n\n\nHowever, with the arrival of a merchant caravan comes a new wave of intrigue. A pattern of strange coincidences involving the visitors and their wares unsettles Maomao, driving her to investigate the puzzling circumstances behind the convoy. As dangers from both outside and within threaten the balance between the imperial concubines, Maomao continues to utilize her cunning and medical expertise to keep the women safe from harm.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.8,'TV',2,0,'24 min','TOHO animation STUDIO','WINTER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx176301-TIGmldLffQGX.jpg','["Drama","Mystery"]',218048,1794735120,24,0,0);
