INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(176496,58567,'Ore dake Level Up na Ken: Season 2 - Arise from the Shadow','Solo Leveling Season 2 -Arise from the Shadow-',replace('Mastering his new abilities in secret, Jin-U must battle humanity''s toughest foes to save his mother.\n\n\n\n(Source: Crunchyroll News)','\n',char(10)),8.4,'TV',2,0,'24 min','A-1 Pictures','WINTER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx176496-9BDMjAZGEbq4.png','["Action","Adventure","Fantasy"]',322252,1794735119,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(177709,58939,'SAKAMOTO DAYS','SAKAMOTO DAYS',replace('When Sakamoto meets Aoi, the convenience store clerk, it’s love at first sight — and just like that, he retires.\n\n\n\nSakamoto gets married, has a daughter, opens a mom-and-pop store in a quiet town, and completely transforms … into a plus-size man. To ensure a peaceful life with his beloved family, the legendary ex–hit man bands together with comrades to face off against the looming threat of assassins.\n\n\n\n(Source: Netflix TUDUM)\n\n\n\nNote: The series streamed a week in advance on Netflix Japan starting with episode 2 released alongside episode 1.','\n',char(10)),7.6,'ONA',2,0,'24 min','TMS Entertainment','WINTER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx177709-e5Qx6RlsBgD5.png','["Action","Comedy"]',229048,1794735120,11,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(178025,59062,'Gachiakuta','Gachiakuta',replace('A boy lives in a floating town, where the poor scrape by and the rich live a sumptuous life, simply casting their garbage off the side, into the abyss. When he’s falsely accused of murder, though, his wrongful conviction leads to an unimaginable punishment—exile off the edge, with the rest of the trash. Down on the surface, the cast-off waste of humanity has bred vicious monsters, and to travel the path to vengeance against those who cast him into Hell, a boy will have to become a warrior…\n\n\n\n(Source: Kodansha USA)','\n',char(10)),8.2,'TV',2,0,'24 min','bones film','SUMMER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx178025-cWJKEsZynkil.jpg','["Action","Drama","Fantasy"]',269607,1794735119,24,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(178083,59088,'Tokyo Revengers: Santen Sensou-hen','Tokyo Revengers: War of the Three Titans Arc','Sequel to Tokyo Revengers: Tenjiku-hen.',7.7,'TV',1,5,'24 min','LIDENFILMS','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx178083-bg7pg6TCHwtG.jpg','["Action","Drama","Romance","Supernatural"]',40246,1794782800,13,1795193580,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(178788,59192,'Kimetsu no Yaiba: Mugenjou-hen Movie 1 - Akaza Sairai','Demon Slayer: Kimetsu no Yaiba Infinity Castle',replace('Tanjiro Kamado – a boy who joined an organization dedicated to hunting down demons called the Demon Slayer Corps after his younger sister Nezuko was turned into a demon.\n\n\n\nWhile growing stronger and deepening his friendships and bonds with fellow corps members, Tanjiro has battled many demons with his comrades – Zenitsu Agatsuma and Inosuke Hashibira. Along the way, his journey has led him to fight alongside the Demon Slayer Corps’ highest-ranking swordsmen, the Hashira, including Flame Hashira Kyojuro Rengoku aboard the Mugen Train, Sound Hashira Tengen Uzui within the Entertainment District, as well as Mist Hashira Muichiro Tokito and Love Hashira Mitsuri Kanroji at the Swordsmith Village.\n\n\n\nAs the Demon Slayer Corps members and Hashira engaged in a group strength training program, the Hashira Training, in preparation for the forthcoming battle against the demons, Muzan Kibutsuji appears at the Ubuyashiki Mansion. With the head of the Demon Corps in danger, Tanjiro and the Hashira rush to the headquarters but are plunged into a deep descent to a mysterious space by the hands of Muzan Kibutsuji.\n\n\n\nThe destination of where Tanjiro and Demon Slayer Corps have fallen is the demons’ stronghold – the Infinity Castle. And so, the battleground is set as the final battle between the Demon Slayer Corps and the demons ignites.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.6,'MOVIE',2,0,'155 min','ufotable','SUMMER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx178788-zm3gtpB9TpRt.jpg','["Action","Adventure","Drama","Fantasy","Supernatural"]',209010,1794735120,1,0,0);
