INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(178868,59204,'Magic Knight Rayearth (2026)','Magic Knight Rayearth (2026)',replace('Hikaru Shidou, Umi Ryuuzaki, and Fuu Hououji aren''t from Cephiro. While on a school field trip to the Tokyo Tower, the three girls'' minds are on anything but different worlds filled with magic and wonder. That is, until Princess Emeraude, the Pillar of Cephiro, cries out for the Magic Knights to save her world--and that just happens to be those three!\n\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.8,'TV',1,3,'23 min','E&H Production','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx178868-mfp0HIHNJNAm.jpg','["Adventure","Fantasy","Mahou Shoujo","Mecha"]',12556,1794782800,0,1795013160,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(179860,59308,'Aikatsu Academy! Animation PVs','アイカツアカデミー！アニメーションPVs',replace('Animated promotional videos for the Aikatsu franchise''s virtual YouTuber project, Aikatsu Academy! posted on the Streaming Club''s YouTube channel.\n\n\n\n1) Mankai! Helianthe / 満開！エリオント (16 July 2024)\n\n2) HAPPY REFLECTION (23 November 2024)','\n',char(10)),5.8,'ONA',1,0,'1 min','Bandai Namco Pictures','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx179860-24j4KEq0JMbN.jpg','["Music"]',362,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(179876,59415,'DARK MACHINE: The Animation','DARK MACHINE THE ANIMATION',replace('Following his grandfather’s will to “seek out the Senki,” the protagonist Kairi visits Golden Valley, a special Dark Machine economic zone. There, he meets a mysterious girl named Rudra. Dragged into becoming a Dark Machine player by Rudra, Kairi’s talent gradually blossoms over the course of many intense battles.\n\n\n\n(Source: Fuji Creative)\n\n\n\nNote: Part of the "DARK MACHINE" Web3 cross-media project where the story of the Game and its anime adaptation intertwine.','\n',char(10)),5.3,'TV',1,2,'24 min','Production +h','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx179876-Wg62CAzp5WQ1.jpg','["Mecha","Sci-Fi"]',3388,1794782800,11,1794933900,6);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(179916,59410,'Ling Wu Dalu','灵武大陆',replace('Lingwu Continent is a world where spiritual power and martial spirit coexist. A spiritual cultivator can move mountains and rivers with a thought, and a martial artist can tear the world apart with bare hands. Chen Tian, ​​a former genius in Xingchen Town, lost his martial spirit and dried up his spiritual sea after he turned ten.\n\n\n\nSince then, he has become a waste of his family and has been looked down upon by others. In a life-and-death struggle, Chen Tian fell off a cliff and mistakenly entered the formation arranged by the ancient sword emperor. Under the influence of the power of the heavenly book, he awakened his spiritual and martial dual cultivation physique. At the same time, he also obtained a strange memory and a mysterious storage ring.\n\n\n\nFrom then on, he rose from adversity, broke through the reincarnation of the Heavenly Dao Palm, and finally crossed the shackles of the emperor''s calamity and aspired to become the champion of Lingwu Continent!\n\n\n\n(Source: iQIYI)','\n',char(10)),0,'ONA',1,0,'10 min','Soyep','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b179916-DAODMjpQq5ba.jpg','["Action","Adventure","Fantasy"]',388,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(180136,59741,'Tsuihou Sareta Tensei Juukishi wa Game Chishiki de Musou Suru','The Exiled Heavy Knight Knows How to Game the System',replace('Born into a prestigious family of master swordsmen, Elymas Edvaughn’s future shatters when he awakens the so-called “defective” Heavy Knight class. Disowned and cast out, he regains memories of another life—and realizes this world mirrors a VR game he once mastered. Armed with knowledge no one else possesses, he sets out to rewrite his fate and prove the strength of the “weakest” class.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.7,'TV',1,4,'24 min','GoHands','SUMMER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx180136-gtMTCRlOD4OE.jpg','["Action","Fantasy"]',77174,1794782800,26,1795101960,21);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(180894,59787,'Romelia Senki: Maou wo Taoshita nochi mo Jinrui Yabasou dakara Guntai Soshiki Shita','Romelia War Chronicle',replace('Romelia and her party succeed in defeating the Demon King Zelgis, though Prince Henri’s reckless charge forces them into a grueling battle. In the aftermath, Romelia is branded "dead weight" for not fighting directly, and the Prince unilaterally breaks off their engagement. Denied a place in the victory celebrations, Romelia returns home, only to be met with cold indifference from her family and society. Yet, she refuses to break. She has already set her sights on the path that lies ahead.\n\n\n\n(Source: Crunchyroll)\n\n\n\nNote: Romelia War Chronicle streamed 2 days in advance of the TV broadcast on AnimeTimes, U-NEXT, and Netflix beginning October 3, 2026. Regular broadcasting began on October 5, 2026.','\n',char(10)),7.3,'ONA',1,6,'24 min','Atra','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx180894-o3pz4DWFm3je.png','["Adventure","Drama","Fantasy"]',19527,1794782800,12,1795262400,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(181444,59845,'Kaoru Hana wa Rin to Saku','The Fragrant Flower Blooms With Dignity',replace('Chidori High is a boys’ school that takes in the dregs of society with the lowest grades. Next door stands Kikyo Girls’ High, where the wealthy, high-class families send their precious daughters. Chidori second-year Rintarou, who has a fierce face but a gentle heart, is helping at his family’s patisserie when he meets a girl named Kaoruko. The two hit it off right away…but this blissful peace is quickly disturbed when Rintarou discovers that Kaoruko is actually a student at Kikyo. Worse, she doesn’t seem to realize what a huge problem this really is! Will these two be able to forge a path for themselves, and sidestep the traps (metaphorical and literal) laid by their classmates?\n\n\n\n(Source: Kodansha USA)','\n',char(10)),8.4,'TV',2,0,'24 min','CloverWorks','SUMMER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx181444-Ut9DDUZdfHwg.jpg','["Comedy","Drama","Romance"]',221304,1794735120,13,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(182255,59978,'Sousou no Frieren 2nd Season','Frieren: Beyond Journey’s End Season 2',replace('Following the First-Class Mage Exam, the trio—elven mage Frieren, warrior Stark, and first-class mage Fern—gains access to the dangerous Northern Plateau. As the party presses onward toward Aureole, formidable adversaries force Stark to confront his insecurities, solidifying his resolve and his role as the party''s frontliner. Meanwhile, Fern continues to cherish the gifts she has been blessed with throughout her life, each a reminder of those she holds dear.\n\n\n\nFrieren—still honoring her vow to understand humanity—revisits memories of her journey with the Hero''s party and her fleeting encounter with a legendary figure. As she reflects on the passage of time, the elven mage quietly questions whether she has truly changed, yet in the small, almost subtle choices that she makes, there are signs that she might have become more human than she realizes.\n\n\n\n(Source: MAL Rewrite)','\n',char(10)),8.7,'TV',2,0,'24 min','MADHOUSE','WINTER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx182255-butzrqd4I0aC.jpg','["Adventure","Drama","Fantasy"]',237120,1794735119,10,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(183231,60153,'Rilakkuma','RILAKKUMA',replace('Everyday life gets a cozy twist with the laid-back Rilakkuma. Gentle moments of friendship, change, and small joys unfold, turning ordinary moments into something quietly magical—one soft, comforting day at a time.\n\n\n\nIt''s a moment that will make your heart feel lighter and lighter. No matter where you are or what you''re doing, Rilakkuma will be by your side. An exciting new story begins! Experience the stress-free world of Rilakkuma, the relaxed bear who makes being lazy look effortless!\n\n\n(Source: Crunchyroll, Rilakkuma Anime Site, translated)','\n',char(10)),6.5,'TV_SHORT',1,6,'1 min','Production I.G','SPRING 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b183231-z7SgjmXZBcoX.png','["Fantasy","Slice of Life"]',1831,1794782800,0,1795220760,33);
