INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(185646,60534,'Koupen-chan','コウペンちゃん',replace('The story of the series follows the everyday adventures of Koupen-chan and his friends as they enjoy the little things in life.\n\n\n(Source: Crunchyroll News, edited)','\n',char(10)),7,'TV_SHORT',1,7,'2 min','Lesprit','SPRING 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx185646-2eGmsnaSHiLC.jpg','["Slice of Life"]',3381,1794782800,0,1795302000,85);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(185660,60543,'Dandadan 2nd Season','DAN DA DAN Season 2',replace('While the mission to exorcise Jin "Jiji" Enjouji''s family home is underway, things are not going as expected. Momo Ayase narrowly evades an attempted abduction while Ken "Okarun" Takakura and Jiji are ambushed by the Kitou family—the unsettling landlords of the cursed estate. The trio''s efforts threaten the foundation of this enigmatic town shrouded in legends and mysteries.\n\n\n\nAs Momo, Okarun, and Jiji are drawn deeper into the maze of folklore and supernatural entities, they must each utilize their unique powers if they want to survive and unravel the secrets of the uncanny town.\n\n\n\n(Source: MAL Rewrite)\n\n\n\nNote: Worldwide premiere of Episodes 1-3 titled as DAN DA DAN: EVIL EYE before the Japanese premiere was pre-screened in advance in theaters on June 6, 2025 in North America by GKIDS Films and June 7 and 8 in Europe by Piece of Magic Entertainment and Animation Digital Network.','\n',char(10)),8.3,'TV',2,0,'24 min','Science SARU','SUMMER 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx185660-uB8RUMBGovGr.jpg','["Action","Comedy","Drama","Romance","Sci-Fi","Supernatural"]',235646,1794735119,12,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(185725,59967,'Dushi Gu Xian Yi','都市古仙医','Ye Bufan, a junior student, tried to scam a car to raise medical expenses for his mother. Unexpectedly, he encountered a female driver who did not play by the rules. After being hit, Ye Bufan accidentally traveled to a fantasy world and obtained the inheritance of ancient medicine. From then on, he mastered medical skills, practiced martial arts, and won the favor of countless beautiful women.',5.7,'ONA',1,0,'11 min','-','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx185725-wRWiiEMSe81E.jpg','["Action","Adventure","Fantasy","Sci-Fi"]',331,1794782800,250,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(185756,60601,'Tensei Kizoku, Kantei Skill de Nariagaru 3rd Season','As a Reincarnated Aristocrat, I''ll Use My Appraisal Skill to Rise in the World Season 3',replace('The third season of Tensei Kizoku, Kantei Skill de Nariagaru.\n\n\n\nNote: On September 4, 2026, it was announced that GeyeG Pictures would take over the production from studio MOTHER while keeping the same staff.','\n',char(10)),6.8,'TV',1,7,'24 min','GeyeG Pictures','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx185756-xPCl0RyQ7fXD.jpg','["Adventure","Fantasy"]',31107,1794782800,0,1795357800,9);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(186151,60651,'Yu-Gi-Oh! CARD GAME: THE CHRONICLES','Yu-Gi-Oh! CARD GAME: THE CHRONICLES',replace('Yu-Gi-Oh! CARD GAME THE CHRONICLES is a monthly short-anime series showcasing Official Card Game-original card themes. It is an expansion of the demo reel of the same name released the previous year.\n\n\n\nEpisodes and Themes\n\n01-02: Sky Striker Ace\n03-08: The Fallen & The Virtuous\n09-12: Spirit Charmers\n13-16: Magistus\n17-21: Seeker of the Sinful Spoils','\n',char(10)),6,'ONA',1,0,'7 min','KONAMI animation','SPRING 2025','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx186151-oUFvXQXVBMMP.png','["Action","Fantasy"]',3206,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(186495,NULL,'MILGRAM Third Season','MILGRAM The Third Trial',replace('Third season of the interactive collaborative multimedia music project between DECO*27 and Takuya Yamanaka.\n\n\n\nThe list of released videos included in this entry are as follows:\n\n1) Yuno - Life  (ユノ - ライフ), June 18, 2025.\n\n2)  Futa - The Appare March  (フータ - 天晴行進曲), Aug 20, 2025.\n\n3)  Muu - Pain  (ムウ - ペイン), Oct 22, 2025.\n\n4)  Kazui - Camouflage  (カズイ - カモフラージュ), Mar 18, 2026.\n\n5)  Amane - Non-Demonium  (アマネ - なんでもにうむ), May 20, 2026.\n\n6)  Mikoto - Requiem  (ミコト - レクイエム), July 15, 2026.\n\n7)  Kotoko - Drama  (コトコ -ドラマ), Sept 16, 2026.','\n',char(10)),6.6,'MUSIC',1,0,'3 min','OTOIRO','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx186495-D8i7Ru1kCxwL.jpg','["Mystery","Psychological"]',1024,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(186541,60948,'Mezametara Saikyou Soubi to Uchuusen-mochi datta node, Ikkodate Mezashite Youhei to shite Jiyuu ni Ikitai','Reborn as a Space Mercenary: I Woke Up Piloting the Strongest Starship!',replace('Sato Takahiro was an ordinary office worker and hobbyist gamer until the day he woke up on a spaceship–one that strangely resembled a craft from a favorite space-shooter game. With a decked-out ship, a crew full of babes, and a fantastic universe to explore, he''s going to make the most of his good luck and create the life he''s always dreamed of!\n\n\n\n(Source: Seven Seas Entertainment)','\n',char(10)),6.9,'TV',1,7,'24 min','studio A-CAT','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx186541-caYpLsLmbCh7.jpg','["Action","Comedy","Drama","Mecha","Romance","Sci-Fi"]',30855,1794782800,13,1795350600,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(186742,61014,'Toaru Anbu no ITEM','A Certain Dark Item',replace('This is a story of four girls living in the "Dark Side" of Academy City.\n\n\n\nIn Academy City where "ESP" has been recognized as a general science. Behind the peace, there is a Dark Side organization that undertakes missions that cannot be made public.\n\n\n\n"ITEM" is an elite unit consisting of four girls. Takitsubo Rikou is able to read and track the AIM fields emitted by those with abilities. Frenda Seivelun, who excels in combat using explosives and traps.\n\n\n\nKinuhata Saiai, who can manipulate nitrogen at will and plays a defensive role. And one of the 7 Espers that Academy City is proud of: Mugino Shizuri. They live freely in the darkness of the Academy City, and quietly set their sights on their target...!\n\n\n\nThis is a story of encounter, friendship, and darkness that eventually leads to a terrible incident!\n\n\n\n(Source: Kadokawa, translated)','\n',char(10)),6.6,'TV',1,5,'23 min','J.C.STAFF','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx186742-v7yfbefc8fuO.png','["Action","Sci-Fi"]',17462,1794782800,0,1795181400,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(186837,60988,'Tian Guan Ci Fu Duanpian','天官賜福 短片','A series of short episodes.',8.3,'ONA',1,0,'8 min','Red Dog Culture House','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b186837-jFoGG2hbLnlo.jpg','["Action","Adventure","Drama","Fantasy"]',2933,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(187316,61140,'Gensou Suikoden','幻想水滸伝',replace('Two young boys... the hero, Riliu, and his best friend Jowy, were members of a youth brigade of their home nation, the Highland Kingdom - a powerful military nation located in the north-east of the Dunan region.\n\n\n\nThe two of them looked up at the same starry skies, slept in the same tent, and believed in the same future. Once the fighting was over, and the night ended, their daily lives were sure to return.\n\n\n\nContrary to their hopes, the two boys become swept up in the whirlpool of fate, guided by the flames of war.\n\n\n\nThe powerless boys reached for, and grasped immense power. As the 108 stars shine brightly in the murky horizon, the boys step forward, each with their own beliefs for an answer-less question.\n\n\n\n(Source: Official Website, translated)\n\n\n\nNote: The first episode aired with a runtime of ~50 minutes as opposed to the standard 24 minute long episode.','\n',char(10)),5.8,'TV',1,2,'24 min','KONAMI animation','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx187316-jucYCojVTjSY.jpg','["Action","Adventure","Fantasy"]',7998,1794782800,23,1794925800,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(187402,61153,'Tensei shita Dai Seijo wa, Seijo de Aru Koto wo Hita Kakusu','A Tale of the Secret Saint',replace('Fia always dreamed of becoming a knight. Born into a family of knights, she’s the least talented among them, but she still clutches to her hope and trains with everything she has. When the day comes for her to slay a small demon and prove her worth, she ends up face to face with a dragon instead! A deadly injury makes her life flash before her eyes…and she suddenly remembers her former life, when she was a powerful Saint in a bygone era who defeated the Demon King. That life ended in pain because of who she was, making her fear ever becoming a Saint again. Now that the magic from her previous life has been rekindled, she may become a more powerful knight than she ever dreamed–if only she can survive long enough!\n\n\n\n(Source: Seven Seas Entertainment)\n\n\n\nNote: The series streamed a week in advance on ABEMA, Prime Video, and Crunchyroll starting with episode 2 released alongside episode 1.','\n',char(10)),7,'ONA',1,6,'24 min','Felix Film','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx187402-ReKkLwFmMV3q.jpg','["Action","Adventure","Fantasy"]',20519,1794782800,0,1795266000,9);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(187990,63818,'Battle Spirits [Re] Zekkai no Kuu','Battle Spirits [Re] Zekkai No Ku',replace('Keio 3, Hinomoto, Eito. As the Bakumatsu throws Japan into turmoil, young Kuu Bashin dreams of becoming stronger through Standard Battle Spirits. His world changes when he encounters Ajara Zetsu, a wandering samurai and formidable Eternal Battler pursued by anti-shogunate forces. As the worlds of Standard and Eternal Battle collide, Kuu is pulled into Zetsu’s journey—and sets history in motion.\n\n\n(Source: Crunchyroll)','\n',char(10)),5.2,'TV',1,2,'24 min','Bandai Namco Pictures','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx187990-tNyQPmr9TkYi.png','["Action","Fantasy"]',2035,1794782800,0,1794924000,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(188034,61227,'Girls und Panzer: Motto Love Love Sakusen desu!','ガールズ＆パンツァー もっとらぶらぶ作戦です！',replace('A deep dive into the untold daily lives and the inter-school interactions of the Ooarai Girls'' team and the other students (along with the colorful characters that surround them) who are wholeheartedly dedicated to the way of the tank!\n\n\n\n(Source: Official Website, translated)\n\n\n\nNote: The series had a four-part theatrical pre-screening in Japan starting in December 2025. Regular TV broadcast began in October 2026.\n\n\n• Part 1 releasing theatrically on December 26, 2025.\n\n• Part 2 releasing theatrically on January 30, 2026.\n\n• Part 3 releasing theatrically on March 6, 2026.\n\n• Part 4 releasing theatrically on April 10, 2026.','\n',char(10)),7.5,'TV',1,4,'24 min','P.A.WORKS','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx188034-oRwVKBMezOOk.jpg','["Comedy"]',4206,1794782800,12,1795098600,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(189123,61323,'Ao no Hako Season 2','Blue Box Season 2',replace('The second season of Ao no Hako.\n\n\n\nAs Taiki and Chinatsu navigate their evolving feelings, a fractured friendship from the past and fierce competition cloud the road to nationals.\n\n\n\n(Source: Netflix, edited)','\n',char(10)),8.1,'TV',1,7,'24 min','Electric Circus','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx189123-0secXELIhkIW.jpg','["Romance","Slice of Life","Sports"]',53452,1794782800,12,1795332600,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(191656,61578,'Seitokai ni mo Ana wa Aru!','Even the Student Council Has Its Holes!',replace('This is Fujinasu Academy, a private high school with top-achieving students located on the outskirts of town.\n\n\n\nHigh School 1st-Year Ume Mizunoe has excellent grades in Japanese language class and has received multiple literary awards.\nHowever, his terrible grades in the sciences are affecting his ability to move up a grade. To avoid repeating a year, he becomes a member of the student council to improve his academic standing.\n\n\n\nHowever, in the student council, he meets the charismatic yet sullen student council president Kotobuki Hisako, and the scary yet kind and refined treasurer, Arisu Terui. Other members include a cheeky and cute boy, Tan Otori, and Komaro Michinoku, the admin who''s like a small abandoned cat. This is the start of a slapstick, heartful, rom-com about a busy student council full of cute, mismatched, and quirky students!\n\n\n\n(Source: Even the Student Council Has Its Holes! Official Site)','\n',char(10)),7.4,'TV',1,6,'24 min','Passione','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx191656-xFHtxM8SUTdU.png','["Comedy","Ecchi","Slice of Life"]',53543,1794782800,12,1795275000,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(191788,61603,'Aoashi 2nd Season','Aoashi Season 2',replace('Aoi Ashito’s game has now earned him a spot on the A team, but he is quickly overwhelmed by his harsh new reality. Surrounded by elite players like Kuribayashi and Akutsu, practices are just as merciless as the matches. In this U-18 Premier League of powerhouse talent, Ashito must evolve or be crushed, if he’s ever to be acknowledged.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.1,'TV',1,7,'24 min','TMS Entertainment','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx191788-XC6F24LdX6a4.jpg','["Sports"]',28263,1794782800,24,1795334400,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(193414,56903,'MyGO!!!!! Member no Nichijou','MyGO!!!!!メンバーの日常','A series of shorts showing the daily lives of the MyGO!!!!! members.',6.5,'ONA',1,0,'1 min','STUDIO MORIKEN','SUMMER 2022','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx193414-FEAnoXeSVW5H.png','["Comedy","Slice of Life"]',636,1794782800,0,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(194207,62039,'Pan Dorobou','パンどろぼう',replace('Based on Keiko Shibata''s picture book "Pan Dorobou" (Bread Thief). The picture books center on a piece of bread that also steals bread from bakeries in the city.\n\n\n(Source: Anime News Network, edited)','\n',char(10)),0,'TV_SHORT',1,5,'9 min','Shin-Ei Animation','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx194207-7n4M6jOwLdcF.jpg','["Comedy"]',583,1794782800,26,1795167600,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(195516,61987,'Kusuriya no Hitorigoto 3rd Season','The Apothecary Diaries Season 3',replace('In the aftermath of the Shi Clan’s rebellion, things have finally settled down, and Maomao has returned to her old life as a pharmacist in the pleasure district.\n\n\n\nOne day, triggered by a breakfast served at the Verdigris House, Maomao senses an anomaly and begins investigating its true nature.\n\n\n\nMeanwhile, Jinshi, who has revealed his true identity as the Imperial brother and begun to face his heavy responsibilities, is deeply troubled by the final message left by Loulan: a warning of an impending "disaster that will strike the nation."\n\n\n\nTo make matters worse, rumors of a mysterious shrine maiden who deceives the people begin to spread, casting a dark shadow over the country of Li once again.\n\n\n\nFrom the depths of the inner court to the city streets, and across foreign borders—the world grows wider, and the stakes even higher for Maomao and Jinshi.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.5,'TV',1,5,'24 min','OLM','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx195516-MJpUZlOberqH.jpg','["Drama","Mystery"]',113761,1794782800,12,1795183200,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(195571,61999,'Shuiro no Kamen','The Vermilion Mask',replace('"The Mask” gives power to anyone who wears it.\n\n\n\nAt times, that means endless possibility, or unimaginable tragedy…\n\n\n\nPeru, pupil of the legendary mask maker Gaston Roux, becomes controlled by the “Mask of the Warrior God,” and unintentionally kills his friends, and even his own master.\n\n\n\nIn order to prevent this type of tragedy from reoccurring, Peru swears to destroy all of Gaston’s masks that are spread around the world. Confronting the sins that he has committed, he embarks on his voyage. Meeting new friends, then confronting powerful foes. The boy continues on. Until the day he can atone for his sins against his master.\n\n\n\n(Source: The Vermillion Mask English Site)','\n',char(10)),6.7,'TV',1,6,'24 min','100studio','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx195571-fvj7u5GI7BRT.jpg','["Action","Drama","Supernatural"]',18254,1794782800,0,1795249800,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(195604,61967,'Black Clover 2nd Season','Black Clover Season 2',replace('As tyranny engulfs the Clover Kingdom, Asta and the Magic Knights launch a desperate raid on the Spade Kingdom to rescue their squad captains from the Dark Triad. But their mission leads them into a brutal battle against forces beyond anything they’ve ever faced. Now, Asta must rise above impossible odds to protect his friends and honor the promise he made to Yuno.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),8.8,'TV',1,6,'24 min','Studio Pierrot','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx195604-tSZcfKbVqSEG.jpg','["Action","Adventure","Comedy","Fantasy"]',110082,1794782800,0,1795269600,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(198560,62238,'Dungeons & Television','ダンジョン＆テレビジョン',replace('Once upon a time, when television broadcasting itself was an adventure.\n\n\n\nThe invention of the television has made it possible to broadcast any event, however it is still an era where swords and sorcery abound. It has come for the cameras to turn their lens towards the darkness of dungeons, previously only known to adventurers.\n\n\n\nFighting countless monsters and constant equipment problems, the camera-wielding adventurers continued on, hoping to broadcast the first live dungeon capture. What may await them ahead?\n\n\n\n(Source: Official Youtube channel)','\n',char(10)),6.2,'ONA',1,0,'5 min','-','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx198560-Sv9fNr4L8hp3.jpg','["Adventure","Fantasy"]',1664,1794782800,0,0,0);
