INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(199007,62524,'#Zombie Sagashitemasu','#I''m Looking For a Zombie',replace('It may be a ruined city ravaged by zombies, but to Aki and her friends, it’s amazing! Having grown up only hearing stories of the old world and the mysterious outbreak that wiped out humanity, she sets off with her childhood friends in search of her missing father. Things quickly become a fight for survival outside the safety of their small village, yet they’ve never felt more alive.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),5.8,'TV',1,6,'23 min','Studio Comet','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx199007-8R1HsnflnHJE.jpg','["Action","Comedy","Horror","Mystery","Supernatural"]',11942,1794782800,12,1795271400,7);
