INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(199594,62615,'Tetsuryou! meet with Tetsudou Musume','TETSURYO! Meet With Tetsudou Musume',replace('Misaki has often felt the urge to break free from everyday life and set out on a journey somewhere far away. Even though she doesn’t yet know what she wants to become, she longs to find something she can truly be passionate about.\n\n\nAt the start of a new chapter on a lively campus, she meets the members of the Railway Travel Research Club—known as the “Tetsuryo Club.” As her world unfolds along the railway lines, Misaki’s heart begins to race with excitement!\n\n\nAs TETSUDOU MUSUME celebrates its 20th anniversary, the Tetsuryo Club sets off on a journey through the world where the Railway Girls work, in search of moments of wonder.\n\n\n\n(Source: Pony Canyon Anime)','\n',char(10)),6,'TV',1,4,'24 min','East Fish Studio','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx199594-moYKzlfIH03U.jpg','["Slice of Life"]',4444,1794782800,12,1795100400,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(200294,62696,'Choujun! Choujou Senpai','Super Psychic Policeman Chojo',replace('The ultimate police duo is here to keep the peace! Rookie officer Nao just joined the force. She’s got a black belt in judo and earned the nickname “Gorilla” for her insane strength. Then there’s her partner Chojo, who wields every psychic power imaginable. But for a guy who can read minds, he still can’t seem to read the room. Now, these two are taking on crime together in Chinjuku.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.5,'TV',1,2,'24 min','Arvo Animation','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx200294-E6KIgkFaJOfG.jpg','["Comedy","Slice of Life"]',7764,1794782800,12,1794924000,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(200455,62753,'Yowaki MAX Reijou Nano ni, Ratsuwan Konyakusha-sama no Kake ni Notte Shimatta','Even Though I''m a Super Timid Noble Girl, I Accepted the Bet From My Cunning Fiancé',replace('I was reborn as a villainous daughter in a reverse harem otome game. \n\n\n\nAfter being sick with a high fever at the age of 10, Pia Rockwell suddenly remembered her past life as a university student in Japan. But far from going down the villainess route, all this super timid girl wants is to finally use her knowledge from when she was a grad student studying to get her doctorate in paleontology. Her ultimate goal is to become a commoner, excavate fossils, build a museum and then become a curator.\n\n\n\nSo in order to escape the villainess route and avoid being deported by her fiancé during the graduation ball, Pia decides to avoid the upcoming hurt and heartache and asks to break off her engagement to Rufus, the Prime Minister''s son.\n\n\n\nBut will her cunning fiancé let her go that easily?','\n',char(10)),6.7,'TV',1,7,'24 min','Jumondou','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx200455-P3XStRQMJ7Di.png','["Comedy","Fantasy","Romance"]',14339,1794782800,12,1795357800,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(202079,62907,'Oji-san wa Kawaii Mono ga Osuki.','Uncle''s Obsession with Cute Things',replace('By day, Mitsutaka Oji is the handsome, dependable boss everyone admires. By night, he dotes on his favorite mascot, Pugtaro, and indulges his secret obsession with all things cute! He''s kept his double life hidden for years—but one unexpected encounter turns everything upside down and forces Oji to face his feelings head-on!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.3,'TV',1,7,'24 min','LIDENFILMS','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx202079-nwBpDUms0Bab.png','["Comedy","Slice of Life"]',6359,1794782800,12,1795352400,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(202250,62922,'Kashita Maryoku wa [Revo Barai] de Kyousei Choushuu','Magic Repo Man: Dumped by My Party, I’ll Cash In With a Cute Support Fairy to Become the Strongest!',replace('If there''s one thing you can never have enough of in a world of RPG-style swords and sorcery, it''s magic points! Whether you''re fueling spells, techniques, or showing off an incredible ability, you''ve gotta spend those points to do real damage. But what if you run out?\n\n\n\nLent is part of the up-and-coming party known as the “Skypiercers,” and thanks to his unique Gift, he can loan massive amounts of magic to others. No MP? No problem with Lent around! Except, now that his companions have become formidable heroes (thanks to his skill), his usefulness is questioned. Kicked out of the group, Lent is furious…until he discovers a hidden power to his Gift. Now, with his adorably devious fairy partner, he''s going to claw back every last scrap of magic from his former party—with interest!\n\n\n(Source: Seven Seas Entertainment)','\n',char(10)),6.2,'TV',1,6,'23 min','SynergySP','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx202250-mpm2cvr92Au2.jpg','["Action","Adventure","Fantasy"]',27020,1794782800,0,1795278600,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(202851,63240,'Fanren Xiu Xian Zhuan Di Wu Ji','凡人修仙传 第五季',replace('The fifth season of Fanren Xiu Xian Zhuan.\n\n\n\nNote: Includes Episodes 177-228.','\n',char(10)),7.5,'ONA',1,6,'20 min','Original Force','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx202851-iHwg4I1NdfMx.jpg','["Action","Adventure","Fantasy"]',607,1794782800,52,1795230000,25);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(202957,63042,'Meitantei Precure!','Star Detective Precure!',replace('Anna Akechi is a second-year junior high student living in Makoto Mirai Town. On her 14th birthday, she has a chance encounter with a fairy named Pochitan, and a magical pendant caused her to travel back in time from 2027 to 1999! In the Makoto Mirai Town 28 years in the past, Anna meets Mikuru Kobayashi, a girl her age who wants to become a great detective.\n\n\n\nMeanwhile, people in town are in trouble as their prized possessions are being stolen from under their noses - the cause being a group of Phantom Thieves. To stop them, Anna and Mikuru turn into Precures! Maybe if they solve these mysteries, Anna can find her way back to her own time?\n\n\n\n(Source: Official Website, translated)','\n',char(10)),7.6,'TV',1,7,'24 min','Toei Animation','WINTER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx202957-fxZGgJTvwXzP.jpg','["Mahou Shoujo","Mystery"]',6983,1794782800,51,1795303800,42);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(203275,63045,'Demons'' Crest','Devils'' Crest',replace('Sixth-grader Yuuma Ashihara and his twin sister, Sawa, are playing Actual Magic, a brand-new virtual reality MMORPG, when it suddenly begins fusing with the real world. Amid all the chaos and confusion, it becomes clear that death is lurking around every corner, including when Yuuma runs into his classmate Sumika. Before, she was one of the cutest girls in his class, but she’s since undergone a terrible metamorphosis—into one of the game’s horrifying monsters! From the author of Sword Art Online and Accel World comes a story beyond VR and AR, where gaming and reality are one and the same…and staying alive is just the beginning!\n\n\n\n(Source: Yen Press)','\n',char(10)),5.5,'ONA',1,5,'24 min','Production I.G','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b203275-YyNHygkzIjMC.jpg','["Action","Adventure","Fantasy"]',11646,1794782800,0,1795176000,4);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(203473,63053,'Kyoufu Collector','HORROR COLLECTOR',replace('Urban legends come to life…Everyone’s heard an urban legend before, but few have ever come face-to-face with one. These phenomena are everywhere, existing in the shadows of reality. More and more of them have been appearing in the wake of the faceless kid sighted all over Japan. If you see her or one of the urban legends she brings―pray the boy in the red hood finds you before it’s too late. You won’t stand a chance on your own. But with his help, you may just live to see another day…\n\n\n\n(Source: Yen Press)','\n',char(10)),5.1,'TV',1,6,'25 min','Studio Palette','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b203473-pzyaqV432Qko.jpg','["Horror","Mystery","Supernatural"]',7318,1794782800,12,1795272300,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(203490,63061,'Uchi no Otouto-domo ga Sumimasen','Please Excuse My Younger Brothers',replace('The manga centers on high school student Ito Hazui. During her spring break at the end of her first year of high school, Ito''s mother remarries, and Ito moves to live with her new family, becoming Ito Narita. Upon arriving at her new house, Ito is shocked to learn she now has four younger step-brothers. Ito tries her hardest to get along with all of the new members of her family, but the eldest brother Gen is a bit cold to her. However, under his aloof facade, he occasionally shows his kindness.\n\n\n\n(Source: Anime News Network)','\n',char(10)),6.9,'TV',1,5,'24 min','Lay-duce','SUMMER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx203490-YQXiymUiDQNA.jpg','["Comedy","Romance","Slice of Life"]',13694,1794782800,24,1795186800,20);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(204011,63098,'PSYЯEN','PSYREN',replace('One day, high schooler Ageha Yoshina picks up a mysterious “red phone card” left behind in a public telephone booth.\nA few days later, his childhood friend and classmate, Sakurako Amamiya—who possessed the same card—suddenly vanishes without a trace. In search of her, Ageha finds himself drawn into the rumors surrounding a nationwide string of mysterious disappearances, said to be the work of a secret organization known only as “Psyren.”\n\n\nWhen he accesses the group, a deadly game begins—one that will change his fate forever.\n\n\n\n(Source: PSYЯEN Official Site)','\n',char(10)),7,'TV',1,1,'24 min','Satelight','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx204011-j45RZoqYbdZK.jpg','["Action","Adventure","Sci-Fi"]',24663,1794782800,0,1794837600,6);
