INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(204650,63181,'Tougen Anki: Nikko・Kegon no Taki-hen','TOUGEN ANKI: Nikko Kegon Falls Arc',replace('After battling in Kyoto and Nerima, the Rasetsu Academy students have grown stronger. But Yaoroshi leaves the academy to join the Oni Brigade for their "the total eradication of the Momotaro."\n\n\n\nWhen Shiki realizes that they also target noncombatants, he sets out after Yaoroshi to bring him back. Meanwhile in Nikko, there''s a research facility for horrific experiments atop the old Kegon Falls…\n\n\n\n(Source: REMOW)','\n',char(10)),7.3,'TV',1,5,'24 min','Studio Hibari','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx204650-cAQOzQ84Lwk8.png','["Action","Mystery","Supernatural"]',22380,1794782800,12,1795185000,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(204656,63151,'mofusand','mofusand',replace('Shark Meow is an orange tabby kitty who wears a shark suit.\n\nA little clumsy and always taking things at their own cozy pace,\n\nbut every day with their best kitty friends — and the rescued baby kitty, Little Meow —\n\nis filled with unexpected little mishaps and sweet adventures.\n\n\n \nA sunny warm spot in the park, the sparkle of the sea,\n\nsteam rising from freshly roasted sweet potatoes,\n\nthe fluttery feeling of the first snowfall…\n\nThese small everyday moments fill their world with warmth and delight.\n \n\n\nYou can’t help but smile and think, “So true!”\n\nA soft and snuggly kitty anime that brings joy to everyday moments.\n\n\n\n(Source: QTORY Channel)','\n',char(10)),6.5,'ONA',1,3,'1 min','Monster''s Egg','WINTER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b204656-KXjxVB4bBhl8.jpg','["Slice of Life"]',951,1794782800,0,1794956400,46);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(204762,58780,'Enter the Garden','Enter the Garden','Three-part anthology series created by Azuki and Dentsu with creative producer, Gorou Taniguchi.',5.8,'ONA',1,0,'24 min','Qzil.la','SPRING 2024','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx204762-5TGKxC1rY63P.jpg','[]',1367,1794782800,3,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(205896,63292,'Shinja Zero no Megami-sama to Hajimeru Isekai Kouryaku','Full Clearing Another World under a Goddess with Zero Believers',replace('RPG player Makoto Takatsuki is hurled into another world with awful skills and stats. But he soon meets a goddess named Noah, who asks him to become her 1st believer in return for blessings.\n\n\n\n(Source: J-Novel Club)','\n',char(10)),6.5,'TV',1,7,'24 min','HORNETS','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx205896-ElrV8oVAsuax.jpg','["Adventure","Fantasy"]',23539,1794782800,0,1795357800,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(205909,63293,'Hotaru no Yomeiri','Firefly Wedding',replace('On the surface, Satoko has it all—she’s beautiful, the daughter of a nobleman, and at a prime age for marriage. Unfortunately, she is also quite ill and only has a short time left to live. Before she can secure a marriage that will redeem her worth in her family’s eyes, she finds herself the target of the mysterious assassin Shinpei, and her plans are put in jeopardy. In order to save herself, she makes a desperate proposal—of marriage! When it comes to love, however, Shinpei takes “until death do we part” seriously.\n\n\n\n(Source: VIZ Media)','\n',char(10)),7.5,'TV',1,5,'23 min','david production','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx205909-DM0fAzNQulod.jpg','["Drama","Romance"]',55604,1794782800,12,1795185000,7);
