INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(206273,62789,'Yi Zhan Cangqiong','GuAn',replace('In the darkest moment of Celestial Realm, the crippled youth Gu An seized the power of an ancient god amid life-or-death peril. Wielding infinite spiritual energy and a mortal blade, he destroyed evildoers, avenged deep grudges, and struck down the heavens.\n\n(Source: Youku)','\n',char(10)),6.5,'ONA',1,0,'24 min','Shenman Entertainment','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx206273-pqQ1tDkDILJi.jpg','["Action","Fantasy"]',385,1794782800,26,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(206282,62954,'Wangu Zhizun: Li Yunxiao Zhuan','The Eternal Supreme, Li Yunxiao',replace('Once hailed as the third-strongest expert on the Tianwu Continent, Martial Emperor Gu Feiyang found his cultivation trapped at its peak by the very laws of the world. To break through his limits, he orchestrated an audacious plan, sacrificing everything to reincarnate and begin anew.\n\n\n\nReborn as Li Yunxiao, a fifteen-year-old heir of a powerful military family in the Kingdom of Tianshui, he finds himself caught in a storm of invasion, royal succession struggles, and political intrigue. While others fight for power and status, Li Yunxiao sees the bigger picture. Armed with the wisdom and experience of a former Martial Emperor, he calmly overcomes every obstacle on his path toward a single goal: completing the grand design he began in his previous life and laying the foundation for true godhood.\n\n(Source: Bilibili TV)','\n',char(10)),0,'ONA',1,0,'11 min','Dancing CG Studio','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx206282-rTWB9aSqZJyA.jpg','["Action","Adventure","Fantasy"]',363,1794782800,34,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(206401,63337,'FX Senshi Kurumi-chan','FX Fighter Kurumi-chan',replace('University student Kurumi Fukuga has finally fulfilled her long-held desire of starting foreign exchange (FX) trading, motivated by recouping the 20 million yen her late mother lost in trading. "I''ll easily make it back," she thought, but the world she enters can become heaven or hell in an instant. Unrealized losses, loss-cutting, unstoppable fluctuations… but she still wants to buy, sell and make money! With fellow FX addicts Mochiko, Mebuki and Yasuko along for the ride, the market heats up! Joy, despair, joy, despair — this is an endearing, yet slightly risky money game. Can Kurumi and her friends survive this turbulent world?\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.7,'TV',1,4,'24 min','Passione','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx206401-8cAebkI0i8BA.png','["Drama","Slice of Life"]',19650,1794782800,12,1795091400,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(206523,63352,'Onegai AiPri','おねがいアイプリ',replace('The latest entry in the Pretty Series franchise and a new chapter in the AiPri series.\n\n\n\nNote: Relations are provisional and will be updated when more info is announced.','\n',char(10)),5.8,'TV',1,7,'24 min','OLM','SPRING 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx206523-2IaJCk4R7i63.jpg','["Music"]',862,1794782800,0,1795307400,34);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(206774,63381,'Mouse Cursor de Genjitsu wo Sousa Dekiru You ni Natta node, Onnanoko wo Ippai Click Shimasu','Now That I Can Control Reality With A Mouse Cursor, I''m Gonna Click Away On The Girls!',replace('What if you could control reality with a mouse cursor?\n\n\n\nOne day during class, Takumi— an otaku — notices his mouse cursor has sprung out of the screen.\n\n\n\nPanicked, he asks his childhood friend Mone, sitting next to him, to take a look, only to be brushed off...\n\n\n\nOnce Takumi realizes he could actually control it himself, he uses the mouse cursor— visible only to him— to slip it in between Mone''s clothes and starts clicking away...\n\n\n\nHere''s Japan’s (probably) first new genre of romcom, "Clicking Away at a Gyaru Who''s Mean to Otakus with a Mouse Cursor"!\n\n\n\n(Source: Official Site)\n\n\n\nNote: Episode 1 receives an advanced distribution on AnimeFesta on September 11th, 2026. The start date reflects the start of the regular series broadcasting.','\n',char(10)),5.2,'TV_SHORT',1,7,'6 min','Studio Houkiboshi','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx206774-gXVdrySlLY6y.jpg','["Ecchi","Romance","Supernatural"]',8076,1794782800,8,1795964400,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(206814,63367,'Dragon Ball Super: Beerus','Dragon Ball Super: Beerus',replace('Several years have passed since the fierce battle against Majin Buu, and Earth has finally regained a brief moment of peace. At the same time, Beerus, the God of Destruction, awakens from his long, deep sleep.\n\nEven Kai and Supreme Kai, aware of Beerus''s overwhelming power to destroy entire planets, watch his awakening with great fear… Meanwhile, Beerus hears rumors of a Saiyan who defeated Frieza—and suddenly appears before Goku.\n\nTargeted by Beerus, the strongest being in the universe, Earth is in grave danger. Thus begins an earth-shattering cosmic battle between the God of Destruction and Goku and his alliesa—a conflict that will shake the entire universe.\n\n\n\n(Source: Official Site)\n\n\n\nNote: “Enhanced” edition of Dragon Ball Super, featuring a large volume of newly added and redrawn cuts, a reconstructed narrative, and updated visuals for a more immersive and faithful representation of Akira Toriyama’s original manga.','\n',char(10)),8,'TV',1,7,'23 min','Toei Animation','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx206814-PVVzRbf1IQpe.jpg','["Action","Adventure","Sci-Fi"]',31855,1794782800,0,1795356960,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(206949,63382,'Kyouran Reijou Nia Liston','Nia Liston: The Merciless Maiden',replace('A great hero lies undefeated on her deathbed, regretting that she never found a foe who could take her down. She never intended to meet her fate anywhere other than on the battlefield, and her peaceful demise has her wishing desperately that things could have been different... But when she suddenly comes to in the body of the young, frail Nia Liston, she’s got an all-new fight ahead of her. Nia is a sickly child, meaning she has a long way to go before she’s in fighting form. Now that she’s been given a second shot at life, however, she’s determined to get what she wants. She’s going to live—and die—for battle this time! Make way for the Merciless Maiden!\n\n\n\n(Source: J-Novel Club)','\n',char(10)),7.4,'TV',1,2,'24 min','KONAMI animation','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx206949-4HYI3YuP0eLI.png','["Action","Fantasy"]',30963,1794782800,25,1794918360,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(207084,63396,'Onee-chan Gokko','Playing Sister',replace('In the distant future, on the outskirts left behind by the rapid concentration of advanced science and technology in urban areas, lies a remote mountain village known as Kagami Village.\n\n“Behave yourself, or a Double will come for you.”\n\nSuch old folklore still lingers in this village.\n\n\n\nAkane Higure, a middle school student living in Kagami Village, has been eagerly awaiting the return of her older sister, Sui Higure, who is finally being discharged from the hospital after a year.\n\nHowever, not long after her sister comes home, Akane receives a single phone call.\n\n\n\n“The girl at home with you… isn’t your sister.”','\n',char(10)),7,'ONA',1,0,'25 min','Studio Gohan','WINTER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b207084-5ERIoIDjU76C.jpg','["Mystery","Psychological","Supernatural","Thriller"]',1947,1794782800,3,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(207191,63409,'Doumo, Suki na Hito ni Horegusuri wo Irai Sareta Majo desu.','Hello, I am a Witch and my Crush Wants me to Make a Love Potion!',replace('“Make me a love potion.”\n\n\n\nAnd with that single sentence, the Good Witch of the Lake’s secret crush on the dashing Sir Harij ends in heartbreak. Still, when he promises to help her gather the ingredients, Rose is thrilled at the chance to gaze upon a man she’d normally never get to interact with. She learns to brace her pounding heart for their usual stilted conversations…but what is she to do when he inexplicably shows up at her doorstep with bread and a jar of apple butter?\n\n\n\n(Source: Yen Press)','\n',char(10)),7.4,'TV',1,1,'24 min','diomedéa','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx207191-VgkIzfH92WoZ.jpg','["Fantasy","Romance"]',32915,1794782800,12,1794832200,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(207329,63431,'Tsuihou Sareta Cheat Fuyo Majutsushi wa Kimama na Second Life wo Ouka Suru.: Ore wa Buki dake ja Naku, Arayuru Mono ni "Kyouka Point" wo Fuyo Dekiru shi, Ore no Ishi de Itsudemo Kouka wo Kaijo Dekiru kedo, Nokotta Hitotachi Daijoubu?','The Laid-Off Cheat-Granting Mage Enjoys a Second Lease on Life',replace('Rein, an enchanter, is suddenly expelled from his guild one day. But instead of despairing, he declares, “Now I can do anything!” and begins reclaiming the massive number of enhancement points he once poured into his guildmates’ gear, setting off on a brand-new path as an adventurer.\n\n\nGathering around him are people carrying wounds that don’t fade easily: a genius adventurer who shut her heart after her party was slaughtered, a warrior who lost her family, and an assassin raised from childhood to kill. Yet Rein never rejects their pasts or their scars—he accepts them all with bright, straightforward warmth.\n\n\nThe stage is a unique fantasy world where Uzis, slingshots, and even yakuza exist side by side. But in this world, the more people rely on convenient technology, the more their magic weakens, and adventurers grow fragile.\n\n\nIntelligent, vicious monsters roam freely, while in the underworld, outlaws bare their greed and ambition as schemes and betrayals intertwine. In a world where ideals and justice are easily crushed, adventurers fight on with nothing but their magic and their convictions.\n\n\nThis is the story of those who have lost their place in the world finding a new way to live. Rein and his companions’ wild, free-spirited second life begins now!\n\n\n(Source: The Laid-Off Cheat-Granting Mage Enjoys a Second Lease on Life Site)','\n',char(10)),7.4,'TV',1,2,'24 min','P.A.WORKS','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b207329-6VPeZIDfF4Sr.png','["Adventure","Comedy","Fantasy","Slice of Life"]',50193,1794782800,0,1794927600,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(207809,63489,'Sora wa Akai Kawa no Hotori','Red River',replace('After a mysterious hand drags her beneath a puddle, modern Japanese teenager Yuri awakens in the Hittite Empire of the 14th century BCE. Thrust into a deadly struggle for the throne, she joins Prince Kail to battle assassins, outwit royal conspiracies, and survive a world at war. As her exploits earn her renown as the goddess Ishtar, Yuri must choose between her old life and an uncertain future.\n\n\n\n(Source: Crunchyroll)','\n',char(10)),6.2,'TV',1,2,'23 min','Tatsunoko Production','SUMMER 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx207809-cpS7CAyjN7iP.jpg','["Action","Adventure","Drama","Fantasy","Romance"]',12178,1794782800,24,1794933300,20);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(208025,63509,'Dark Summoner to Dekiteiru','I''m Dating a Dark Summoner',replace('Amona’s a dark summoner with demonic powers. Roni’s a devout priest who’s way too uptight. By all rights, they should hate each other. Instead, they end up fast-tracking their enemies-to-lovers arc with a one-night stand that somehow insists on becoming a recurring event. Now they must hide their situationship from the rest of the party while denying their growing attraction to one another, all while dealing with an imp who’s far too invested in their love life.\n\n\n\n(Source: HIDIVE)','\n',char(10)),6.7,'TV_SHORT',1,7,'12 min','AtoriE','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx208025-JKvqWNr8rz8l.jpg','["Comedy","Ecchi","Fantasy","Romance"]',30613,1794782800,12,1795364400,8);
