INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(209219,63712,'Tensei Goblin Dakedo Shitsumon Aru?','So What''s Wrong with Getting Reborn as a Goblin?',replace('Office worker Akira Yagami’s altruistic nature usually gets him the short end of the stick. When he dies after saving a kid from oncoming traffic...he reincarnates in another world as a goblin?! Normally, goblins only live for seven days, but Akira’s newfound powers let him defy the species’ normal life span...and are the key to his path to becoming the strongest goblin ever!\n\n\n\n(Source: Yen Press)\n\n\n\nNote: Tensei Goblin Dakedo Shitsumon Aru? is streaming 1 week in advance of the TV broadcast on ABEMA and Prime Video beginning with episode 2 on October 5th, 2026','\n',char(10)),6.5,'ONA',1,1,'24 min','BAKKKA','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx209219-3yhKlRx0LX3p.jpg','["Action","Adventure","Comedy","Drama","Fantasy","Romance"]',23616,1794782800,0,1794834000,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(209463,63753,'Kanata Kara','From Far Away',replace('On her way home from school one day, Noriko is unexpectedly plunged into a strange and extraordinary fantasy world. Her troubles compound exponentially when she is rescued and befriended by a handsome young man by the name of Izark. He may be brave and courageous, but inside Izark lurks the darkest evil imaginable. And according to an ancient prophecy, Noriko possesses the power to unleash that evil. Now, inexorably bound together, these two unlikely allies must navigate a world both wondrous and hostile.\n\n\n\n(Source: VIZ Media)','\n',char(10)),7,'TV',1,7,'24 min','Studio DEEN','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx209463-Yxk2q10RXgg8.jpg','["Adventure","Fantasy","Romance"]',6445,1794782800,0,1795359600,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(209499,63751,'TANK CHAIR: Sensha Isu','TANK CHAIR',replace('Shizuka takes on the most dangerous of assassin jobs, but she''s not the one doing the killing. Rather, it''s her brother, Nagi, a strong assassin who took a bullet to protect his sister, leaving him in a comatose state and having to use a wheelchair. However, Shizuka has figured out the key to waking her brother up: he must be faced with killing intent! Thus begins a violent journey of recovery, battling the most dangerous foes!\n\n\n\n(Source: Kodansha USA)','\n',char(10)),6.1,'TV',1,7,'25 min','POLYGON PICTURES','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx209499-S0sWFrCpft85.jpg','["Action","Sci-Fi"]',9653,1794782800,0,1795356000,8);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(209502,63754,'Shiotaiou no Satou-san ga Ore ni dake Amai','The Cold Sato-san is Only Sweet to Me',replace('Sato-san is the unattainable flower of the class. She is always cold and curt with classmates, but only I know she''s actually very cute when she smiles, even if she''s not much of a photographer.\n\n\n\nOshio-kun is friendly and lively, but only I know he works at his family''s cafe after school. He does a great job with the cafe''s SNS account, and his mischievous smile makes my heart skip a beat!\n\n\n\nInnocent and sweet, but sometimes frustrating, this is a 120%-pure fluffy story about two people falling in love for the first time.','\n',char(10)),6.8,'TV',1,2,'24 min','Tezuka Productions','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx209502-C81oN8M4Smlo.jpg','["Comedy","Romance"]',24184,1794782800,12,1794920400,7);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(209562,63764,'Vertex Force','VERTEX FORCE',replace('Akira lives a peaceful life with his older sister Haruka and his mother, who runs a cafe. The family however harbors a secret — Haruka has inherited a power from her father called "Engine," and she hides that power from others. Akira on the other hand has not inherited his father''s power, and he has an inferiority complex about it. Amidst this, strange events start happening around the world.\n\n\n\n(Source: Anime News Network)','\n',char(10)),5.5,'TV',1,6,'24 min','Shogakukan Music & Digital Entertainment','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx209562-kQQbTKDuql9p.jpg','["Action","Mecha"]',5093,1794782800,0,1795271400,8);
