INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(210482,61469,'JoJo no Kimyou na Bouken: Steel Ball Run - 2nd & 3rd STAGE','STEEL BALL RUN JoJo''s Bizarre Adventure 2nd - 3rd STAGE',replace('In the 2nd STAGE, a desert crossing spanning roughly 750 miles- the land that Johnny Joestar and Gyro Zeppeli must challenge, is home to the area that is feared as the "Devil''s Palm." In 1875, a threat lurking in said desert wiped out a cavalry of 26 people, eliciting fear from the local native people. As ominous incidents begin to unfold, they are forced to realize that this race is far more than a mere competition. The two press forward, where countless hidden motives collide..\n\n\n\n(Source: Warner Bros. Japan Anime, Netflix Anime, edited)','\n',char(10)),8.6,'ONA',1,5,'23 min','david production','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx210482-P1VNKbqdJ6Zj.jpg','["Action","Adventure","Drama","Mystery","Supernatural"]',52083,1794782800,11,1795161600,9);
