INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(211220,63987,'Li Xiongmao','Raised by Demons: Panda Li',replace('Adapted from a novel by Wen Zhou, this story follows Li Xiongmao, a human boy raised by demons who is sent by his master to leave Black-White Mountain and kill the three enemies responsible for the demons’ downfall. As he searches for the truth, he gradually unravels the mysteries behind the conflict between humans and demons, the secrets of the dynasty, and his own destiny.\n\n\n\n(Source: iQIYI, translated)','\n',char(10)),6.5,'ONA',1,0,'24 min','GARDEN','-','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx211220-fkWS8gCM2rA5.png','["Adventure"]',2186,1794782800,18,0,0);
INSERT INTO "animes" ("id","mal_id","title","title_alt","synopsis","score","type","status","schedule_day","duration","studio","release_season","poster_url","genres_json","popularity","updated_at","episodes_total","next_airing_at","next_airing_ep") VALUES(211778,64084,'Sekai Saikyou no Majo, Hajimemashita','The World''s Strongest Witch',replace('After using her SSS-Rank skill, Internet, to crush her former family’s ambitions, Lorna is free to travel the world. Her next stop is the port town of Aquas, where she hopes to see the sights and chow down on some fresh seafood. But when she arrives, the place is on the brink of destruction thanks to a certain Weekly Quest… Good thing Lorna has the gods on her side!\n\n\n\n(Source: Crunchyroll)','\n',char(10)),7,'TV',1,3,'24 min','Bridge','FALL 2026','https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx211778-0MXK5HqVFBYH.jpg','["Action","Comedy","Fantasy"]',22475,1794782800,0,1795006800,7);
