PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE animes (
  id INTEGER PRIMARY KEY,
  mal_id INTEGER,
  title TEXT NOT NULL,
  title_alt TEXT,
  synopsis TEXT,
  score REAL,
  type TEXT,
  status INTEGER NOT NULL,
  schedule_day INTEGER DEFAULT 0,
  duration TEXT,
  studio TEXT,
  release_season TEXT,
  poster_url TEXT,
  genres_json TEXT,
  popularity INTEGER DEFAULT 0,
  updated_at INTEGER NOT NULL
, episodes_total INTEGER NOT NULL DEFAULT 0, next_airing_at INTEGER NOT NULL DEFAULT 0, next_airing_ep INTEGER NOT NULL DEFAULT 0);
CREATE TABLE episodes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  anime_id INTEGER NOT NULL,
  episode_number INTEGER NOT NULL,
  name TEXT NOT NULL,
  op_start INTEGER,
  op_end INTEGER,
  ed_start INTEGER,
  ed_end INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE(anime_id, episode_number),
  FOREIGN KEY (anime_id) REFERENCES animes(id) ON DELETE CASCADE
);
CREATE TABLE stream_sources (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  episode_id INTEGER NOT NULL,
  type TEXT NOT NULL,
  quality INTEGER NOT NULL,
  url_payload TEXT NOT NULL,
  release_group TEXT NOT NULL DEFAULT 'default',
  sub_kind TEXT NOT NULL DEFAULT 'hardsub-id',
  duration_sec INTEGER DEFAULT 0,
  file_size_bytes INTEGER DEFAULT 0,
  fail_count INTEGER DEFAULT 0,
  cooldown_until INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  UNIQUE(episode_id, type, quality, release_group),
  FOREIGN KEY (episode_id) REFERENCES episodes(id) ON DELETE CASCADE
);
CREATE TABLE source_telemetry_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source_id INTEGER NOT NULL,
  reason TEXT NOT NULL,
  ip_hash TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  UNIQUE(source_id, ip_hash),
  FOREIGN KEY (source_id) REFERENCES stream_sources(id) ON DELETE CASCADE
);
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  name TEXT NOT NULL,
  photo_url TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE user_sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  generation INTEGER NOT NULL DEFAULT 1,
  current_token_hash TEXT UNIQUE NOT NULL,
  previous_token_hash TEXT,
  rotated_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  is_revoked INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE user_histories (
  user_id TEXT NOT NULL,
  anime_id INTEGER NOT NULL,
  episode_id INTEGER NOT NULL,
  progress_sec INTEGER NOT NULL,
  max_progress_sec INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, episode_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (anime_id) REFERENCES animes(id) ON DELETE CASCADE,
  FOREIGN KEY (episode_id) REFERENCES episodes(id) ON DELETE CASCADE
);
CREATE TABLE user_bookmarks (
  user_id TEXT NOT NULL,
  anime_id INTEGER NOT NULL,
  pinned INTEGER DEFAULT 0,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, anime_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (anime_id) REFERENCES animes(id) ON DELETE CASCADE
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE catalog_meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at INTEGER NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_animes_status_pop ON animes(status, popularity DESC);
CREATE INDEX idx_animes_sched_pop ON animes(schedule_day, popularity DESC);
CREATE INDEX idx_animes_updated ON animes(updated_at DESC);
CREATE INDEX idx_episodes_anime ON episodes(anime_id, episode_number ASC);
CREATE INDEX idx_sources_ep ON stream_sources(episode_id, is_active);
CREATE INDEX idx_telemetry_created ON source_telemetry_events(created_at);
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_sessions_user ON user_sessions(user_id, is_revoked, rotated_at ASC);
CREATE INDEX idx_sessions_prev_hash ON user_sessions(previous_token_hash);

CREATE TABLE IF NOT EXISTS catalog_episodes (
  slug TEXT PRIMARY KEY,
  anilist_id INTEGER,
  title TEXT NOT NULL,
  romaji_title TEXT,
  episode INTEGER NOT NULL DEFAULT 1,
  poster_url TEXT NOT NULL DEFAULT '',
  banner_url TEXT NOT NULL DEFAULT '',
  synopsis TEXT NOT NULL DEFAULT '',
  streams_json TEXT NOT NULL DEFAULT '[]',
  is_recommended INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_catalog_title ON catalog_episodes(title);
CREATE INDEX IF NOT EXISTS idx_catalog_anilist ON catalog_episodes(anilist_id, episode);
CREATE INDEX IF NOT EXISTS idx_catalog_rec ON catalog_episodes(is_recommended, updated_at DESC);
